function postSettinginitialization() {
  $('#opensettleWindowbutton').css(
    'display',
    showfastsettleButton ? '' : 'none',
  );
  $('#opentasettleWindowbutton').css(
    'display',
    showfastsettleButton ? '' : 'none',
  );
  $('#openquicksettleWindowbutton').css(
    'display',
    showfastsettleButton ? '' : 'none',
  );
  if (window.usenewtableitemView) {
    if ($('#tableDiv_container').is(':visible')) {
      $('#deptcontainer').css('display', showDepartmentTable ? '' : 'none');
    }
    // showDepartmentTable ? $('.treeviewDiv').css('height', '93%') : $('.treeviewDiv').css('height', '100%')
  } else if (!window.usenewtableitemView) {
    $('#deptcontainer').css('display', showDepartmentTable ? '' : 'none');
    showDepartmentTable
      ? $('.treeviewDiv').css('height', '93%')
      : // : $('.treeviewDiv').css('height', '100%');
        $('.treeviewDiv').css('height', '93%');
  }
  if (window.usenewtableitemView) {
    $('#tableDiv_container').css('height', showDepartmentTable ? '86%' : '93%');
  }
  // Pre Order settings
  $(
    '#takeawayPreordercheckid,#takeawayPreorderchecklabelid,#deliveryPreordercheckid,#deliveryPreorderchecklabelid',
  ).css('display', allowpreOrderstatus ? '' : 'none');
  $('#takeawaypreorderformButton').hide();
  setactiondivButtonsize();

  $('#previewBodyid').html('');
  if (ISBILLINGBYSECTION_ON) {
    $('#previewBodyid').load('Previewbysection.html');
  } else {
    $('#previewBodyid').load('Preview.html');
  }

  if (window.previewscriptLoaded) {
    reloadbillPreviewsettings();
  }
  // Set send payment link button visibility
  $('#sendpaylinkdineinButtonid,#sendpaylinktaButtonid').css(
    'display',
    showsendpaymentlinkButton ? '' : 'none',
  );

  if (showvirtualKeyboard) {
    setTimeout(initializevirtualKeyboard, 1000);
  } else {
    destroyVirtualkeyboard();
  }
}

