async function getBusyTablePostProcess(busyTables) {
  if (busyTables) {
    try {
      if (busyTables && Array.isArray(busyTables) && busyTables.length > 0) {
        const interval = 300;
        busyTables.forEach(async (element, index) => {
          // setTimeout(() => {
          if (window.showbillDetails) {
            // const tableId = `table_${element.table_id}`;
            // const table = $(`#${tableId}`);
            // $(table).click();
            if (window.__IS_MASTER_POS__) {
              ipcRenderer.send(FETCH_BILL_DATA_FOR_CSK_ORDER_TOTAL, {
                table_id: element.table_id,
              });
            } else {
              window.remotefetchBillDataForCskOrderTotal({
                table_id: element.table_id,
              });
            }
          }
          if (element.order_id !== 0 && element.order_id !== undefined) {
            $(`#table_${element.table_id}`)
              .find('#tablebillnumberlabel')
              .text(`Bill No: ${element.order_id}`);
          }
          if (element.amount) {
            $(`#table_${element.table_id}`)
              .find('#tableamountlabel')
              .text(currency + element.amount.toFixed(ROUNDOFF_UPTO));
          }
          // if (showkotnosonTable && element.kot_nos) {
          //    $('#table_' + element.table_id)
          //       .find('#tablekotnosLabelid')
          //       .text(`KOT : ${element.kot_nos}`);
          // }
          addtabletowatchList(
            `table_${element.table_id}`,
            element.actual_in_time,
          );
          // }, index * interval);
        });
      }
    } catch (error) {
      console.error(error);
    }
  }
}

