async function initLoadMenu() {
  if (iskotRunningfortables()) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSaveRemoveAllKOTFirst'),
    );
    $('#syncButton').prop('disabled', false);
    return;
  }
  if (
    typeof temptakeawayorderList !== 'undefined' &&
    temptakeawayorderList &&
    temptakeawayorderList.length > 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSaveRemoveAllKOTFirst'),
    );
    $('#syncButton').prop('disabled', false);
    return;
  }

  if (
    typeof tempdeliveryorderList !== 'undefined' &&
    tempdeliveryorderList &&
    tempdeliveryorderList.length > 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSaveRemoveAllKOTFirst'),
    );
    $('#syncButton').prop('disabled', false);
    return;
  }

  if (
    typeof quickbilltableButton !== 'undefined' &&
    quickbilltableButton &&
    quickbilltableButton.data &&
    quickbilltableButton.data.details &&
    quickbilltableButton.data.details.items &&
    quickbilltableButton.data.details.items.length > 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSaveRemoveAllKOTFirst'),
    );
    $('#syncButton').prop('disabled', false);
    return;
  }

  try {
    const response = await doLoadMenu();
    loadMenuPostProcess(response);
  } catch (error) {
    console.error(
      `Message="Error while getting next kot and bill number"`,
      error,
    );
  } finally {
    $('#syncButton').prop('disabled', false);
  }
}
