async function changeOrderTypePostProcess(reply) {
  if (reply.status == 200) {
    let table_id = reply.data.table_id;
    const desttable_id = reply.data.desttable_id;
    if (window.displaytimeonTables) {
      removetablefromwathersList(currenttableButton.id);
    }
    // if table is self order then remove it
    if (
      reply.data &&
      [TAKEAWAY_FLAG_ID, HOMED_FLAG_ID].includes(reply.data.order_type_flag)
    ) {
      // $('#' + currenttableButton.id).remove();
      $('#' + `table_${reply.data.table_id}`).remove();
      initDeleteTable(`${reply.data.table_id}`);
      removeTableFromSuggestions(reply.data.from_table_name);
    }

    if (reply.createNewTable) {
      addtabletoView(reply.tableDetails);
      sendTableSplittedevent({
        message: 'Order Type Changed',
        tableDetails: reply.tableDetails,
      });
    }
    sendTableChangedevent(reply);
    switch (reply.data.order_type_flag) {
      case TAKEAWAY_FLAG_ID:
        resettaHddata();
        break;
      case HOMED_FLAG_ID:
        resetDeliverydata();
        break;
      case DINEIN_FLAG_ID:
      case VIRTUALTABLE_FLAG_ID:
        // table dept is running then remove table from running orders
        const activeTableDept = $(
          '.activeTableDepartment .menuItemButtoncontentwrapper .department-title-container',
        ).attr('value');
        if (activeTableDept === 'Running Orders') {
          $(`#${currenttableButton.id}`).hide();
        }
        const table = $(`#table_${reply.data.table_id}`);
        table[0].data.details.order_state = '';

        const desttable = $(`#table_${reply.data.desttable_id}`);
        if (desttable && desttable[0] && desttable[0].data) {
          desttable[0].data.details.order_state = 'Placed';
        }

        $(`#table_${reply.data.table_id}`).css(
          'background-color',
          TableUtils.Colors.FREE_TABLE,
        );
        resetdineinData();
        resetCurrentabledata();
        resetBilldetails();
        break;
      default:
        break;
    }

    // reset current table
    tableData.set(currenttableButton.id, []);
    $(`#${currenttableButton.id}`).css(
      'background-color',
      TableUtils.Colors.FREE_TABLE,
    );
    currenttableButton.data.details.color = TableUtils.Colors.FREE_TABLE;
    currenttableButton.data.details.items = [];
    currenttableButton.data.details.printBillItems = [];
    currenttableButton.data.details.itemsForItemDiscount = [];

    currenttableButton.data.table_action_flag = TableUtils.State.FREE_TABLE;

    $('#kotTable').find('tr:not(:first)').remove();
    $('#billTable').find('tr:not(:first)').remove();
    window.notifyUser.showMessage(
      'success',
      $.i18n.t('controller:orderController.tableShifted'),
    );
    const eventParams = {
      table_id,
      allitemsRemoved: true,
      message: `KOT Update for ${currenttableButton.data.table_name}`,
      transferItem: true,
      destinationtable: desttable_id,
      kotcreatedAt: currenttableButton.data.details.kotcreatedAt,
    };
    // setTimeout(() => {
    sendKotupdateddevent(eventParams);
    // }, 2000);
    setTimeout(() => {
      $(`#table_${table_id}`).click();
    }, 200);
    // // $(`#table_${table_id}`).click();
    setTimeout(() => {
      $(`#table_${desttable_id}`).click();
    }, 650);
  }
}

