// update payment
window.initUpdatePayment = async (data) => {
  const response = await updatePaymentRequest(data);
  if (response.status === 400) {
    if (response.table_id) {
      $(`#table_${response.table_id}`).click();
    }
    return;
  }
  updatePaymentPostProcess(response);
  if (
    !openCashDrawerOnPaymetWindow &&
    (data.paymentName === 'Cash' || data.paymentName === 'Split')
  ) {
    let openDrawer = true;
    if (data.paymentName === 'Split' && data.payList && data.payList.length) {
      const cashPayment = data.payList.find((p) => p.payment_option === 'Cash');
      if (!cashPayment) {
        openDrawer = false;
      }
    }
    if (openDrawer) {
      openCashDrawerRequest();
    }
  }
};

