function closedayReminderPopup(lastCloseTime) {
  // Simulate time check (replace this with your real check)
  const now = Date.now();

  if (!lastCloseTime || now - lastCloseTime > 24 * 60 * 60 * 1000) {
    // 24 * 60 * 60 * 1000
    $('#closeDayReminderModal').fadeIn();
    $('#closedaytitlefor24hour').show();
    $('#closedaytitleforsettime').hide();
  }

  $('#okCloseDayReminderButton').on('click', () => {
    $('#closeDayReminderModal').fadeOut();
    // Navigate to Close Day Window
    $('#menuManagementIcon').click();
    setTimeout(() => {
      $('#closeDaybuttonid').click();
    }, 200);
  });

  $('#cancelCloseDayReminderButton').on('click', () => {
    $('#closeDayReminderModal').fadeOut();
  });
}

// check day started
async function initCheckDaytarted() {
  console.log(`Message="Check if day is started"`);
  const content = await checkStartDayRequest();
  if (content) {
    console.log(`Message="Day started date=${content.start_day_date}"`);
    if (content.start_day_date) {
      window.start_day_date = content.start_day_date;
    }
    try {
      if (fetchReportAsPerCloseDay && !content.askforStartday) {
        // check day started time and show close day popup
        // closedayReminderPopup(content.start_day_date);
        setTimeout(() => {
          scheduleDayClosePopup(
            content.start_day_date,
            window.storeDetails.day_close_time,
          );
        }, 300);
      }
      // setTimeout(() => {
      askforStartday(content).then((result) => {
        if (!content.askforStartday) {
          initCheckUserShiftStarted({
            store_id: window.storeDetails.store_id,
            tmpos_id: window.storeDetails.tmpos_id,
            shift_start_by_user: window.storeDetails.username,
          });
        }
        //   if (result) {
        //     sendStartdayrequest(result);
        //   }
      });
      // }, 2000);
      setTimeout(() => {
        document.body.style.pointerEvents = 'auto';
      }, 300);
    } catch (error) {}
  }
}

