function setCustomerfrompaymodal(mobile, name) {
  if (name && mobile) {
    const activeTab = $('.mainsectionTabs li a.active').attr('id');
    if (activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
          $('#kotcustomernameField').val(name);
          $('#kotcustomermobileField').val(mobile);
          $('#kotcustomermobileField').val(mobile);
          break;
        case TAKEAWAY_TAB_ID:
          $('#takeawaykotcustomernameField').val(name);
          $('#takeawaykotcustomermobileField').val(mobile);
          $('#takotcustomeraddressField').val(mobile);
          break;
        case QUICK_TAB_ID:
          $('#quickbillkotcustomernameField').val(name);
          $('#quickbillkotcustomermobileField').val(mobile);
          $('#quickkotcustomeraddressField').val(mobile);
          break;
        default:
          break;
      }
    }
    initgetWalletDetails({ phone: mobile });
  }
}

/**
 * Updates the selected customer for a KOT and bill if it is saved.
 */
async function updateCustomer() {
  const activeTab = $('.mainsectionTabs li a.active').attr('id');
  let customer_name;
  let customer_mobile;
  let forQuickbill = false;
  let order_type_flag = 0;
  if (activeTab) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
        if (currenttableButton == undefined) {
          return;
        }
        order_type_flag = 0;
        customer_name = $('#kotcustomernameField').val();
        customer_mobile = $('#kotcustomermobileField').val();
        break;
      case TAKEAWAY_TAB_ID:
        customer_name = $('#takeawaykotcustomernameField').val();
        customer_mobile = $('#takeawaykotcustomermobileField').val();
        if (currenttableButton === undefined) {
          if (customer_mobile) {
            checkifduePayavailable(customer_mobile);
          }
          return;
        }

        // let order_type_flag = currenttableButton.data.order_type_flag;
        order_type_flag = 1;
        break;
      case DELIVERY_TAB_ID:
        customer_name = $('#deliverykotcustomernameField').val();
        customer_mobile = $('#deliverykotcustomermobileField').val();
        let checkIftableIsRunning = window.allTableslist.find(
          (table) =>
            Number(table.table_customer_mobile) === Number(customer_mobile),
        );

        if (
          currenttableButton &&
          currenttableButton.data.details &&
          currenttableButton.data.details.customer &&
          currenttableButton.data.details.customer.phone &&
          customer_mobile == currenttableButton.data.details.customer.phone
        ) {
          checkIftableIsRunning = false;
        }
        if (checkIftableIsRunning) {
          const openOrderConfirmation = await window.Swal.fire({
            title: $.i18n.t('controller:orderController.openOrder'),
            text: $.i18n.t(
              'controller:orderController.customerHaveOpenOrderOpenExisting',
            ),
            showConfirmButton: true,
            showCancelButton: true,
            width: '23em',
            allowOutsideClick: true,
            allowEscapeKey: false,
            confirmButtonText: $.i18n.t('controller:orderController.Yes'),
            cancelButtonText: $.i18n.t('controller:orderController.Cancel'),
            customClass: {
              popup: 'tmbill-swal-pop-up',
              content: 'tmbill-swal-title-class',
              input: 'tmbill-swal-input2',
            },
          });

          if (openOrderConfirmation && openOrderConfirmation.isConfirmed) {
            // openAddStockwindow(item);
            // $('#deliveryclearkotButton').click();
            if (checkIftableIsRunning && checkIftableIsRunning.id) {
              $('#deliverykotTable').find('tr:not(:first)').remove();
              let itemsList = [];
              const items = tempdeliveryorderList;
              switch (checkIftableIsRunning.order_type_flag) {
                case 0:
                  itemsList = transferTableItems({
                    items,
                    orderType: 1,
                    currentTable: currenttableButton,
                    itemsList,
                    tablesbuttonList,
                    tableDeptId: checkIftableIsRunning['mpos_department.id'],
                  });
                  tempdeliveryorderList = [];
                  tableData.set(`table_${checkIftableIsRunning.id}`, itemsList);
                  $(`#table_${checkIftableIsRunning.id}`).click();
                  await sleep(500);
                  $('#kottabID').tab('show');
                  break;
                case 1:
                  // itemsList = temptakeawayorderList;
                  $(`#table_${checkIftableIsRunning.id}`).click();
                  await sleep(500);
                  itemsList = transferTableItems({
                    items,
                    orderType: 2,
                    itemsList,
                  });
                  if (itemsList) {
                    temptakeawayorderList = itemsList;
                    tempdeliveryorderList = [];
                    $('#takeawaykotTab').tab('show');
                    kotCalculation(TAKEAWAY_FLAG_ID);
                  }

                  break;
                case 2:
                  $(`#table_${checkIftableIsRunning.id}`).click();
                  await sleep(500);
                  itemsList = transferTableItems({
                    items,
                    orderType: 3,
                    itemsList,
                  });
                  if (itemsList) {
                    tempdeliveryorderList = itemsList;
                    $('#deliverykotTab').tab('show');
                    kotCalculation(HOMED_FLAG_ID);
                  }
                  break;
              }
            }
          }
        }
        if (currenttableButton === undefined) {
          if (customer_mobile) {
            checkifduePayavailable(customer_mobile);
          }
          return;
        }
        order_type_flag = 2;
        break;
      case QUICK_TAB_ID:
        customer_name = $('#quickbillkotcustomernameField').val();
        customer_mobile = $('#quickbillkotcustomermobileField').val();
        forQuickbill = true;
        break;
      default:
        break;
    }
  }
  // Find if customer exists
  const customer = getCustomer(false, customer_mobile);
  const currentTable = forQuickbill ? quickbilltableButton : currenttableButton;
  if (
    customer_name &&
    customer_mobile
    // &&
    // order_type_flag == currentTable.data.order_type_flag
  ) {
    if (customer) {
      currentTable.data.details.customer = customer;
    } else {
      currentTable.data.details.customer = {
        name: customer_name,
        phone: customer_mobile,
        address_line1: '',
        address_line2: '',
      };
    }
    if (!forQuickbill) {
      const table_id = currenttableButton.id.replace('table_', '');
      const customerupdateData = {
        order_id: currenttableButton.data.details.bill_number,
        customer,
        customer_name,
        customer_mobile,
        table_id,
      };
      const table = window.allTableslist.find((t) => t.id === Number(table_id));
      if (table) {
        table.table_customer_mobile = customer_mobile;
      }
      initUpdateCustomer(JSON.stringify(customerupdateData));
    }
    checkifduePayavailable(customer_mobile);
  } else {
    currentTable.data.details.customer = undefined;
  }
}

