/**
 * Search for a button and fires it
 * @param {Button to search} button_name
 */
async function findelementandFire(button_name, forItem) {
  let button;
  if (button_name != undefined) {
    if (forItem) {
      const itemButton = $(
        `#itemviewContainer button[data-title="${button_name}"]:visible`,
      );

      if (itemButton.length) {
        button = itemButton[0];
      } else {
        itemsbuttonList.forEach((item) => {
          if (item.content == button_name) {
            button = item;
          }
        });
      }
    } else {
      tablesbuttonList.forEach((item) => {
        if (item.content == button_name) {
          button = item;
        }
      });
    }
  }
  return button;
}

// Check if the node was previously clicked if yes
// the check the time passed if it is less than 300 ms
// we'll consider it as double click just for the sake of implementation
function clicknode(event, data) {
  if (lastselectednodeid !== undefined && lastselecttime) {
    const time = new Date().getTime();
    const t = time - lastselecttime;
    if (lastselectednodeid == data.nodeId && t < 300) {
      // custombusiness(data);
      if (data.state.expanded) {
        // TODO collapse children
        collapseNode(data.nodeId);
      } else {
        // TODO expand children
        expandNode(data.nodeId);
      }
    }
  }
  lastselectednodeid = data.nodeId;
  lastselecttime = new Date().getTime();

  //   event.preventDefault();
  //   if (data.nodes && data.nodes.length) {
  //     if (data.state.expanded) {
  //       // TODO collapse children
  //       collapseNode(data.nodeId);
  //     } else if (!data.state.expanded) {
  //       // TODO expand children
  //       expandNode(data.nodeId);
  //     }
  //   }
}

function collapseNode(nodeId) {
  $('#tree').treeview('collapseNode', [nodeId]);
}

function expandNode(nodeId) {
  $('#tree').treeview('expandNode', [nodeId]);
}

/**
 * Add's the click listener to the tree view nodes
 * @param {clicked menu tree item} data
 */
function categoryNodeclicklistener(data) {
  if (data.tags.length > 0) {
    switch (data.tags[0]) {
      case 'sub-category':
        if (data.tags[1]) {
          filterItems(data.tags[1], 2);
        }
        break;
      case 'category':
        if (data.tags[1]) {
          filterItems(data.tags[1], 1, data.tags[2]);
        }
        break;
      case 'root':
        showAllitems();
        break;
      default:
        showAllitems();
        break;
    }
  }
}

/**
 * Filter the items according to the category clickd
 * @param {CLicked Menu item} clicked_item
 */
async function filterItems(clicked_item, type, subcatIds) {
  if (clicked_item && type) {
    let activeOrderType = $('.mainsectionTabs li a.active').attr('orderType');
    // if bar section is enabled
    let productGroupList;
    if (storeDetails.is_bar_section_billing || itemFileterByOrderType) {
      let productGroupValue = [];
      globalproductGroups.map((ele) => productGroupValue.push(ele.id));
      productGroupValue = productGroupValue.join(',');

      const departementData = {};
      const activeTab = $('.mainsectionTabs li a.active').attr('id');

      const isVisible = $('#tablesParentdivclassid').is(':visible');
      if (activeTab && isVisible) {
        switch (activeTab) {
          case DINEIN_TAB_ID:
            Object.assign(departementData, {
              product_groups:
                currenttableButton &&
                currenttableButton.data &&
                currenttableButton.data['mpos_department.product_groups']
                  ? currenttableButton.data['mpos_department.product_groups']
                  : productGroupValue,
            });
            productGroupList = String(departementData.product_groups).split(
              ',',
            );
            break;
          case TAKEAWAY_TAB_ID:
          case DELIVERY_TAB_ID:
            Object.assign(departementData, {
              product_groups: productGroupValue,
            });
            productGroupList = String(departementData.product_groups).split(
              ',',
            );
            break;
          case QUICK_TAB_ID:
            Object.assign(departementData, {
              product_groups: productGroupValue,
            });
            productGroupList = String(departementData.product_groups).split(
              ',',
            );
            if (
              quickbilltableButton &&
              quickbilltableButton.data &&
              quickbilltableButton.data.selectedCustomOrderType
            ) {
              // const activeBillingType =
              //   BillingTypes[quickbilltableButton.data.selectedCustomOrderType];
              const activeBillingType =
                window.orderTypes[
                  Number(quickbilltableButton.data.selectedCustomOrderType)
                ].order_type;
              if (activeBillingType) {
                activeOrderType = activeBillingType
                  .replace(/\s+/g, '')
                  .toLowerCase();
              }
            }
            break;
          default:
            break;
        }
      }
    }

    if (storeDetails)
      switch (type) {
        case 1:
          if (subcatIds) {
            subcatIds = String(subcatIds).split(',');
            if (storeDetails.is_bar_section_billing) {
              itemsbuttonList.forEach((item) => {
                if (
                  (subcatIds.includes(String(item.data.category_ref_ids)) ||
                    item.data.category_ref_ids == clicked_item) &&
                  productGroupList &&
                  productGroupList.includes(String(item.data.product_group))
                ) {
                  $(`#${item.id}`).show();
                } else {
                  $(`#${item.id}`).hide();
                }
              });
            } else if (itemFileterByOrderType) {
              itemsbuttonList.forEach((item) => {
                const orderTypeGroupList = String(
                  item.data.excludePlaforms,
                ).split(',');

                if (
                  (subcatIds.includes(String(item.data.category_ref_ids)) ||
                    item.data.category_ref_ids == clicked_item) &&
                  orderTypeGroupList &&
                  !orderTypeGroupList.includes(String(activeOrderType))
                ) {
                  $(`#${item.id}`).show();
                } else {
                  $(`#${item.id}`).hide();
                }
              });
            } else {
              itemsbuttonList.forEach((item) => {
                if (
                  subcatIds.includes(item.data.category_ref_ids) ||
                  item.data.category_ref_ids == clicked_item
                ) {
                  $(`#${item.id}`).show();
                } else {
                  $(`#${item.id}`).hide();
                }
              });
            }
          } else if (storeDetails.is_bar_section_billing) {
            itemsbuttonList.forEach((item) => {
              const { data } = item;
              if (
                data.category_ref_ids == clicked_item &&
                productGroupList &&
                productGroupList.includes(String(item.data.product_group))
              ) {
                $(`#${item.id}`).show();
              } else {
                $(`#${item.id}`).hide();
              }
            });
          } else if (itemFileterByOrderType) {
            itemsbuttonList.forEach((item) => {
              const orderTypeGroupList = String(
                item.data.excludePlaforms,
              ).split(',');

              if (
                item.data.category_ref_ids == clicked_item &&
                orderTypeGroupList &&
                !orderTypeGroupList.includes(String(activeOrderType))
              ) {
                $(`#${item.id}`).show();
              } else {
                $(`#${item.id}`).hide();
              }
            });
          } else {
            itemsbuttonList.forEach((item) => {
              const { data } = item;
              if (data.category_ref_ids == clicked_item) {
                $(`#${item.id}`).show();
              } else {
                $(`#${item.id}`).hide();
              }
            });
          }
          break;
        case 2:
          if (storeDetails.is_bar_section_billing) {
            itemsbuttonList.forEach((item) => {
              const { data } = item;
              if (
                data.category_ref_ids == clicked_item &&
                productGroupList &&
                productGroupList.includes(String(item.data.product_group))
              ) {
                $(`#${item.id}`).show();
              } else {
                $(`#${item.id}`).hide();
              }
            });
          } else {
            itemsbuttonList.forEach((item) => {
              const { data } = item;
              if (data.category_ref_ids == clicked_item) {
                $(`#${item.id}`).show();
              } else {
                $(`#${item.id}`).hide();
              }
            });
          }
          break;
        default:
          break;
      }
  }
}

