async function addTables() {
  $('#tablesContainer').empty();
  window.tableName_suggestions = [];
  window.dinein_tableName_suggestions = [];
  let increasebuttonSize = false;
  if (tablesList && tablesList.length > 0) {
    tablesList.forEach((item) => {
      if (item.order_type_flag == ONLINEORDER_FLAG_ID) {
        increasebuttonSize = true;
        addOnlineorderTable(item);
      } else {
        addtabletoView(item);
      }
    });
    if (window.showbillDetails || increasebuttonSize) {
      $('.table_container button').css({
        'min-width': '18%',
      });
    }
  } else {
    $('#tablesContainer').append($(NO_TABLES_MESSAGE));
  }
}

