async function initializeOrderWindowDetails(orderwindowData) {
  if (orderwindowData) {
    try {
      if (orderwindowData) {
        window.globalIPAddress = orderwindowData.ipAddress;
        if (window.mastermenuScriptloaded) {
          setIPAddress_fromremote();
        }
        if (orderwindowData.charges) {
          window.defaultOrdercharges = [];
          window.defaultdineinOrdercharges = [];
          window.defaulttakeawayOrdercharges = [];
          window.defaulthomedOrdercharges = [];
          window.defaultquickOrdercharges = [];
          window.orderCharges = [];
          window.orderCharges = orderwindowData.charges;
          if (window.chargesscriptLoaded) readdCharges_fromremote();
        }

        if (orderwindowData.platformCatalogueitems) {
          platformCatalogueitems = orderwindowData.platformCatalogueitems;
        }
        if (orderwindowData.platformCatalogueCategories) {
          platformCatalogueCategories =
            orderwindowData.platformCatalogueCategories;
        }
        if (orderwindowData.modifiers) {
          window.modifiersList = orderwindowData.modifiers;
        }

        if (orderwindowData.items) {
          itemsList = orderwindowData.items;
          window.allItemsList = orderwindowData.items;
          window.optionsList = orderwindowData.options;
          window.modifiersList = orderwindowData.modifiers;
          itemsbuttonList = [];
          addItems().then(() => {
            addautocompleteforItems();
          });
        }
        if (orderwindowData.categories) {
          window.categoriesList = orderwindowData.categories;
          initMenutree(
            orderwindowData.categories,
            clicknode,
            categoryNodeclicklistener,
          );
        }

        if (orderwindowData.outletKitchenDepartments) {
          window.outletKitchenDepartments =
            orderwindowData.outletKitchenDepartments;
        }

        if (orderwindowData.outletProductGroups) {
          window.outletProductGroups = orderwindowData.outletProductGroups;
        }

        if (orderwindowData.departments) {
          window.tableDepartments = [...orderwindowData.departments];
          defaultDepartmentid = 0;
          addDepartmentsContexts(orderwindowData.departments);
          addDepartmentsToView(orderwindowData.departments);
        }

        if (orderwindowData.outletTaxes) {
          window.outletTaxes = orderwindowData.outletTaxes;
        }

        if (orderwindowData.taxes) {
          window.taxGroupMapping = orderwindowData.taxes;
        }

        if (orderwindowData.itemPrices) {
          window.itemPricesMapping = orderwindowData.itemPrices;
        }

        if (orderwindowData.users) {
          window.users = orderwindowData.users;
        }
        if (orderwindowData.orderTypes) {
          window.orderTypes = orderwindowData.orderTypes;
        }

        if (orderwindowData.platformMappingDetails) {
          window.platformMappingDetails =
            orderwindowData.platformMappingDetails;
        }
        if (orderwindowData.customers) {
          customersList = [];
          customersList = orderwindowData.customers;
          addautocompleteforCustomers();
        }
        if (orderwindowData.deliveryBoys) {
          window.deliveryBoys = orderwindowData.deliveryBoys;
          // addDeliveryboys(orderwindowData.deliveryBoys);
        }

        if (orderwindowData.shortcuts) {
          addShortcutKeylisteners(orderwindowData.shortcuts, {
            toggleMaintabs,
            toggleitemtableView,
            deleteSelectedrow,
            traverseTable,
          });
        }

        window.kitchenDepartments = [];
        if (orderwindowData.kitchenDepartments) {
          window.kitchenDepartments = orderwindowData.kitchenDepartments;
          window.kitchenDepartmentsidsmap = _.chain(window.kitchenDepartments)
            .keyBy('id')
            .mapValues('kitchen_dept_name')
            .value();
        }
        // window.globalproductGroups = [];
        if (orderwindowData.productGroups) {
          window.globalproductGroups = orderwindowData.productGroups;
          if (window.globalproductGroups.length > 0) {
            window.defaultparentGroup = window.globalproductGroups[0];
          }
        }

        if (orderwindowData.tables) {
          currenttableButton = undefined;
          globalcurrenttableId = undefined;
          tablesList = orderwindowData.tables;
          allTableslist = orderwindowData.tables;
          tablesbuttonList = [];
          addTables().then(() => {
            getBusytables();
            addautocompleteforTables();
          });
        }

        if (!window.__IS_MASTER_POS__) {
          $('#syncIndicatorid').hide();
        }
      }
    } catch (error) {
      console.error(error);
    }
  }
}

