function groupDepartmentsbyprinter(
  departments,
  kotItems,
  source = 'atlantic_pos',
) {
  const printerMap = {};

  let printers = [];
  departments.forEach((dept) => {
    // items of this department
    const deptItems = kotItems.filter((item) => item.kitchen_dept === dept.id);
    if (!deptItems.length) return;

    // resolve printers for this department

    if (dept.hasMultipleprinters && Array.isArray(dept.printersList)) {
      printers = dept.printersList.map((p) => p.device_name);
    } else {
      printers = [dept.printer_name || ''];
    }

    printers.forEach((printerName) => {
      // create group ONLY ONCE per printerName
      if (!printerMap[printerName]) {
        if (source === 'captain') {
          printerIndex = _.findIndex(window.printersList, (printer) => {
            if (printer.device_name !== printerName) return false;

            // more_info is null for some entries
            if (!printer.more_info) return false;

            const moreInfo = JSON.parse(printer.more_info);

            // Prefer "captain", fallback to others
            return (
              moreInfo.app_source === 'captain' && printer.action_type === 15
            );
          });
        } else {
          // printerIndex = _.findIndex(window.printersList, {
          //   device_name: printerName,
          // });
          printerIndex = _.findIndex(window.printersList, (printer) => {
            if (printer.device_name !== printerName) return false;

            // more_info is null for some entries
            if (!printer.more_info) return false;

            const moreInfo = JSON.parse(printer.more_info);

            // Prefer "captain", fallback to others
            return (
              (moreInfo.app_source === 'atlantic_pos' ||
                moreInfo.app_source === 'all') &&
              printer.action_type === 15
            );
          });
        }

        printerMap[printerName] = {
          printer_name: printerName,
          departments: [],
          kitchen_dept_name: dept.kitchen_dept_name, // same as your function
          printer: printerIndex >= 0 ? printerIndex : 0,
          items: [],
        };
      }

      // add department once
      printerMap[printerName].departments.push(dept.id);

      // add items (dedupe later)
      printerMap[printerName].items.push(...deptItems);
    });
    if (source === 'captain' && printerIndex === -1) {
      printers.forEach((printerName) => {
        // create group ONLY ONCE per printerName
        // if (!printerMap[printerName]) {
        printerIndex = _.findIndex(window.printersList, {
          device_name: printerName,
        });

        const printer = window.printersList[printerIndex];
        printerMap[printerName] = {
          printer_name: printerName,
          departments: [],
          kitchen_dept_name: dept.kitchen_dept_name, // same as your function
          printer: printerIndex >= 0 ? printerIndex : 0,
          items: [],
        };
        // }

        // add department once
        printerMap[printerName].departments.push(dept.id);

        // add items (dedupe later)
        printerMap[printerName].items.push(...deptItems);
      });
    }
  });

  Object.values(printerMap).forEach((group) => {
    group.departments = _.uniq(group.departments);
    // group.items = _.uniqBy(group.items, 'id');
  });

  return Object.values(printerMap);
}

