/**
 * This method sets the current table details according to the
 * order type flag.
 * @param {Current table bill and KOT Details} tableData
 */
async function setBilldata(currenttableData) {
  window.currentOrderDetails = currenttableData;
  if (currenttableButton == undefined) {
    return;
  }
  if (currenttableData) {
    const table_id = currenttableButton.id.replace('table_', '');
    if (currenttableData.table_id === table_id) {
      let currentbillTable;
      const tabledetails = {
        KOT_Number: currenttableData?.kot_numbers?.join(','),
        Table_Name: currenttableData.table_name,
        Bill_Number: currenttableData.order_id,
        Customer_Mobile: currenttableData.customerMobile,
        Customer_Name: currenttableData.customerName,
      };

      const extraDetails = safeParse(currenttableData?.extra_details);
      if (extraDetails && extraDetails.order_number) {
        Object.assign(tabledetails, {
          Order_Number: extraDetails.order_number,
        });
      }
      window.busyTableData[currenttableData.table_id] = tabledetails;
      let tabtoSwitch;
      switch (currenttableButton.data.order_type_flag) {
        case TAKEAWAY_FLAG_ID:
          {
            isnewtakeawayOrder = false;
            $(`#${TAKEAWAY_BILLTABLE}`).find('tr:not(:first)').remove();
            currentbillTable = TAKEAWAY_BILLTABLE;
            if (window.isTakeawaybilltabEnabled) {
              tabtoSwitch = TAKEAWAY_BILL_TABID;
            }
            activateTab(TAKEAWAY_TABDIV_ID);
          }
          istakeawaywindowSelected = true;
          $('#dboyselectionId').hide();
          $('#sendcustomerdetailstodboylabelCheckid').hide();
          initializeTahdinpermissions({
            type: 'ta',
            event: `ORDER_WINDOW.TAKEAWAY_WINDOW`,
            permissionKey: 'takeaway',
          });

          break;
        case HOMED_FLAG_ID:
          {
            isnewtakeawayOrder = false;
            $(`#${DELIVERY_BILLTABLE}`).find('tr:not(:first)').remove();
            currentbillTable = DELIVERY_BILLTABLE;
            if (window.isDeliverybilltabEnabled) {
              tabtoSwitch = DELIVERY_BILL_TABID;
            }
            activateTab(DELIVERY_TABDIV_ID);
          }
          istakeawaywindowSelected = false;
          $('#senddeliverycustomerdetailstodboyCheckid').show();
          initializehdinpermissions({
            type: 'hd',
            event: `ORDER_WINDOW.HOMED_WINDOW`,
            permissionKey: 'hd',
          });

          break;
        case DINEIN_FLAG_ID:
        case VIRTUALTABLE_FLAG_ID:
          {
            $('#billTable').find('tr:not(:first)').remove();
            currentbillTable = DINEIN_BILLTABLE;
            tabtoSwitch = DINE_BILL_TABID;
            activateTab(DINEIN_TABDIV_ID);
          }
          break;
        default:
          break;
      }

      currenttableButton.data.details.instructions = undefined;
      currenttableButton.data.details.draftprint_status = 0;
      if (currenttableData.tableState) {
        currenttableButton.data.details.color =
          currenttableData.tableState.table_color;
        $(`#${currenttableButton.id}`).css(
          'background-color',
          currenttableData.tableState.table_color,
        );
      }

      if (currenttableData.status == 200) {
        const { bill_number } = currenttableData;
        const { payid } = currenttableData;
        const { kot_id } = currenttableData;
        const { order_id } = currenttableData;
        const { billDetails } = currenttableData;
        const { kotcreatedAt } = currenttableData;
        let order_number;

        if (bill_number != 0) {
          if (window.showbillDetails && order_id != 0) {
            try {
              $(`#${currenttableButton.id}`)
                .find('#tablebillnumberlabel')
                .text(`Bill No: ${order_id}`);
            } catch (error) {}
          }

          const { tableState } = currenttableData;
          if (tableState) {
            $(`#${currenttableButton.id}`).css(
              'background-color',
              tableState.table_color,
            );
            currenttableButton.data.details.color = tableState.table_color;
            currenttableButton.data.table_action_flag =
              tableState.table_action_flag;
          } else {
            $(`#${currenttableButton.id}`).css(
              'background-color',
              TableUtils.Colors.BILL_SAVED,
            );
            currenttableButton.data.details.color =
              TableUtils.Colors.BILL_SAVED;
            currenttableButton.data.table_action_flag =
              TableUtils.State.BILL_SAVED;
          }
        } else if (currenttableData.draftprint_status) {
          currenttableButton.data.details.color =
            currenttableData.tableState.table_color;
          $(`#${currenttableButton.id}`).css(
            'background-color',
            currenttableData.tableState.table_color,
          );
          currenttableButton.data.table_action_flag =
            TableUtils.State.DRAFT_BILL_PRINTED;
        } else {
          // currenttableButton.data.details.color = TableUtils.Colors.KOT_SAVED;
          // $('#' + currenttableButton.id).css("background-color", TableUtils.Colors.KOT_SAVED);
          // currenttableButton.data.table_action_flag = TableUtils.State.KOT_SAVED;
          currenttableButton.data.details.color =
            currenttableData.tableState.table_color;
          $(`#${currenttableButton.id}`).css(
            'background-color',
            currenttableData.tableState.table_color,
          );
          currenttableButton.data.table_action_flag =
            currenttableData.tableState.table_action_flag;
        }

        const kot_numbers = currenttableData.kot_numbers.join(',');
        if (showkotnosonTable) {
          $(`#${currenttableButton.id}`)
            .find('#tablekotnosLabelid')
            .text(`KOT : ${kot_numbers}`)
            .prop('title', `${kot_numbers}`);
        }

        if (window.showCaptainNameOnTable) {
          $(`#${currenttableButton.id}`)
            .find('#tableCreatedByLabelid')
            .text(`${currenttableData.createdBy}`)
            .prop('title', `Captain: ${currenttableData.createdBy}`);
        }

        if (currenttableData && currenttableData.extra_details) {
          const eDetails = safeParse(currenttableData.extra_details);
          if (eDetails && eDetails.order_number) {
            $(`#${currenttableButton.id}`)
              .find('#tableOrdernoLabelid')
              .text(`# ${eDetails.order_number}`)
              .prop('title', `Order Number${eDetails.order_number}`);

            order_number = eDetails.order_number;
            currenttableButton.data.details.order_number = order_number;
            currenttableButton.data.details.extra_details = eDetails;
          }
        }

        if (currenttableData.customerName) {
          $(`#${currenttableButton.id}`)
            .find('#tablecustomernameLabelid')
            .html(currenttableData.customerName);
        } else {
          $(`#${currenttableButton.id}`)
            .find('#tablecustomernameLabelid')
            .html('');
        }

        if (window.showWaiterNameOnTable && currenttableData.waiter) {
          $(`#${currenttableButton.id}`)
            .find('#tablewaiterLabelid')
            .html(currenttableData.waiter);
        }

        currenttableButton.data.details.kot_numbers =
          currenttableData.kot_numbers;

        currenttableButton.data.details.charges = currenttableData.charges;
        if (payid != undefined && payid != 0) {
          currenttableButton.data.details.paymentAdded = true;
        }

        let noofPersons =
          currenttableButton?.data?.details?.persons ??
          currenttableData?.noofPersons ??
          1;
        const { customerName } = currenttableData;
        const { customerMobile } = currenttableData;
        const { ebillCheckstat } = currenttableData;
        const { showonBillstat } = currenttableData;
        const { deliveryboy_id } = currenttableData;
        let { dial_code } = window;
        if (customerName && customerMobile) {
          const customer = getCustomer(false, customerMobile);
          if (customer && customer.dial_code) {
            dial_code = customer.dial_code;
          }
          if (customer) {
            currenttableButton.data.details.customer = customer;
          } else {
            currenttableButton.data.details.customer = {
              name: customerName,
              phone: customerMobile,
              address_line1: '',
              address_line2: '',
            };
          }
        } else {
          currenttableButton.data.details.customer = {};
        }

        const { discount_type } = currenttableData;
        const { discount } = currenttableData;

        if (
          currenttableData.printBillItems != undefined &&
          currenttableData.printBillItems.length > 0
        ) {
          currenttableData.printBillItems.forEach((element) => {
            addBillRow(currentbillTable, element);
          });
        } else {
          if (
            currenttableData.billItems != undefined &&
            currenttableData.billItems.length > 0
          ) {
            currenttableData.billItems.forEach((element) => {
              addBillRow(currentbillTable, element);
            });
          }
        }
        const { order_type_flag } = currenttableButton.data;
        let applyDefaultcharges =
          currenttableData.charges == undefined ||
          (currenttableData.charges &&
            Array.isArray(currenttableData.charges) &&
            currenttableData.charges.length == 0);

        if (
          currenttableData.field2 &&
          Number(currenttableData.field2) &&
          [COMMON_STATE.ACTIVE, COMMON_STATE.INACTIVE].includes(
            Number(currenttableData.field2),
          )
        ) {
          applyDefaultcharges =
            Number(currenttableData.field2) == COMMON_STATE.INACTIVE;
          currenttableButton.data.details.defaultchargesRemoved = true;
        }
        currenttableButton.data.details.waiter =
          currenttableData.waiter || undefined;
        currenttableButton.data.details.waiter_id =
          currenttableData.waiter_id || undefined;
        currenttableButton.data.details.createdBy =
          currenttableData.createdBy || undefined;
        currenttableButton.data.details.draftprint_status =
          currenttableData.draftprint_status;
        currenttableButton.data.details.bill_id = currenttableData.bill_id;
        console.log(
          `Message="currenttableData.payment_mode=${currenttableData.payment_mode}"`,
        );
        if (currenttableData.payment_mode) {
          currenttableButton.data.details.payment_mode =
            currenttableData.payment_mode;
        }
        // checkifduePayavailable(customerMobile);
        switch (order_type_flag) {
          case TAKEAWAY_FLAG_ID:
            $('#showOntakeawayBillcheckid').prop('checked', showonBillstat);
            $('#takeawayebillBillcheckid').prop('checked', ebillCheckstat);
            $('#takeawaynoofpersonsField').val(noofPersons);
            $('#takeawaykotcustomernameField').val(customerName);
            $('#takeawaykotcustomermobileField').val(customerMobile);
            $('#takeawaykotdialcodeFieldid').val(dial_code);

            // Check if order is pre-order
            $('#takeawayPreordercheckid').prop(
              'checked',
              currenttableData.is_pre_order === 1,
            );
            // takeawaypreorderformButton
            $('#takeawaypreorderformButton').css(
              'display',
              currenttableData.is_pre_order === 1 ? '' : 'none',
            );

            if (currenttableButton.data.details.customer) {
              let address = currenttableButton.data.details.customer
                .address_line1
                ? currenttableButton.data.details.customer.address_line1
                : '';
              address += currenttableButton.data.details.customer.address_line2
                ? currenttableButton.data.details.customer.address_line2
                : '';

              $('#takotcustomeraddressField').val(address);
            } else {
              $('#takotcustomeraddressField').val('');
            }

            // if (!istakeawaywindowSelected && deliveryboy_id) {
            //   selectDeliveryboy(deliveryboy_id);
            // } else {
            //   $('#dboyselectionId').prop('selectedIndex', 0);
            // }

            // Add Default charges if any
            // Newly added
            if (applyDefaultcharges) {
              if (
                window.defaulttakeawayOrdercharges != undefined &&
                window.defaulttakeawayOrdercharges.length > 0
              ) {
                currenttableButton.data.details.charges = cloneDeep(
                  window.defaulttakeawayOrdercharges,
                );
              }
            }
            // takeaway
            if (
              window.takeawayOldKotAccess &&
              window.takeawayOldKotAccess.is_visible
            ) {
              if (allowModifyBill && currenttableData.bill_number) {
                $('#saveBilltakeawayoldkotButton').show();
                $('#takeawayoldkotButton').hide();
              } else {
                $('#saveBilltakeawayoldkotButton').hide();
                $('#takeawayoldkotButton').show();
              }
            }
            break;
          case HOMED_FLAG_ID:
            $('#showOndeliveryBillcheckid').prop('checked', showonBillstat);
            $('#deliveryebillBillcheckid').prop('checked', ebillCheckstat);
            $('#deliverynoofpersonsField').val(noofPersons);
            $('#deliverykotcustomernameField').val(customerName);
            $('#deliverykotcustomermobileField').val(customerMobile);
            $('#deliverykotdialcodeFieldid').val(dial_code);

            // Check if order is pre-order
            $('#deliveryPreordercheckid').prop(
              'checked',
              currenttableData.is_pre_order === 1,
            );
            // takeawaypreorderformButton
            $('#deliverypreorderformButton').css(
              'display',
              currenttableData.is_pre_order === 1 ? '' : 'none',
            );

            if (currenttableButton.data.details.customer) {
              let address = currenttableButton.data.details.customer
                .address_line1
                ? currenttableButton.data.details.customer.address_line1
                : '';
              address += currenttableButton.data.details.customer.address_line2
                ? currenttableButton.data.details.customer.address_line2
                : '';

              $('#deliverykotcustomeraddressField').val(address);
            } else {
              $('#deliverykotcustomeraddressField').val('');
            }
            if (deliveryboy_id) {
              selectDeliveryboy(deliveryboy_id);
              const deliveryBoy = window.deliveryBoys.find(
                (d) => d.id === deliveryboy_id,
              );
              if (deliveryBoy) {
                $('#deliveryBoyNamelabelid')
                  .text(deliveryBoy.name)
                  .attr('deliveryBoyId', deliveryboy_id);

                currenttableButton.data.details.delivery_boy_name =
                  deliveryBoy.name;
                currenttableButton.data.details.deliveryboy_id = deliveryboy_id;
              }
            } else {
              $('#deliveryBoyNamelabelid').text('');
              $('#deliveryBoyNamelabelid').removeAttr('deliveryBoyId');
              $('#dboyselectionfordeliveryId').prop('selectedIndex', 0);
            }

            // Add Default charges if any
            // Newly added
            if (applyDefaultcharges) {
              if (order_type_flag === HOMED_FLAG_ID) {
                if (
                  window.defaulthomedOrdercharges != undefined &&
                  window.defaulthomedOrdercharges.length > 0
                ) {
                  currenttableButton.data.details.charges = cloneDeep(
                    window.defaulthomedOrdercharges,
                  );
                }
              }
            }
            // takeaway
            if (
              window.takeawayOldKotAccess &&
              window.takeawayOldKotAccess.is_visible
            ) {
              if (allowModifyBill && currenttableData.bill_number) {
                $('#saveBilltakeawayoldkotButton').show();
                $('#takeawayoldkotButton').hide();
              } else {
                $('#saveBilltakeawayoldkotButton').hide();
                $('#takeawayoldkotButton').show();
              }
            }
            break;
          case DINEIN_FLAG_ID:
          case VIRTUALTABLE_FLAG_ID:
            $('#showOnBillcheckid').prop('checked', showonBillstat);
            $('#ebillBillcheckid').prop('checked', ebillCheckstat);
            $('#noofpersonsField').val(noofPersons);
            $('#kotcustomernameField').val(customerName);
            $('#kotcustomermobileField').val(customerMobile);
            $('#dineinkotdialcodeFieldid').val(dial_code);
            // $('#kotcustomeraddressField').val('');
            if (currenttableButton.data.details.customer) {
              let address = currenttableButton.data.details.customer
                .address_line1
                ? currenttableButton.data.details.customer.address_line1
                : '';
              // address += currenttableButton.data.details.customer.address_line2
              //   ? currenttableButton.data.details.customer.address_line2
              //   : '';

              $('#kotcustomeraddressField').val(address);
            } else {
              $('#kotcustomeraddressField').val('');
            }

            if (
              applyDefaultcharges &&
              window.defaultdineinOrdercharges != undefined &&
              window.defaultdineinOrdercharges.length > 0
            ) {
              if (currenttableButton?.data['mpos_department.section'] == 1) {
                // check if bar section charges is present and remove it
                const filteredCharges = window.defaultdineinOrdercharges.filter(
                  (charge) => {
                    const extraDetails = safeParse(charge.extra_details);
                    return extraDetails.bar_section_billing !== 1;
                  },
                );
                currenttableButton.data.details.charges = filteredCharges;
              } else {
                currenttableButton.data.details.charges =
                  window.defaultdineinOrdercharges;
              }
            }

            // dinein
            if (
              window.dineinOldKotAccess &&
              window.dineinOldKotAccess.is_visible
            ) {
              if (allowModifyBill && currenttableData.bill_number) {
                $('#saveBilloldkotButton').show();
                $('#oldkotButton').hide();
              } else {
                $('#saveBilloldkotButton').hide();
                $('#oldkotButton').show();
              }
            }
            break;
          default:
            break;
        }
        currenttableButton.data.details.bill_number = bill_number;
        currenttableButton.data.details.order_id = order_id;
        currenttableButton.data.details.items = currenttableData.billItems;
        currenttableButton.data.details.printBillItems =
          currenttableData.printBillItems;
        currenttableButton.data.details.itemsForItemDiscount =
          currenttableData.itemsForItemDiscount;

        currenttableButton.data.details.persons = noofPersons;
        currenttableButton.data.details.field2 =
          currenttableData?.billDetails?.field2;
        currenttableButton.data.details.order_note =
          currenttableData?.order_note;

        currenttableButton.data.details.reservation_id =
          currenttableData?.tableState?.reservation_id;

        currenttableButton.data.details.tableReservationDetails =
          currenttableData?.tableReservationDetails;

        applyDiscounttotable(currenttableButton, {
          rate: discount,
          discount_type,
          discount_name: currenttableData.discountTitle || '',
          product_groups: currenttableData.discounted_product_groups,
        });

        currenttableButton.data.details.couponDisountamt =
          currenttableData.couponDisount;
        currenttableButton.data.details.couponDisounttype =
          currenttableData.couponDisounttype;
        currenttableButton.data.details.coupon = currenttableData.coupon;
        currenttableButton.data.details.kotcreatedAt = kotcreatedAt;

        currenttableButton.data.details.remoteKot = currenttableData.remoteKot;
        currenttableButton.data.details.remoteOrder_id =
          currenttableData.remote_order_id;

        if (currenttableData.is_pre_order) {
          currenttableButton.data.details.preorderInfo =
            currenttableData.preorderInfo || undefined;
          currenttableButton.data.details.is_pre_order =
            currenttableData.is_pre_order;
        } else {
          currenttableButton.data.details.preorderInfo = undefined;
          currenttableButton.data.details.is_pre_order = 0;
        }
        currenttableButton.data.details.custom_bill_number =
          currenttableData.custom_bill_number || undefined;

        if (window.displaytimeonTables) {
          addtabletowatchList(currenttableButton.id, kotcreatedAt);
        }

        currenttableButton.data.details.instructions =
          currenttableData.discountInstruction || '';

        if (!currenttableButton.data.details.extra_details) {
          currenttableButton.data.details.extra_details = {};
        }
        billstatusReason = currenttableData.field1 || '';
        if (billDetails) {
          currenttableButton.data.details.due_payment = billDetails.due_payment;
          if (!billDetails.due_payment) {
            currenttableButton.data.details.cust_paid_amount =
              billDetails.cust_paid_amount || undefined;
          } else {
            currenttableButton.data.details.cust_paid_amount = 0;
          }
          currenttableButton.data.details.isBillModified =
            billDetails.isBillModified || undefined;
          currenttableButton.data.details.print_status =
            billDetails.print_status || undefined;
          if (billDetails.extra_details) {
            currenttableButton.data.details.extra_details = JSON.parse(
              billDetails.extra_details,
            );
          }

          if (billDetails.print_status) {
            switch (order_type_flag) {
              case TAKEAWAY_FLAG_ID:
                if (window.takeawayPrintBillAccessLevel === 1) {
                  $('#reprint_n_savetakeawayBillbutton').show();
                  $('#print_n_savetakeawayBillbutton').hide();
                }
                break;
              case HOMED_FLAG_ID:
                if (window.deliveryPrintBillAccessLevel === 1) {
                  $('#reprint_n_savedeliveryBillbutton').show();
                  $('#print_n_savedeliveryBillbutton').hide();
                }

                break;
              case DINEIN_FLAG_ID:
              case VIRTUALTABLE_FLAG_ID:
                if (window.dineinPrintBillAccessLevel === 1) {
                  $('#reprint_n_savebillButton').show();
                  $('#print_n_savebillButton').hide();
                }
                break;
              default:
                break;
            }
          } else {
            switch (order_type_flag) {
              case TAKEAWAY_FLAG_ID:
                if (window.takeawayPrintBillAccessLevel === 1) {
                  $('#reprint_n_savetakeawayBillbutton').hide();
                  $('#print_n_savetakeawayBillbutton').show();
                }
                break;
              case HOMED_FLAG_ID:
                if (window.deliveryPrintBillAccessLevel === 1) {
                  $('#reprint_n_savedeliveryBillbutton').hide();
                  $('#print_n_savedeliveryBillbutton').show();
                }
                break;
              case DINEIN_FLAG_ID:
              case VIRTUALTABLE_FLAG_ID:
                if (window.dineinPrintBillAccessLevel === 1) {
                  $('#reprint_n_savebillButton').hide();
                  $('#print_n_savebillButton').show();
                }
                break;
              default:
                break;
            }
          }

          currenttableButton.data.details.payment_modes =
            billDetails.payment_modes;
          currenttableButton.data.details.instructions =
            billDetails.instructions || '';
          billstatusReason = billDetails.instructions || '';
          orderStatusReason = billDetails.field1 || '';
        } else {
          switch (order_type_flag) {
            case TAKEAWAY_FLAG_ID:
              if (window.takeawayPrintBillAccessLevel === 1) {
                $('#reprint_n_savetakeawayBillbutton').hide();
                $('#print_n_savetakeawayBillbutton').show();
              }
              break;
            case HOMED_FLAG_ID:
              if (window.deliveryPrintBillAccessLevel === 1) {
                $('#reprint_n_savedeliveryBillbutton').hide();
                $('#print_n_savedeliveryBillbutton').show();
              }
              break;
            case DINEIN_FLAG_ID:
            case VIRTUALTABLE_FLAG_ID:
              if (window.dineinPrintBillAccessLevel === 1) {
                $('#reprint_n_savebillButton').hide();
                $('#print_n_savebillButton').show();
              }
              break;
            default:
              break;
          }
        }
        precalculateDetailsCheck(currenttableButton);

        if (order_number && currenttableButton.data.details.extra_details) {
          Object.assign(currenttableButton.data.details.extra_details, {
            ...currenttableButton.data.details.extra_details,
            order_number,
          });
        }

        const orderid = currenttableData.bill_number;
        const orderAmount = currenttableButton.data.details.order_total
          ? currenttableButton.data.details.order_total
          : 0;
        const { field2 } = currenttableButton.data.details;
        // if (accessOfCustomerDisplay) {
        await sendTableClickEventFunction(
          orderAmount,
          orderid,
          field2,
          table_id,
          currenttableButton,
          order_number,
        );
        // }

        activateTab(tabtoSwitch);
        // precalculateDetailsCheck(currenttableButton);
        // sectionWiseOrderCalculation(currenttableButton.data.details);
      } else {
        currenttableButton.data.details.kotcreatedAt = undefined;
        currenttableButton.data.details.bill_number = undefined;
        currenttableButton.data.details.persons = undefined;

        switch (currenttableButton.data.order_type_flag) {
          case TAKEAWAY_FLAG_ID:
            cleartakeawayindata();
            activateTab(TAKEAWAY_KOT_TABID);
            if (currenttableButton.data.details.persons) {
              $(`#takeawaynoofpersonsField`).val(
                currenttableButton.data.details.persons,
              );
            }
            break;
          case HOMED_FLAG_ID:
            cleardeliveryindata();
            activateTab(DELIVERY_KOT_TABID);
            if (currenttableButton.data.details.persons) {
              $(`#deliverynoofpersonsField`).val(
                currenttableButton.data.details.persons,
              );
            }
            break;
          case DINEIN_FLAG_ID:
          case VIRTUALTABLE_FLAG_ID:
            clearDineindata();
            activateTab('tab1');

            if (
              currenttableButton &&
              currenttableButton.data &&
              currenttableButton.data.details
            ) {
              const details = currenttableButton.data.details;

              // Restore customer
              if (details.customer) {
                const customer = details.customer;

                $('#kotcustomernameField').val(customer.name || '');
                $('#kotcustomermobileField').val(customer.phone || '');

                let address = customer.address_line1
                  ? customer.address_line1
                  : '';
                address += customer.address_line2 ? customer.address_line2 : '';

                $('#kotcustomeraddressField').val(address);
              }

              // Restore guests
              if (details.persons) {
                $('#noofpersonsField').val(details.persons);
              }

              // Restore KOT note
              if (details.order_note) {
                $('#kotnoteField').val(details.order_note);
              }
            }
            if (currenttableButton.data.details.persons) {
              $(`#noofpersonsField`).val(
                currenttableButton.data.details.persons,
              );
            }
            break;
          default:
            break;
        }
        showDuepayavaiablemark({ hideall: true });
      }

      const current_table = currenttableButton.id;
      const kotitems = tableData.get(current_table);

      if (kotitems && kotitems.length > 0) {
        currenttableButton.data.details.color = TableUtils.Colors.KOT_HAS_ITEMS;
      }

      if (showPaymentStrip) {
        if (currenttableButton.data.order_type_flag >= 0) {
          switch (currenttableButton.data.order_type_flag) {
            case DINEIN_FLAG_ID:
              $(`#dininpayMode_${currenttableButton.data.details.payment_mode}`)
                .length > 0
                ? $(
                    `#dininpayMode_${currenttableButton.data.details.payment_mode}`,
                  ).prop('checked', true)
                : currenttableButton &&
                    currenttableButton.data.details.bill_number
                  ? $(`#dininpayMode_Other`).prop('checked', true)
                  : $($("input:radio[name='paymentModebutton']")).prop(
                      'checked',
                      false,
                    );
              break;
            case TAKEAWAY_FLAG_ID:
              $(
                `#takeawaypayMode_${currenttableButton.data.details.payment_mode}`,
              ).length > 0
                ? $(
                    `#takeawaypayMode_${currenttableButton.data.details.payment_mode}`,
                  ).prop('checked', true)
                : currenttableButton &&
                    currenttableButton.data.details.bill_number
                  ? $(`#takeawaypayMode_Other`).prop('checked', true)
                  : $($("input:radio[name='paymentModebutton']")).prop(
                      'checked',
                      false,
                    );
              break;
            case HOMED_FLAG_ID:
              $(
                `#deliverypayMode_${currenttableButton.data.details.payment_mode}`,
              ).length > 0
                ? $(
                    `#deliverypayMode_${currenttableButton.data.details.payment_mode}`,
                  ).prop('checked', true)
                : currenttableButton &&
                    currenttableButton.data.details.bill_number
                  ? $(`#deliverypayMode_Other`).prop('checked', true)
                  : $($("input:radio[name='paymentModebutton']")).prop(
                      'checked',
                      false,
                    );
              break;
          }
        }
      }
      // $('#' + currenttableButton.id).css('border', 'solid');
      // $('#' + currenttableButton.id).css('border-width', '3px');
      // $('#' + currenttableButton.id).css('border-color', '#F8BB5D');

      $(`#${currenttableButton.id}`).addClass('selected-table-border');
      // try {
      //   const tree = document.getElementById('tree');

      //   if (tree) {
      //     const selected = tree.querySelectorAll('.node-selected');
      //     if (selected && selected.length > 0) {
      //       selected.forEach((node) => node.classList.remove('node-selected'));
      //     }
      //   }
      // } catch (e) {
      //   console.error(e);
      // }

      $('#takeawayebillBillcheckid').prop('checked', defaultebillCheck);
      $('#ebillBillcheckid').prop('checked', defaultebillCheck);

      // set order state
      if (currenttableData.kot_status) {
        const { kot_status } = currenttableData;
        const allEqual = (arr) => arr.every((v) => v == arr[0]);
        const isAllEqual = allEqual(kot_status);
        if (isAllEqual) {
          const orderState = [
            'Placed',
            'Bumped',
            'Preparing',
            'Ready',
            'Served',
          ];
          const tableId = `table_${currenttableData.table_id}`;
          const orderStateToShow = kot_status[0] - 1;
          if (
            currenttableButton.data.details.order_state &&
            currenttableButton.data.details.order_state !== 'Placed'
          ) {
            $(`#${currenttableButton.id}`)
              .find('#tableorderstatusLabel')
              .html(currenttableButton.data.details.order_state);
          } else {
            $(`#${tableId}`)
              .find('#tableorderstatusLabel')
              .html(orderState[orderStateToShow]);
            currenttableButton.data.details.order_state =
              orderState[orderStateToShow];
          }
        }
      }
    }

    // table is of split bill then only update charges
    if (/-Per-|-Por-|-Part/.test(currenttableData.table_name)) {
      const { charges } = currenttableButton.data.details;
      // updateChargesForSplitTable(charges);
    }

    // save bharatpe qr
    // if (accessOfCustomerDisplay) {
    // const orderid = currenttableData.bill_number;
    // const orderAmount = currenttableButton.data.details.order_total
    //   ? currenttableButton.data.details.order_total
    //   : 0;

    // const { field2 } = currenttableButton.data.details;
    // await sendTableClickEventFunction(
    //   orderAmount,
    //   orderid,
    //   field2,
    //   table_id,
    //   currenttableButton,
    // );
    // }
    // call table click event
    if (
      window.accessOfCustomerDisplay &&
      currenttableData &&
      currenttableData.billItems
    ) {
      const state = {
        total: Number(currenttableButton?.data?.details?.order_total).toFixed(
          window.ROUNDOFF_UPTO,
        ),
        items: currenttableData.billItems,
        billNumber: currenttableData.order_id,
        qrCode: currenttableButton?.data?.details?.field2,
      };

      window.sendStatetolocalcustomerdisplay(state);
    }

    if (
      window.settingsConfig[POSYTUDE_PORT - 1] != undefined &&
      window.settingsConfig[POSYTUDE_PORT - 1].value !== '0'
    ) {
      const orderDetail = {};
      orderDetail.amount = `Total ${storeDetails.currency_code} = ${
        currenttableButton.data.details.order_total
          ? currenttableButton.data.details.order_total
          : 0.0
      }`;
      betteripcRenderer.callMain(
        'IPC_EVENT:SERIAL_PORT:DISPLAY_AMOUNT',
        orderDetail,
      );
    }

    if (allowModifyBill && currenttableData.bill_number) {
      if (window.askPasscodeForModifyBillAfterSave) {
        setTimeout(() => {
          $('#itemviewContainer')
            .find(
              '.menuItemButtoncontentwrapper, .inneritembuttonDiv, img, div, label, i',
            )
            .each(function () {
              $(this).attr('passcode-protected', '1');
              let event;
              if (window.modifybillaftersavePasscodeEvent) {
                event = cloneDeep(window.modifybillaftersavePasscodeEvent);
                Object.assign(event.event_details, {
                  bill_number: currenttableData.order_id,
                  order_id: currenttableData.bill_number,
                });
                // event.event_details.bill_number = currenttableData.order_id;
              }
              $(this).data(event);
            });
        }, 300);
      }
    } else if (window.askPasscodeForModifyBillAfterSave) {
      $('#itemviewContainer')
        .find(
          '.menuItemButtoncontentwrapper, .inneritembuttonDiv, img, div, label, i',
        )
        .each(function () {
          $(this).removeAttr('passcode-protected');
        });
      $('#itemviewContainer').removeAttr('passcode-protected');
    }
    setDefaultebillcheck();
  } else {
    // currentTableButton.data = undefined;
  }
}
