/**
 * Fetches the saved KOT Data
 */
async function fetchBilldata() {
  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }
  // check if day is started before item add
  if (checkIfDayisStartedCount < 5) {
    checkIfDayisStartedCount++;
    initCheckDaytarted();
  }
  const table_id = currenttableButton.id.replace('table_', '');
  initfetchBillTableData({ table_id });
}

let handlertime = 2000;
async function checkPrintProgressAndPrintKOT(previewDetails) {
  handlertime += 2000;
  // if (!window.isKOTPrintInprogessforPOS) {
  if (!window.isPrintingInprogress && !window.isKOTPrintInprogess) {
    $('#kotpreviewBodyid').data('data', previewDetails);
    await window.showkotPreview();
    handlertime = 2000;
  } else {
    setTimeout(() => {
      checkPrintProgressAndPrintKOT(previewDetails);
    }, handlertime);
  }
}

async function KOTPreview(params, printers) {
  if (
    window.KOT_Printer != undefined &&
    window.KOT_Printer.printer_type != undefined &&
    window.KOT_Printer.printer_type == 3 &&
    window.KOT_Printer.more_info != undefined &&
    window.KOT_Printer.more_info.width != undefined &&
    window.KOT_Printer.more_info.height != undefined
  ) {
    isLabelprinter = true;
    more_info = window.KOT_Printer.more_info;
  }
  let customer_name = '';
  const activeTab = $('.mainsectionTabs li a.active').attr('id');

  if (activeTab) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
        if (showcustomeronKOTCheckfordinein)
          customer_name = $('#kotcustomernameField').val();
        break;
      case TAKEAWAY_TAB_ID:
        if (showcustomeronKOTCheckforta)
          customer_name = $('#takeawaykotcustomernameField').val();
        break;
      case DELIVERY_TAB_ID:
        if (showcustomeronKOTCheckfordelivery)
          customer_name = $('#deliverykotcustomernameField').val();
        break;
      case QUICK_TAB_ID:
        if (showcustomeronKOTCheckforquick)
          customer_name = $('#quickbillkotcustomernameField').val();
        break;

      default:
        break;
    }
  }
  if (params.kotItems !== undefined && params.kotItems.length > 0) {
    let tableName = params.forQuickbill
      ? quickbilltableButton.content
      : currenttableButton?.content;
    if (
      !params.forQuickbill &&
      params.kotDetails &&
      params.kotDetails.table_name
    ) {
      tableName = params.kotDetails.table_name;
    }
    let kot_number = params.forQuickbill ? params.tempkotNumber : insertedKOTid;
    if (
      !params.forQuickbill &&
      params.kotDetails &&
      params.kotDetails.insertedKOTid
    ) {
      kot_number = params.kotDetails.insertedKOTid;
    }

    let previewDetails = {
      items: params.kotItems,
      tableName,
      kot_type: params.forQuickbill
        ? $('#quickkotprintChecklabel').html()
        : KOT_TITLE,
      kot_number,
      note: params.kotNote,
      isLabelprinter: params.isLabelprinter,
      more_info: params.more_info,
      order_id: params.order_id,
      showCovers: params.showCovers,
      showWaiternameonkot,
      kitchenDepartment: params.kitchenDepartment,
      customKOTTitle: params.customKOTTitle,
      order_number: params.order_number,
      customOrderNumberName: params.customOrderNumberName,
      username: window.storeDetails.username,
      isNewKot: params.isNewKot,
    };
    previewDetails = cloneDeep(previewDetails);

    if (
      params.forQuickbill &&
      defaultcustomerQuickordertype !== QUICKBILL_BILLING_FLAG
    ) {
      Object.assign(previewDetails, {
        // tableName: BillingTypes[defaultcustomerQuickordertype],
        tableName:
          // window.orderTypes[Number(defaultcustomerQuickordertype)].order_type,
          (window.orderTypes &&
            window.orderTypes[Number(defaultcustomerQuickordertype)]
              ?.order_type) ||
          'Quick Bill',
      });
    }

    if (showWaiternameonkot) {
      const waitername = params.forQuickbill
        ? quickbilltableButton.data.details.waiter
        : params.kotDetails.waiter; // currenttableButton?.data?.details?.waiter;
      Object.assign(previewDetails, { waiter: waitername });
    }

    if (
      shownewoldkotasTitle &&
      !params.forQuickbill &&
      currenttableButton &&
      !currenttableButton.data.details.firstKOTPrinted
    ) {
      currenttableButton.data.details.firstKOTPrinted = true;
    }

    if (
      params.forQuickbill &&
      window.tablestatusTagonkotsettings &&
      window.tablestatusTagonkotsettings.showNewordertag &&
      window.tablestatusTagonkotsettings.newOrdertaglabel
    ) {
      previewDetails.tablestatuskotprintTag =
        window.tablestatusTagonkotsettings.newOrdertaglabel;
    }
    if (params.forQuickbill && showcustomeronKOTCheckforquick) {
      previewDetails.customer = quickbilltableButton.data.details.customer;
    } else if (currenttableButton && currenttableButton.data) {
      if (
        params.kotDetails.billing_type == 1 &&
        showcustomeronKOTCheckfordinein
      ) {
        previewDetails.customer = currenttableButton.data.details.customer;
        if (params.kotDetails && params.kotDetails.customer) {
          previewDetails.customer = params.kotDetails.customer;
        }
      } else if (
        params.kotDetails.billing_type == 2 &&
        showcustomeronKOTCheckforta
      ) {
        previewDetails.customer = currenttableButton.data.details.customer;
        if (params.kotDetails && params.kotDetails.customer) {
          previewDetails.customer = params.kotDetails.customer;
        }
      } else if (
        params.kotDetails.billing_type == 3 &&
        showcustomeronKOTCheckfordelivery
      ) {
        previewDetails.customer = currenttableButton.data.details.customer;
        if (params.kotDetails && params.kotDetails.customer) {
          previewDetails.customer = params.kotDetails.customer;
        }
      }

      if (!previewDetails.customer && customer_name) {
        Object.assign(previewDetails, { customer_name });
      }
      if (window.tablestatusTagonkotsettings) {
        if (
          !params.isNewKot &&
          window.tablestatusTagonkotsettings.showrunningOrdertag &&
          window.tablestatusTagonkotsettings.runningOrdertaglabel
        ) {
          previewDetails.tablestatuskotprintTag =
            window.tablestatusTagonkotsettings.runningOrdertaglabel;
        }

        if (
          params.isNewKot &&
          window.tablestatusTagonkotsettings.showNewordertag &&
          window.tablestatusTagonkotsettings.newOrdertaglabel
        ) {
          previewDetails.tablestatuskotprintTag =
            window.tablestatusTagonkotsettings.newOrdertaglabel;
        }
      }
    }
    if (!previewDetails.customer && customer_name) {
      Object.assign(previewDetails, { customer_name });
    }
    if (showStorenamonkot) {
      previewDetails.showStorenamonkot = window.storeDetails.store_name;
    }

    if (params.forQuickbill) {
      Object.assign(previewDetails, {
        billingType: QUICKBILL_BILLING_FLAG,
      });
    } else {
      Object.assign(previewDetails, {
        billingType: params.kotDetails.billing_type,
      });
    }

    if (params.kotDetails && params.kotDetails.billing_type) {
      Object.assign(previewDetails, {
        billingType: params.kotDetails.billing_type,
      });
    }

    const pageConfig = await setPageconfigifany();
    if (pageConfig && pageConfig.margins) {
      previewDetails.pageConfig = pageConfig;
      pageconfigProvided = true;
    } else {
      pageconfigProvided = false;
    }

    if (previewDetails) {
      console.log(
        `Message="Preparing Kot print data for rendering" JobId="${params?.job_id}" kot_number="${previewDetails.kot_number}" billing_type="${previewDetails.billingType}" table_name="${previewDetails.tableName}" source="Order Window"`,
      );
    }
    if (!printers || !printers?.length) {
      if (!window.__IS_MASTER_POS__) {
        console.log(
          `Message="Printers not found and terminal system. Sending previewDetails to master POS"`,
        );
        // const printKotData = $('#kotpreviewBodyid').data();
        Object.assign(previewDetails, {
          isTerminalPrint: true,
          doNotPrintAllInOneKot: !params.allInOneKot,
          table_id: params.forQuickbill
            ? quickbilltableButton.data.id
            : params.kotDetails.table_id,
          allInOneKot: params.allInOneKot,
        });
        sendKOTPrintRequestToMaster(previewDetails);
      }
    } else {
      // console.log(`Message`)
      Object.assign(previewDetails, {
        job_id: params?.job_id ?? window.generateId(10),
      });

      await window.printKotfromqueue({ previewDetails, printers });
    }

    return 'success';
  }
  return 'failure';
}

/**
 * This method gets the required details to be displayed
 * on the preview and passes it to the preview
 * controller to render the provided data
 * @param {WHether to show preview or not} showPopup
 * @param { Tell's if current bill is a draft bill or not} isdraftBill
 * @param {Tell's if current bill is a quick bill or not} forQuickbill
 */
async function printPreview({
  showPopup,
  isdraftBill,
  forQuickbill,
  currenttable,
  is_Draft_bill,
  billing_type,
  customPrinter,
  currentTableButton,
  printers,
}) {
  // If not a quick bill check if the table is selected or not

  if (currenttable) {
    currenttableButton = currenttable;
  }
  if (!forQuickbill && currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return 'failure';
  }

  // Get the current table
  let currentTable;
  if (currenttable) {
    currentTable = currenttable;
  } else {
    currentTable = forQuickbill ? quickbilltableButton : currenttableButton;
  }
  const { defaultchargesRemoved } = currentTable.data.details;
  // Check if the current table has some items in it.
  if (
    currentTable.data.details != undefined &&
    currentTable.data.details.items.length > 0
  ) {
    let showonBill = false;
    let orderType;
    let recalculate = false;
    let custombilltitle;
    let customKotTitle;
    let deliveryboyName;

    if (!forQuickbill) {
      let { charges } = currentTable.data.details;
      const activeTab = $('.mainsectionTabs li a.active').attr('id');
      switch (currenttableButton.data.order_type_flag) {
        case TAKEAWAY_FLAG_ID:
        case HOMED_FLAG_ID:
          if (DINEIN_TAB_ID === activeTab) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectTheTable'),
            );
            return 'failure';
          }
          showonBill = $('#showOntakeawayBillcheckid').is(':checked');
          if (showcustomeronbillCheck) showonBill = showcustomeronbillCheck;

          if (istakeawaywindowSelected) {
            orderType = 'PickUp';
            if (customBilltitlesettings && customBilltitlesettings.takeaway) {
              custombilltitle = customBilltitlesettings.takeaway;
            }
            if (customKOTtitlesettings && customKOTtitlesettings.takeaway) {
              customKotTitle = customKOTtitlesettings.takeaway;
            }
            if (charges == undefined || charges.length == 0) {
              if (
                window.defaulttakeawayOrdercharges != undefined &&
                window.defaulttakeawayOrdercharges.length > 0 &&
                !defaultchargesRemoved
              ) {
                charges = cloneDeep(window.defaulttakeawayOrdercharges);
                recalculate = true;
              }
            }
          } else {
            // showonBill = true;
            const selection = $(
              "input:radio[name='deliveryBoyButton']:checked",
            );
            // if (selection && selection.length > 0) {
            deliveryboyName = $(`#deliveryBoyNamelabelid`).text();
            // }
            orderType = 'Delivery';
            if (customBilltitlesettings && customBilltitlesettings.delivery) {
              custombilltitle = customBilltitlesettings.delivery;
            }
            if (customKOTtitlesettings && customKOTtitlesettings.delivery) {
              customKotTitle = customKOTtitlesettings.delivery;
            }
            if (charges == undefined || charges.length == 0) {
              if (
                window.defaulthomedOrdercharges != undefined &&
                window.defaulthomedOrdercharges.length > 0 &&
                !defaultchargesRemoved
              ) {
                charges = window.defaulthomedOrdercharges;
                recalculate = true;
              }
            }
          }
          break;
        case DINEIN_FLAG_ID:
        case VIRTUALTABLE_FLAG_ID:
          if (!currenttable && TAKEAWAY_TAB_ID === activeTab) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectTheTable'),
            );
            return 'failure';
          }

          if (charges == undefined || charges.length == 0) {
            if (
              defaultdineinOrdercharges != undefined &&
              defaultdineinOrdercharges.length > 0 &&
              !defaultchargesRemoved
            ) {
              if (currenttableButton?.data['mpos_department.section'] == 1) {
                // check if bar section charges is present and remove it
                const filteredCharges = window.defaultdineinOrdercharges.filter(
                  (charge) => {
                    const extraDetails = safeParse(charge.extra_details);
                    return extraDetails.bar_section_billing !== 1;
                  },
                );
                charges = filteredCharges;
              } else {
                charges = window.defaultdineinOrdercharges;
                recalculate = true;
              }
            }
          }
          showonBill = $('#showOnBillcheckid').is(':checked');
          orderType = 'Dine In';
          if (customBilltitlesettings && customBilltitlesettings.dinein) {
            custombilltitle = customBilltitlesettings.dinein;
          }
          if (customKOTtitlesettings && customKOTtitlesettings.delivery) {
            customKotTitle = customKOTtitlesettings.dinein;
          }

          break;
        default:
          break;
      }
      if (recalculate) {
        currenttableButton.data.details.charges = charges;
        await precalculateDetailsCheck(currenttableButton);
      }
    } else {
      showonBill = $('#showOnquickbillBillcheckid').is(':checked');
      // orderType = BillingTypes[defaultcustomerQuickordertype] || 'Quick Bill';
      orderType =
        window.orderTypes[Number(defaultcustomerQuickordertype)]?.order_type ||
        'Quick Bill';
      const customer_name = $('#quickbillkotcustomernameField').val();
      const customer_mobile = $('#quickbillkotcustomermobileField').val();
      let customer = getCustomer(false, customer_mobile);

      if (dynamiccustomerAddressforquickbill && customer) {
        Object.assign(customer, {
          address_line1: dynamiccustomerAddressforquickbill,
        });
      }
      if (!customer) {
        if (customer_name && customer_mobile) {
          customer = {
            name: customer_name,
            phone: customer_mobile,
            email: '',
            store_id: window.storeDetails.store_id,
            address_line1: dynamiccustomerAddressforquickbill,
            address_line2: '',
            city: '',
            ...newCustomerAddressForQuickBill,
          };
        }
      }

      quickbilltableButton.data.details.customer = customer;

      const persons = $('#quickbillnoofpersonsField').val();
      quickbilltableButton.data.details.persons = persons;
    }

    // if remote kot and showcustomeronbill is true then show customer on bill
    if (
      currenttableButton &&
      currenttableButton.data.details &&
      currenttableButton.data.details.remoteKot
    ) {
      showonBill = showcustomeronbillCheck;
    }

    if (/-(Per|Por|Part)-/.test(currentTable.content)) {
      showonBill = showcustomeronbillCheck;
    }

    const previewDetails = cloneDeep(currentTable?.data?.details);
    if (
      currentTable.data.details.printBillItems &&
      currentTable.data.details.printBillItems.length
    ) {
      Object.assign(previewDetails, {
        items: currentTable.data.details.printBillItems,
      });
    }
    const pageConfig = await setPageconfigifany();
    previewDetails.tableName = currentTable.content;
    previewDetails.table_id = currentTable.data.id;
    previewDetails.tax_name = window.currentTaxname;
    previewDetails.showCustomerinfo = showonBill;
    previewDetails.isdraftBill = isdraftBill;
    previewDetails.order_type_flag = orderType;
    previewDetails.custombilltitle = custombilltitle;
    previewDetails.customKotTitle = customKotTitle;
    previewDetails.customOrderNumberName = customOrderNumberName;
    previewDetails.extra_details = currentTable.data.details.extra_details;
    previewDetails.forQuickbill = forQuickbill;
    // previewDetails.field2 = currentTable.data.details.field2;

    previewDetails.printers = printers;

    if (pageConfig && pageConfig.margins) {
      previewDetails.pageConfig = pageConfig;
      pageconfigProvided = true;
    } else {
      pageconfigProvided = false;
    }

    if (showdefaultPayment) {
      previewDetails.paymentAdded = true;
    }

    if (previewDetails.draftprint_status) {
      Object.assign(previewDetails, {
        printCount: previewDetails.draftprint_status + 1,
      });
    }

    if (previewDetails.print_status && !isdraftBill) {
      Object.assign(previewDetails, {
        printCount: previewDetails.print_status + 1,
      });
    }

    if (previewDetails.print_status && previewDetails.draftprint_status) {
      Object.assign(previewDetails, {
        printCount:
          previewDetails.print_status + previewDetails.draftprint_status + 1,
      });
    }

    if (deliveryboyName) {
      previewDetails.deliveryboyName = deliveryboyName;
    }
    if (forQuickbill) {
      const customBillname = $('#quickbillprintChecklabel').html();
      if (customBillname) {
        previewDetails.customBillname = customBillname;
      }

      if (customKOTtitlesettings && customKOTtitlesettings.quick) {
        previewDetails.customKotTitle = customKOTtitlesettings.quick;
      }
    }

    if (customOrderNumberName) {
      previewDetails.customOrderNumberName = customOrderNumberName;
    }
    // Check for loyalty reward discount
    if (window.storeDetails.loyalty_enabled) {
      const extraDetails = currentTable.data.details.extra_details;
      if (extraDetails && extraDetails.rewardDiscount) {
        Object.assign(previewDetails, {
          isloyaltyrewardDiscount: true,
          rewardTitle: extraDetails.rewardDiscount.title,
          pointsRedeemed: extraDetails.rewardDiscount.points_redeemed,
        });
      } else {
        Object.assign(previewDetails, {
          isloyaltyrewardDiscount: false,
          pointsRedeemed: undefined,
        });
      }
    }
    const extra_info = safeParse(window.storeDetails.extra_info);
    if (extra_info && extra_info.isReeloIntegrate) {
      const extraDetails = currentTable.data.details.extra_details;
      if (
        extraDetails &&
        extraDetails.reelo &&
        extraDetails.reelo_redeemed_amount
      ) {
        Object.assign(previewDetails, {
          // reeloRedeemAmount: extraDetails.reelo.redeemed_amount
          reelo_redeemed_amount: extraDetails.reelo_redeemed_amount,
        });
      }
    }

    // add customer name if only name is entered
    if (showcustomeronbillCheck) {
      let customer_name = '';
      const activeTab = $('.mainsectionTabs li a.active').attr('id');

      if (activeTab) {
        switch (activeTab) {
          case DINEIN_TAB_ID:
            if (showcustomeronKOTCheckfordinein)
              customer_name = $('#kotcustomernameField').val();
            break;
          case TAKEAWAY_TAB_ID:
            if (showcustomeronKOTCheckforta)
              customer_name = $('#takeawaykotcustomernameField').val();
            break;
          case DELIVERY_TAB_ID:
            if (showcustomeronKOTCheckfordelivery)
              customer_name = $('#deliverykotcustomernameField').val();
            break;
          case QUICK_TAB_ID:
            if (showcustomeronKOTCheckforquick)
              customer_name = $('#quickbillkotcustomernameField').val();
            break;

          default:
            break;
        }
      }
      if (!previewDetails.customer && customer_name) {
        Object.assign(previewDetails, { customer_name });
      }
    }
    if (showPopup) {
      console.log(
        `bill preview opened from order window for order_id=${previewDetails.bill_number}, bill_number=${previewDetails.order_id}, billing_type=${previewDetails.billing_type}, orderType=${previewDetails.order_type_flag}`,
      );
      $('#previewModal').modal('show');
    }

    if (previewDetails) {
      console.log(
        `bill print from order window for order_id=${previewDetails.bill_number}, bill_number=${previewDetails.order_id}, billing_type=${previewDetails.billing_type}, orderType=${previewDetails.order_type_flag}`,
      );
    }

    Object.assign(previewDetails, {
      job_id: window.generateId(10),
    });

    console.log(
      `[OrderWindow] Message="Add Bill print job in queue" JobId="${previewDetails?.job_id}" `,
    );

    await window.printBillfromqueue({
      previewDetails,
      is_Draft_bill,
      billing_type,
      customPrinter,
      currentTableButton,
      currenttable,
      printers,
    });

    //print from queue

    return 'success';
  }
  window.notifyUser.showMessage(
    'error',
    $.i18n.t('controller:orderController.noItems'),
  );
  return 'failure';
}

window.setPageconfigifany_fromremote = (params) => setPageconfigifany(params);

/**
 * Set the margins to the preview if there are any
 */
async function setPageconfigifany(istabidProvided) {
  const currentPrinter = getcurrentwindowPrinter(istabidProvided);
  if (currentPrinter && currentPrinter.size && window.settingsConfig) {
    let margins;
    $('#preview-footer-actionsid').attr('size', currentPrinter.size);
    let currentSize = '80mm';
    switch (currentPrinter.size) {
      case PRINTER_SIZES_REFID.PRINTER_58MM.ID:
        margins = window.settingsConfig[PRINTER_58_CONFIG - 1].value;
        currentSize = PRINTER_SIZES_REFID.PRINTER_58MM.SIZE;
        $('#previewContainerid').css({
          width: PRINTER_SIZES_REFID.PRINTER_58MM.SIZE,
        });
        break;
      case PRINTER_SIZES_REFID.PRINTER_80MM.ID:
        currentSize = PRINTER_SIZES_REFID.PRINTER_80MM.SIZE;
        $('#previewContainerid').css({
          width: PRINTER_SIZES_REFID.PRINTER_80MM.SIZE,
          // 'margin-left': '8px',
        });
        margins = window.settingsConfig[PRINTER_80_CONFIG - 1].value;
        break;
      default:
        break;
    }

    if (margins) {
      try {
        // $('#previewContainerid').css({ 'margin': margins });
        const rawmargins = String(margins).split(' ');
        if (rawmargins && rawmargins.length == 2) {
          $('#currentleftMarginlabel').html(rawmargins[0].replace('px', ''));

          if (rawmargins[1]) {
            const currentWidth = Number(rawmargins[1].replace('mm', ''));
            currentSize = Number(currentSize.replace('mm', ''));
            $('#previewContainerid').css({
              width: rawmargins[1],
            });
            if (currentSize > currentWidth) {
              const widthDecrementcounter = currentSize - currentWidth;
              if (widthDecrementcounter > 0) {
                $('#currentrightMarginlabel').html(widthDecrementcounter);
              } else {
                $('#currentrightMarginlabel').html(0);
              }
            }
          }
        }
      } catch (error) {
        margins = undefined;
      }
    } else {
      $('#currentleftMarginlabel').html('0');
      $('#currentrightMarginlabel').html('0');
    }

    const pageConfig = {
      margins,
    };
    return pageConfig;
  }
}

/**
 *  Add's the item to bill table.
 * @param {*} tableid
 * @param {item to add in bill row} item
 */
function addBillRow(tableid, item) {
  if (item != undefined && tableid) {
    // let itemtitle = item.title;
    // if(itemtitle.includes('\\n')){
    //    itemtitle = itemtitle.replace('\\n', '&nbsp')
    // }

    let itemTitle = item.title;
    if (window.selectedLanguage != 'en' && item.alternative_title) {
      itemTitle = item.alternative_title;
    }
    if (item && item.extra_details && item.extra_details.baseTitle) {
      itemTitle = item.extra_details.baseTitle;
      if (window.selectedLanguage != 'en' && item.alternative_title) {
        itemTitle = item.alternative_title;
      }
      itemTitle = `<span class='baseItemKotbillrow'>${itemTitle}</span>`;
    }
    if (item.addons && item.addons.length) {
      item.addons.forEach((addon) => {
        if (window.selectedLanguage !== 'en' && addon.alternative_title) {
          itemTitle =
            `${itemTitle}<br>` +
            `<span class='kotbillItemAddons'>${addon.option_qty || addon.qty} x ${addon.alternative_title || addon.option_name || addon.title} </span>`;
        } else {
          itemTitle =
            `${itemTitle}<br>` +
            `<span class='kotbillItemAddons'>${addon.option_qty || addon.qty} x ${addon.option_name || addon.title} </span>`;
        }
      });
    }
    let code = '';
    const table = $(`#${tableid}`);

    if (showitemcodeDetails && item.short_code) {
      code = ` (${item.short_code})`;
    }
    let kotnote = '';
    if (showItemNoteInBillingWindow && item.note) {
      kotnote = ` </br> <span class="kotrowItemNoteid"> (${item.note}) </span>`;
    }
    const billitemRow = $('<tr>', {
      kot_item_id: item.id,
    });

    const billitemnameCell = $('<td>', {
      html: itemTitle + kotnote + code,
      class: 'itemBillRow',
    });
    const billitemqtyCell = $('<td>', {
      class: 'billItemQty',
      id: `billitemqty_${item.item_id}`,
      html: item.quantity,
    });
    const billitemamountCell = $('<td>', {
      id: `billitemamt_${item.item_id}`,
      html: Number(item.amount).toFixed(ROUNDOFF_UPTO),
    });
    // Check for discunt
    if (item.discount_rate > 0 && item.discounted_price > 0) {
      billitemnameCell.addClass('text-info').attr('title', 'Discounted item');
    }

    billitemRow.append(billitemnameCell);
    billitemRow.append(billitemqtyCell);
    billitemRow.append(billitemamountCell);
    table.append(billitemRow);
  }
  $(`#${tableid}`).trigger('rowAddOrRemove');
}

/**
 * Resets the current details and variable needed to take a new ta and
 * delivery order.
 */
function newOrder(newOrderForChangeOrderType = false) {
  const isKOTTableempty = $('#takeawaykotTable tbody tr').length == 0;

  if (!isKOTTableempty && !newOrderForChangeOrderType) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.thereAreSomeItemsInKOT'),
    );
    return;
  }
  $('#takeawaytabID').tab('show');
  $(`#${TAKEAWAY_BILLTABLE}`).find('tr:not(:first)').remove();
  $(`#${TAKEAWAY_KOTTABLE}`).find('tr:not(:first)').remove();
  $('#takeawaykotcustomernameField').val('');
  $('#takeawaykotcustomermobileField').val('');
  $('#takotcustomeraddressField').val('');
  $('#takeawaynoofpersonsField').val('');
  $('#takeawaycurrentTablename').html('');
  $('#takeawaybillcurrentTablename').html('');
  $('#takeawaybillGrandtotal').html('');
  $('#takeawaykottotalLabel').html('');
  $('#deliverykottotalLabel').html('');
  $('#dboyselectionId').prop('selectedIndex', 0);
  $('#takeawayPreordercheckid').prop('checked', false);
  // $('#searchByname_item').focus();
  defaultCursorOnSerchByCode
    ? $('#searchitembyCode').focus()
    : $('#searchByname_item').focus();
  $('#takeawaykotdialcodeFieldid').val(window.dial_code);
  activateTab(TAKEAWAY_KOT_TABID);
  setColor();

  if (isCurrenttabletakeaway() || isCurrenttabledelivery()) {
    currenttableButton = undefined;
    window.globalcurrenttableId = undefined;
  }
  isnewtakeawayOrder = true;
  temptaWaiter = undefined;
  temptaWaiterid = undefined;
  if (window.usenewtableitemView) {
    $('#itemsDivid').show();
    $('#tableDiv_container').hide();
    $('#deptcontainer').hide();
    $('.treeviewDiv').css('height', '93%');
  }

  $(`#takeawaycustomerhistoryButton span`).hide();
  if (window.askPasscodeForModifyBillAfterSave) {
    $('#itemviewContainer')
      .find(
        '.menuItemButtoncontentwrapper, .inneritembuttonDiv, img, div, label, i',
      )
      .each(function () {
        $(this).removeAttr('passcode-protected');
      });
    $('#itemviewContainer').removeAttr('passcode-protected');
  }

  if (itemFileterByOrderType) {
    showAllitems();
  }

  window.notifyUser.showMessage(
    'success',
    $.i18n.t('controller:orderController.readyToTakeNewOrder'),
  );
}

window.initNewOrderFromRemote = () => {
  const activeTab = $('.mainsectionTabs li a.active').attr('id');
  if (activeTab) {
    switch (activeTab) {
      case TAKEAWAY_TAB_ID:
        newOrder();
        break;
      case DELIVERY_TAB_ID:
        newDeliveryOrder();
      default:
        break;
    }
  }
};

async function newDeliveryOrder(newOrderForChangeOrderType = false) {
  const isKOTTableempty = $('#deliverykotTable tbody tr').length == 0;

  if (!isKOTTableempty && !newOrderForChangeOrderType) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.thereAreSomeItemsInKOT'),
    );
    return;
  }

  $('#deliverytabID').tab('show');

  $(`#${DELIVERY_BILLTABLE}`).find('tr:not(:first)').remove();
  $(`#${DELIVERY_KOTTABLE}`).find('tr:not(:first)').remove();
  $('#deliverykotcustomernameField').val('');
  $('#deliverykotcustomermobileField').val('');
  $('#deliverykotcustomeraddressField').val('');
  $('#deliverynoofpersonsField').val('');
  $('#deliverycurrentTablename').html('');
  $('#deliverybillcurrentTablename').html('');
  $('#deliverybillGrandtotal').html('');
  $('#deliverykottotalLabel').html('');
  $('#deliverykottotalLabel').html('');
  $('#deliveryBoyNamelabelid').text('');
  $('#deliverykotdialcodeFieldid').val(window.dial_code);

  // $('#dboyselectionfordeliveryId').prop('selectedIndex', 0);
  $($("input:radio[name='deliveryBoyButton']")).prop('checked', false);
  $('#deliveryPreordercheckid').prop('checked', false);
  // $('#searchByname_item').focus();
  defaultCursorOnSerchByCode
    ? $('#searchitembyCode').focus()
    : $('#searchByname_item').focus();
  activateTab(DELIVERY_KOT_TABID);
  setColor();
  if (isCurrenttabledelivery() || isCurrenttabletakeaway()) {
    currenttableButton = undefined;
    window.globalcurrenttableId = undefined;
  }
  isnewdeliveryOrder = true;
  temptaWaiterfordelivery = undefined;
  temptaWaiteridfordelivery = undefined;
  if (window.usenewtableitemView) {
    $('#itemsDivid').show();
    $('#tableDiv_container').hide();
    $('#deptcontainer').hide();
    $('.treeviewDiv').css('height', '93%');
  }

  $(` #deliverycustomerhistoryButton span`).hide();

  if (window.askPasscodeForModifyBillAfterSave) {
    $('#itemviewContainer')
      .find(
        '.menuItemButtoncontentwrapper, .inneritembuttonDiv, img, div, label, i',
      )
      .each(function () {
        $(this).removeAttr('passcode-protected');
      });
    $('#itemviewContainer').removeAttr('passcode-protected');
  }
  if (itemFileterByOrderType) {
    await showAllitems();
  }

  window.notifyUser.showMessage(
    'success',
    $.i18n.t('controller:orderController.readyToTakeNewOrder'),
  );
}

function getLatestDate() {
  showLoader({
    title: 'Fetching latest Date',
    text: $.i18n.t('controller:orderController.pleaseWait'),
  });
  initFetchDateFromBackend();
}

/**
 * Makes save bill request to the main process
 */
async function makesaveBillrequest(shouldprintBill) {
  if (checkSystemDate) {
    const targetDate = moment(window.currentDateFetchedFromBackend);
    const currentDate = moment();
    if (!currentDate.isSame(targetDate, 'day')) {
      getLatestDate();
      window.notifyUser.showMessage('error', 'System date is not upto date');
      return;
    }
  }

  if (!calculationDone) {
    console.log('Save bill is in progress..');
    return;
  }
  if (savebillinProgessForOrderWindow) {
    console.log('Save bill is in progress..');
    return;
  }

  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return 'failure';
  }
  if (
    $('#tatable-actions-divid *:disabled').length > 0 ||
    $('#table-actions-divid *:disabled').length > 0
  ) {
    return;
  }
  switch (currenttableButton.data.order_type_flag) {
    case DINEIN_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.dinein &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    case TAKEAWAY_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.takeaway &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    case HOMED_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.delivery &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    default:
      break;
  }
  if (
    currenttableButton.data.details.isBillModified == 1 &&
    currenttableButton.data.details.bill_number != undefined &&
    currenttableButton.data.details.bill_number != 0
  ) {
    const isBillPrinted = await initCheckBillPrinted({
      order_id: currenttableButton.data.details.bill_number,
      store_id: window.storeDetails.store_id,
    });
    if (
      shouldprintBill &&
      window.reprintBill &&
      isBillPrinted.length > 0 &&
      isBillPrinted[0].print_status !== 0
    ) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t(
          'controller:orderWindowNotifications.BillisprintedalreadyYoucannotreprintsamebill',
        ),
      );
      return;
    }
  }

  if (fastsettlePopupisopen) {
    const waiterTipAmount = $('#swalfastwaiterTipinput').val();
    if (waiterTipAmount && !currenttableButton.data.details.order_id) {
      Swal.showValidationMessage(
        'Please save bill first and then add tip amount',
      );
      $('input.swal-fast-action-button').prop('disabled', false);
      return;
    }
  }
  if (
    (!allowModifyBill &&
      currenttableButton.data.details.bill_number != undefined &&
      currenttableButton.data.details.bill_number != 0) ||
    (allowModifyBill &&
      currenttableButton.data.details.bill_number != undefined &&
      currenttableButton.data.details.bill_number != 0 &&
      currenttableButton.data.details.isBillModified == 1)
  ) {
    console.log('bill already saved');
    if (!fastsettlePopupisopen)
      window.notifyUser.showMessage(
        'success',
        $.i18n.t('controller:orderController.billAlreadySaved'),
      );

    if (fastsettlePopupisopen) {
      Swal.showValidationMessage(
        $.i18n.t('controller:orderController.billAlreadySaved'),
      );
      $('input.swal-fast-action-button').prop('disabled', false);
    }

    if (shouldprintBill) {
      // if (
      //   (isbharatpeConfigured || isPhonePeConfigured) &&
      //   !currenttableButton.data.details.field2
      // ) {
      //   fetchBilldata();
      // }
      let billingtype = DINEIN_BILLING_FLAG;
      switch (currenttableButton.data.order_type_flag) {
        case TAKEAWAY_FLAG_ID:
          billingtype = TAKEAWAY_BILLING_FLAG;
          break;
        case HOMED_FLAG_ID:
          billingtype = HOMED_BILLING_FLAG;
          break;
        case DINEIN_FLAG_ID:
        case VIRTUALTABLE_FLAG_ID:
          billingtype = DINEIN_BILLING_FLAG;
          break;
      }
      await printBill({
        isdraftBill: false,
        forQuickbill: false,
        currenttable: '',
        billing_type: billingtype,
      });
      $(`#${currenttableButton.id}`).css(
        'background-color',
        TableUtils.Colors.BILL_PRINTED,
      );
      updatetableStatusrequest({
        table_id: currenttableButton.data.id,
        table_action_flag: TableUtils.State.BILL_PRINTED,
        table_color: TableUtils.Colors.BILL_PRINTED,
      });
      Object.assign(currenttableButton.data.details, {
        print_status: currenttableButton.data.details.print_status + 1,
      });
      initupdatePrintStatus({
        order_id: currenttableButton.data.details.bill_number,
        store_id: window.storeDetails.store_id,
      });
      sendBillsavedevent({
        bill_number: currenttableButton?.data?.details?.bill_number,
        order_id: currenttableButton?.data?.details?.order_id,
        table_id: currenttableButton.data.id,
        isBillPrinted: true,
        message: 'Bill Printed',
        order_total: currenttableButton?.data?.details?.order_total || 0,
      });
    }
    return 'failure';
  }
  // showLoader({
  //   title: $.i18n.t('controller:orderController.savingBill'),
  //   text: $.i18n.t('controller:orderController.pleaseWait'),
  // });
  if (
    currenttableButton.data.details.items != undefined &&
    currenttableButton.data.details.items.length > 0
  ) {
    let billTotal = Number(
      currenttableButton.data.details.order_total.toFixed(ROUNDOFF_UPTO),
    );
    let customer_name;
    let customer_mobile;
    const table_id = currenttableButton.id.replace('table_', '');
    let persons = 1;
    const { items } = currenttableButton.data.details;
    let deliveryboy_id = 0;
    let delivery_boy_name;
    let delivery_boy_phone;
    let askcoversCheck = false;
    let isPreorder = false;
    /**
     * Check for default charges
     */
    let { charges } = currenttableButton.data.details;
    const { defaultchargesRemoved } = currenttableButton.data.details;
    let billing_type = DINEIN_BILLING_FLAG;
    switch (currenttableButton.data.order_type_flag) {
      case TAKEAWAY_FLAG_ID:
        {
          if (
            (charges == undefined || charges.length == 0) &&
            !defaultchargesRemoved
          ) {
            calculateAgain = true;
            charges = cloneDeep(window.defaulttakeawayOrdercharges);
            currenttableButton.data.details.charges = charges;
            await precalculateDetailsCheck(currenttableButton);
          }

          if (!billTotal) billTotal = $('#takeawaybillGrandtotal').text();
          customer_name = $('#takeawaykotcustomernameField').val();
          customer_mobile = $('#takeawaykotcustomermobileField').val();
          persons = $('#takeawaynoofpersonsField').val();
          billing_type = TAKEAWAY_BILLING_FLAG;

          askcoversCheck = askfortahdcoversFirst;
          $('#tatable-actions-divid *').prop('disabled', true);
          $('#tablesContainer *').prop('disabled', true);
          isPreorder = $('#takeawayPreordercheckid').is(':checked');
        }
        break;
      case HOMED_FLAG_ID:
        {
          if (
            (charges == undefined || charges.length == 0) &&
            !defaultchargesRemoved
          ) {
            calculateAgain = true;
            charges = cloneDeep(window.defaulthomedOrdercharges);
            currenttableButton.data.details.charges = charges;
            await precalculateDetailsCheck(currenttableButton);
          }

          if (!billTotal) billTotal = $('#deliverybillGrandtotal').text();
          customer_name = $('#deliverykotcustomernameField').val();
          customer_mobile = $('#deliverykotcustomermobileField').val();
          persons = $('#deliverynoofpersonsField').val();

          billing_type = HOMED_BILLING_FLAG;
          // const selection = $(
          //   '#dboyselectionfordeliveryId option:selected:not([disabled])',
          // );
          // const selection = $("input:radio[name='deliveryBoyButton']:checked");
          // console.log('selection::', selection);
          // if (selection.length > 0) {
          //   deliveryboy_id = $(selection).attr('value');
          //   delivery_boy_phone = $(selection).attr('phone');
          //   delivery_boy_name = $(selection).text();
          // }

          if (currenttableButton.data.details.deliveryboy_id) {
            const selection = window.deliveryBoys.find(
              (b) =>
                b.id === Number(currenttableButton.data.details.deliveryboy_id),
            );
            deliveryboy_id = selection.id;
            delivery_boy_phone = selection.phone;
            delivery_boy_name = selection.name;
          }
          askcoversCheck = askfordeliverycoversFirst;
          $('#tatable-actions-divid *').prop('disabled', true);
          $('#tablesContainer *').prop('disabled', true);
          isPreorder = $('#deliveryPreordercheckid').is(':checked');
        }
        break;
      case DINEIN_FLAG_ID:
      case VIRTUALTABLE_FLAG_ID:
        {
          if (
            (charges == undefined || charges.length == 0) &&
            !defaultchargesRemoved
          ) {
            calculateAgain = true;
            if (currenttableButton?.data['mpos_department.section'] == 1) {
              // check if bar section charges is present and remove it
              const filteredCharges = window.defaultdineinOrdercharges.filter(
                (charge) => {
                  const extraDetails = safeParse(charge.extra_details);
                  return extraDetails.bar_section_billing !== 1;
                },
              );
              charges = filteredCharges;
            } else {
              charges = cloneDeep(window.defaultdineinOrdercharges);
            }
            currenttableButton.data.details.charges = charges;
            await precalculateDetailsCheck(currenttableButton);
          }

          if (!billTotal) billTotal = $('#billGrandtotal').text();
          customer_name = $('#kotcustomernameField').val();
          customer_mobile = $('#kotcustomermobileField').val();
          persons = $('#noofpersonsField').val();
          billing_type = DINEIN_BILLING_FLAG;
          askcoversCheck = askfordinecoversFirst;
          $('#table-actions-divid *').prop('disabled', true);
          $('#tablesContainer *').prop('disabled', true);
        }
        break;
      default:
        break;
    }
    $('.neworderButton').prop('disabled', true);

    if (!persons && askcoversCheck) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.invalidCovers'),
      );
      return;
    }
    const customer = getCustomer(false, customer_mobile);

    if (
      currenttableButton?.data?.details?.isBillModified == 2 &&
      currenttableButton?.data?.details?.extra_details?.rewardDiscount
        ?.points_redeemed
    ) {
      sendRewardhistory({
        reward: '',
        order_id: currenttableButton.data.details.bill_number,
        phone: customer.phone,
        customer_name: customer.name,
        isQuickbill: 0,
        action: 'delete',
      });
      delete currenttableButton?.data?.details?.extra_details?.rewardDiscount;
      currenttableButton.data.details.discount = 0;
    }

    if (
      currenttableButton?.data?.details?.isBillModified === 2 &&
      currenttableButton?.data?.details?.coupon
    ) {
      delete currenttableButton?.data?.details?.coupon;
      delete currenttableButton?.data?.details?.couponDisountamt;
    }

    let payment_mode = defaultPaymentoption;
    console.log(`Message="Default payment mode=${defaultPaymentoption}"`);
    console.log(
      `Message="currenttableButton.data.details.payment_mode=${currenttableButton.data.details.payment_mode}"`,
    );
    if (
      currenttableButton.data &&
      currenttableButton.data.details &&
      currenttableButton.data.details.payment_mode
    ) {
      payment_mode = currenttableButton.data.details.payment_mode;
    }

    if (payment_mode === 'None' || payment_mode === '0') {
      payment_mode = undefined;
    }

    const order_id = window.generateId();
    let paymentDetails;
    console.log(`Message="payment_mode=${payment_mode}"`);
    if (payment_mode) {
      paymentDetails = {
        order_id,
        payment_option: payment_mode,
        amount: billTotal,
      };
      console.log(`Message="Save bill paymentDetails=${paymentDetails}"`);
      currenttableButton.data.details.payment_mode =
        paymentDetails.payment_option;
    }

    const { waiter } = currenttableButton.data.details;
    const { waiter_id } = currenttableButton.data.details;

    const { extra_details } = currenttableButton.data.details;

    // added remote kot order id in extra_details;
    if (
      currenttableButton.data.details.remoteKot ||
      currenttableButton.data.details.remoteOrder_id !== '0'
    ) {
      Object.assign(extra_details, {
        upsale_order_id: currenttableButton.data.details.remoteOrder_id,
      });
      Object.assign(extra_details, { appSource: 'UpSale' });
    }

    if (
      currenttableButton.data.details &&
      currenttableButton.data.details.is_pre_order
    ) {
      Object.assign(extra_details, { is_pre_order: 1 });

      if (currenttableButton.data.details.preorderInfo) {
        const formattedDate = moment(
          currenttableButton.data.details.preorderInfo.delivery_at,
        ).format('YYYY-MM-DD HH:mm:ss');
        Object.assign(extra_details, {
          delivery_at: currenttableButton.data.details.preorderInfo.delivery_at,
          delivered_at: formattedDate,
        });
      }
    }
    if (currenttableButton.data['mpos_department.section'] == 2) {
      Object.assign(extra_details, { isBarSection: 'true' });
    }

    if (currenttableButton?.data?.details?.reservation_id) {
      Object.assign(extra_details, {
        reservation_id: currenttableButton.data.details.reservation_id,
      });
    }

    // currenttableButton.data.details.cust_paid_amount =
    //   currenttableButton.data.details.cust_paid_amount || billTotal;

    // if (!customer_name && !customer_mobile) {
    //   customer_name = 'POS User';
    //   customer_mobile = '9090909090';
    // }

    Object.assign(extra_details, { invoiceType: 'B2C' });
    if (allowModifyBill && currenttableButton.data.details.bill_number) {
      if (currenttableButton.data.details.discountHistory) {
        currenttableButton.data.details.discountHistory = [];
      }
      Object.assign(currenttableButton.data.details, {
        discounttoApply: 0,
        coupondiscounttoApply: 0,
      });
    }

    const uniqueKotIds = [...new Set(items.map((item) => item.kot_id))];

    const billDetails = {
      order_total: billTotal,
      table_name: currenttableButton.content,
      table_id,
      cust_name: customer != undefined ? customer.name : customer_name,
      phone: customer != undefined ? customer.phone : customer_mobile,
      email: customer != undefined ? customer.email : '',
      line_1: customer != undefined ? customer.address_line1 : '',
      line_2: customer != undefined ? customer.address_line2 : '',
      persons,
      order_state: OrderState.PENDING,
      discount_title: currenttableButton.data.details.discount_title,
      discount:
        Number(currenttableButton.data.details.discounttoApply) +
        Number(currenttableButton.data.details.coupondiscounttoApply),
      order_level_total_taxes: currenttableButton.data.details.taxtoApply,
      order_id,
      order_subtotal: currenttableButton.data.details.order_subtotal,
      order_level_total_charges:
        currenttableButton.data.details.order_level_total_charges,
      charges_level_total_tax:
        currenttableButton.data.details.charges_level_total_tax,
      store_id: window.storeDetails.store_id,
      billing_type,
      deliveryboy_id,
      user_id: window.storeDetails.username,
      delivery_boy_phone,
      delivery_boy_name,
      createdBy: window.storeDetails.username,
      // currenttableButton.data.details.createdBy ||
      // window.storeDetails.username,
      payment: payment_mode,
      waiter,
      waiter_id,
      issectionwisebilling:
        currenttableButton.data.details.issectionwisebilling,
      // cust_paid_amount:
      //   currenttableButton.data.details.cust_paid_amount || billTotal,
      instructions: billstatusReason || '',
      field1: orderStatusReason || '',
      extra_details: extra_details || {},
      charges: currenttableButton.data.details.totalCharges,
      item_level_total_charges:
        currenttableButton.data.details.item_level_total_charges,
      draftprint_status: currenttableButton.data.details.draftprint_status || 0,
      isBarSection: currenttableButton.data['mpos_department.section'],
      discounted_product_groups: currenttableButton.data.details
        .discounted_product_groups
        ? currenttableButton.data.details.discounted_product_groups
        : '',
      uniqueKotIds,
      order_note: currenttableButton.data.details.order_note || null,
    };
    if (isPreorder && !billDetails.phone) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.pleaseSelectCustomer'),
      );
      return;
    }

    if (!window.reduceInventorystatus) {
      Object.assign(billDetails, { inventoryReduced: 3 });
    }
    if (shouldprintBill) {
      if (currenttableButton.data.details.print_status) {
        Object.assign(billDetails, {
          print_status:
            Number(currenttableButton.data.details.print_status) + 1 || 0,
        });
      } else {
        Object.assign(billDetails, { print_status: 1 });
      }
    } else {
      Object.assign(billDetails, {
        print_status: Number(currenttableButton.data.details.print_status) || 0,
      });
    }

    if (isPreorder) {
      Object.assign(billDetails, { is_pre_order: isPreorder });
    }

    if (currenttableButton?.data?.details?.reservation_id) {
      Object.assign(billDetails, {
        reservation_id: currenttableButton?.data?.details?.reservation_id,
      });
    }

    let couponDisountavailable = false;
    if (
      currenttableButton.data.details.coupon &&
      currenttableButton.data.details.couponDisountamt > 0
    ) {
      billDetails.couponDisount =
        currenttableButton.data.details.couponDisountamt;
      billDetails.couponDisounttype =
        currenttableButton.data.details.couponDisounttype;
      billDetails.coupon = currenttableButton.data.details.coupon;
      billDetails.couponDisounttotal = Number(
        currenttableButton.data.details.coupondiscounttoApply,
      );
      couponDisountavailable = true;
    }

    savebillinProgessForOrderWindow = true;

    const billData = {
      paymentDetails,
      billDetails,
      items,
      charges,
      table_color: TableUtils.Colors.BILL_SAVED,
      table_action_flag: TableUtils.State.BILL_SAVED,
      printBill: shouldprintBill,
      order_type_flag: currenttableButton.data.order_type_flag,
    };

    if (
      currenttableButton.data.details.discountHistory &&
      Array.isArray(currenttableButton.data.details.discountHistory) &&
      currenttableButton.data.details.discountHistory.length > 0
    ) {
      billData.discountHistory =
        currenttableButton.data.details.discountHistory;

      billData.discountHistory.forEach((discount) => {
        Object.assign(discount, { order_id });
      });
    }

    if (couponDisountavailable) {
      const couponDisounthistorydata = {
        store_id: window.storeDetails.store_id,
        tmpos_id: window.storeDetails.tmpos_id,
        logedin_user: window.storeDetails.username,
        coupon_code: String(
          currenttableButton.data.details.coupon,
        ).toUpperCase(),
        customer_name: billDetails.cust_name,
        customer_phone: billDetails.phone,
        coupon_code_amt: currenttableButton.data.details.coupondiscounttoApply,
        order_id,
      };
      billData.couponDisounthistorydata = couponDisounthistorydata;
    }
    initSaveOrder(billData);
    return 'success';
  }
  window.notifyUser.showMessage(
    'error',
    $.i18n.t('controller:orderController.noItems'),
  );
  $('.neworderButton').prop('disabled', false);
  return 'failure';
}

async function updatetableStatusrequest(params) {
  window.initUpdateTableStatus(params);
}

window.settleBillFromRemote = async function (status, reason) {
  if (reason) {
    if (reason.length > 100) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t(
          'controller:orderWindowNotifications.Reasonlengthshouldbelessthanhundredcharacters',
        ),
      );
      return;
    }
    if (window.specialCharRegex.test(reason)) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t(
          'controller:orderWindowNotifications.Somespecialcharactersarenotallowed',
        ),
      );
      return;
    }
    // billstatusReason = addOrderlevelinstructions(
    //   billstatusReason,
    //   reason,
    //   'Bill Status',
    // );
    orderStatusReason = reason;
  }
  if (status) {
    $('#billstatusModal').modal('hide');
    if ([OrderState.CANCELLED, OrderState.FREE].includes(status)) {
      if (sendotpforOrder) {
        const isotpValid = await askforOTP(
          status,
          currenttableButton.data.details.bill_number,
          OTP_TYPES.ORDER_STATUS_UPDATE,
        );
        if (!isotpValid) return;
      }
      makesettleBillrequest(status);
    }
  }
};

/**
 *
 * @param {Title of the prompt} title
 * @param {*} payment_mode
 */
async function showPaymentadded(title, payment_mode) {
  const result = await Swal.fire({
    title,
    text: `${$.i18n.t(
      'controller:orderController.paymentMethodIsAlreadyProvidedIfYouContinueTheOldMethodWillBeDiscarded',
    )}
     ${$.i18n.t(
       'controller:swalDataTranslations.PaymentModes',
     )} ${payment_mode}`,
    showCancelButton: true,
    allowOutsideClick: false,
    allowEscapeKey: false,
    width: '23em',
    confirmButtonText: $.i18n.t('controller:orderController.Continue'),
    cancelButtonText: $.i18n.t('controller:homeController.Cancel'),
    customClass: {
      popup: 'tmbill-swal-pop-up',
    },
  });
  return result;
}
/**
 * Add's charges to KOT and Bill
 */
async function addCharges() {
  $('#billchargesModal').modal('hide');

  const activeTab = $('.mainsectionTabs li a.active').attr('id');
  let billTotal = 0;
  let forQuickbill = false;
  if (activeTab) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
        billTotal = $('#billGrandtotal').text();
        break;
      case TAKEAWAY_TAB_ID:
        billTotal = $('#takeawaybillGrandtotal').text();
        break;
      case DELIVERY_TAB_ID:
        billTotal = $('#deliverybillGrandtotal').text();
        break;
      case QUICK_TAB_ID:
        forQuickbill = true;
        billTotal = $('#quickbillGrandtotal').text();
        break;

      default:
        break;
    }
  }
  let addtoBillcharges = false;
  if (!forQuickbill) {
    if (
      currenttableButton == undefined ||
      currenttableButton.data == undefined ||
      currenttableButton.data.details == undefined
    ) {
      return;
    }

    if (
      currenttableButton.data.details.bill_number != undefined &&
      currenttableButton.data.details.bill_number != 0
    ) {
      addtoBillcharges = true;
    }
  }

  const selected = [];
  $('#chargeslistId li input:checked').each(function () {
    const rawchargesId = $(this).attr('charge_id');
    if (rawchargesId) {
      selected.push(Number(rawchargesId));
    }
  });
  const defaultchargesRemoved =
    $(`#chargeslistId`).find(`li[is_default="true"] input:checked`).length ===
    0;
  const selectedCharges = [];
  if (selected.length > 0) {
    window.orderCharges.forEach((element) => {
      if (selected.includes(element.charge_id)) {
        selectedCharges.push(element);
      }
    });
  }
  if (forQuickbill) {
    quickbilltableButton.data.details.charges = selectedCharges;
    quickbilltableButton.data.details.defaultchargesRemoved =
      defaultchargesRemoved;

    // quickbilltableButton.data.details.payment_mode = defaultPaymentoption;
    let payment_mode = defaultPaymentoption;
    if (defaultPaymentoption === 'None' || defaultPaymentoption === '0') {
      payment_mode = '';
    }
    quickbilltableButton.data.details.payment_mode = payment_mode;

    quickbilltableButton.data.details.paymentAdded = false;
    if (defaultPaymentoption !== 'None' && defaultPaymentoption !== '0') {
      const paymentDetails = {
        payment_option: defaultPaymentoption,
        amount: billTotal,
      };
      quickbilltableButton.data.details.paymentDetails = paymentDetails;
    }

    precalculateDetailsCheck(quickbilltableButton);
    $(`#quickpayMode_${quickbilltableButton.data.details.payment_mode}`)
      .length > 0
      ? $(
          `#quickpayMode_${quickbilltableButton.data.details.payment_mode}`,
        ).prop('checked', true)
      : $(`#quickpayMode_Other`).prop('checked', true);
    window.notifyUser.showMessage(
      'success',
      $.i18n.t('controller:orderWindowNotifications.Chargesapplied'),
    );
  } else {
    currenttableButton.data.details.charges = selectedCharges;
    currenttableButton.data.details.defaultchargesRemoved =
      defaultchargesRemoved;
    precalculateDetailsCheck(currenttableButton).then(async () => {
      if (activeTab) {
        switch (activeTab) {
          case DINEIN_TAB_ID:
            billTotal = $('#billGrandtotal').text();
            break;
          case TAKEAWAY_TAB_ID:
            billTotal = $('#takeawaybillGrandtotal').text();
            break;
          case DELIVERY_TAB_ID:
            billTotal = $('#deliverybillGrandtotal').text();
            break;
          default:
            break;
        }
      }
      const tempCharges = currenttableButton.data.details.charges;
      const table_id = currenttableButton.id.replace('table_', '');
      const updatepayData = {
        table_id,
        order_id: currenttableButton.data.details.bill_number,
        tempCharges,
        addtoBillcharges,
        billTotal,
        allowchargesafterPrint,
        defaultchargesRemoved,
      };
      if (updatepayData.addtoBillcharges) {
        Object.assign(updatepayData, {
          billupdateData: {
            order_level_total_charges:
              currenttableButton.data.details.order_level_total_charges,
            order_total: currenttableButton.data.details.order_total,
            charges_level_total_tax:
              currenttableButton.data.details.charges_level_total_tax,
            order_level_total_taxes: currenttableButton.data.details.taxtoApply,
            // payment: defaultPaymentoption,
            due_payment: 0,
            // cust_paid_amount: billTotal,
          },
        });
      }
      // Reset the payment details
      if (defaultPaymentoption !== 'None' && updatepayData.billupdateData) {
        Object.assign(updatepayData.billupdateData, {
          payment: defaultPaymentoption,
        });
        currenttableButton.data.details.payment_mode = defaultPaymentoption;
      }
      currenttableButton.data.details.paymentAdded = false;
      // currenttableButton.data.details.cust_paid_amount = billTotal;
      currenttableButton.data.details.due_payment = 0;
      showLoader({
        title: $.i18n.t('controller:orderController.updatingCharges'),
        text: $.i18n.t('controller:orderController.pleaseWait'),
      });
      initUpdateCharges(JSON.stringify(updatepayData));
    });
  }
  $('#chargeslistId li input:checkbox').prop('checked', false);
}

function updateChargesForSplitTable(selectedCharges) {
  const activeTab = $('.mainsectionTabs li a.active').attr('id');
  currenttableButton.data.details.charges = selectedCharges;
  precalculateDetailsCheck(currenttableButton).then(async () => {
    if (activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
          billTotal = $('#billGrandtotal').text();
          break;
        case TAKEAWAY_TAB_ID:
          billTotal = $('#takeawaybillGrandtotal').text();
          break;
        case DELIVERY_TAB_ID:
          billTotal = $('#deliverybillGrandtotal').text();
          break;
        default:
          break;
      }
    }
    const tempCharges = currenttableButton.data.details.charges;
    const table_id = currenttableButton.id.replace('table_', '');
    const updatepayData = {
      table_id,
      order_id: currenttableButton.data.details.bill_number,
      tempCharges,
      addtoBillcharges: true,
      billTotal,
      allowchargesafterPrint,
    };
    if (updatepayData.addtoBillcharges) {
      Object.assign(updatepayData, {
        billupdateData: {
          order_level_total_charges:
            currenttableButton.data.details.order_level_total_charges,
          order_total: currenttableButton.data.details.order_total,
          charges_level_total_tax:
            currenttableButton.data.details.charges_level_total_tax,
          order_level_total_taxes: currenttableButton.data.details.taxtoApply,
          // payment: defaultPaymentoption,
          due_payment: 0,
          // cust_paid_amount: billTotal,
        },
      });
    }

    if (defaultPaymentoption !== 'None' && defaultPaymentoption !== '0') {
      Object.assign(updatepayData.billupdateData, {
        payment: defaultPaymentoption,
      });
      currenttableButton.data.details.payment_mode = defaultPaymentoption;
    }
    // Reset the payment details
    currenttableButton.data.details.paymentAdded = false;
    // currenttableButton.data.details.cust_paid_amount = billTotal;
    currenttableButton.data.details.due_payment = 0;
    initUpdateCharges(JSON.stringify(updatepayData));
    // }
  });
}

