/**
 * Shows the charges pop up window
 * billing_flag: 0=All ,1=Quick Bill, 2=Dine In, 3= TA
 */
async function openChargeswindow(billing_type) {
  $('#chargeslistId li input:checkbox').prop('checked', false);
  $('#searchchargesid').val('');
  if (billing_type == 1) {
    if (
      !quickbilltableButton.data.details.items ||
      quickbilltableButton.data.details.items.length == 0
    ) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.pleaseAddSomeItems'),
      );
      return;
    }

    if (
      quickbilltableButton.data.details.paymentAdded &&
      quickbilltableButton.data.details.payment_mode &&
      quickbilltableButton.data.details.payment_mode !== defaultPaymentoption
    ) {
      const result = await showPaymentadded(
        $.i18n.t('controller:customerHistoryController.charges'),
        quickbilltableButton.data.details.payment_mode,
      );
      if (result.dismiss) {
        return;
      }
    }
    charges = quickbilltableButton.data.details.charges;
    const { defaultchargesRemoved } = quickbilltableButton.data.details;

    if (
      (charges == undefined || charges.length == 0) &&
      !defaultchargesRemoved
    ) {
      if (
        window.defaultquickOrdercharges != undefined &&
        window.defaultquickOrdercharges.length > 0
      ) {
        charges = window.defaultquickOrdercharges;
      }
    }
  } else {
    if (currenttableButton == undefined) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.pleaseSelectTheTable'),
      );
      return;
    }
    if (
      !allowchargesafterPrint &&
      (currenttableButton.data.table_action_flag ==
        TableUtils.State.BILL_PRINTED ||
        currenttableButton.data.details.print_status > 0)
    ) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t(
          'controller:orderController.cannotApplyChargesAfterBillPrinted',
        ),
      );
      return;
    }
    if (
      currenttableButton.data.details.paymentAdded &&
      currenttableButton.data.details.payment_mode &&
      currenttableButton.data.details.payment_mode !== defaultPaymentoption
    ) {
      const result = await showPaymentadded(
        $.i18n.t('controller:customerHistoryController.charges'),
        currenttableButton.data.details.payment_mode,
      );
      if (result.dismiss) {
        return;
      }
    }

    charges = currenttableButton.data.details.charges;
    const { defaultchargesRemoved } = currenttableButton.data.details;
    if (charges == undefined || charges.length == 0) {
      switch (currenttableButton.data.order_type_flag) {
        case TAKEAWAY_FLAG_ID:
          {
            const chargesList = cloneDeep(window.defaulttakeawayOrdercharges);
            if (
              chargesList != undefined &&
              chargesList.length > 0 &&
              !defaultchargesRemoved
            ) {
              charges = chargesList;
            }
          }
          break;
        case HOMED_FLAG_ID:
          {
            const chargesList = cloneDeep(window.defaulthomedOrdercharges);
            if (
              chargesList != undefined &&
              chargesList.length > 0 &&
              !defaultchargesRemoved
            ) {
              charges = chargesList;
            }
          }
          break;
        case DINEIN_FLAG_ID:
        case VIRTUALTABLE_FLAG_ID:
          if (
            defaultdineinOrdercharges != undefined &&
            defaultdineinOrdercharges.length > 0 &&
            !defaultchargesRemoved
          ) {
            if (currenttableButton?.data['mpos_department.section'] == 1) {
              // check if bar section charges is present and remove it
              const filteredCharges = window.defaultdineinOrdercharges.filter(
                (charge) => {
                  const extraDetails = safeParse(charge.extra_details);
                  return extraDetails.bar_section_billing !== 1;
                },
              );
              charges = filteredCharges;
            } else {
              charges = cloneDeep(window.defaultdineinOrdercharges);
            }
          }
          break;
        default:
          break;
      }
      currenttableButton.data.details.charges = charges;
    }
  }

  if (charges && charges.length > 0) {
    charges.forEach((element) => {
      $(`#billcharges_${element.charge_id}`).prop('checked', true);
    });
  }

  const existingCharges = $('#chargeslistId li ');
  let chargestobeShown = 0;
  if (existingCharges && existingCharges.length > 0) {
    existingCharges.each(function () {
      let rawchargesId = $(this).children('input').attr('charge_billing_type');
      rawchargesId = String(rawchargesId);
      const billingTypes = rawchargesId.split(',');
      if (
        billingTypes &&
        (billingTypes.includes(String(billing_type)) ||
          billingTypes.includes('0'))
      ) {
        $(this).show();
        chargestobeShown += 1;
      } else {
        $(this).hide();
        $(this).children('input').prop('checked', false);
      }
    });
  }

  if (chargestobeShown) {
    $('#billchargesModal').modal('show');
  } else {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.nochargesAvailable'),
    );
  }
}

