/**
 * Called after the bill is settled.
 */
async function postSettleprocessing(order_id, orderState) {
  // If silent sync is turned on the the order will
  // be synced.
  sendsilentSyncrequest();
  if (
    window.reduceInventorystatus &&
    !ORDERSTATEFOR_REDUCEINVENTORY.includes(orderState)
  ) {
    initAutoReduceInventory();
  }
  if (
    window.storeDetails.loyalty_enabled &&
    !ORDERSTATEFOR_REDUCEINVENTORY.includes(orderState)
  ) {
    setTimeout(() => {
      sendPointruleactionifexists({
        order_id,
        store_id: window.storeDetails.store_id,
        tmpos_id: window.storeDetails.tmpos_id,
      });
    }, 3000);
  }

  initGetSyncStatus();
  initSendCouponHistory();
  if (window.accessOfCustomerDisplay) {
    window.sendStatetolocalcustomerdisplay({});
  }
}

window.sendsilentSyncrequestfromremote = (forceSync) => {
  sendsilentSyncrequest(forceSync);
};

/**
 * Send's bill sync request
 * @param {Force sync} forceSync
 */
function sendsilentSyncrequest(forceSync) {
  if (!silentautoSyncmode && !navigator.onLine) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.noInternetConnection'),
    );
    return;
  }
  // if (
  //   window.storeDetails.loyalty_enabled ||
  //   window.storeDetails.live_tracking_enabled
  // ) {
  //   forceSync = true;
  // }
  if (silentautoSyncmode && navigator.onLine) {
    ipcRenderer.send(
      SYNC_BILL,
      JSON.stringify({ silentSync: true, logout: false, forceSync }),
    );
  } else if (forceSync && navigator.onLine) {
    $('#syncIndicatorid').addClass('fa-spin');
    ipcRenderer.send(
      SYNC_BILL,
      JSON.stringify({ silentSync: true, logout: false, forceSync }),
    );
  }
}

ipcRenderer.on(ORDER_IPC.SENT_REDUCEINVENTORY_REQUEST_REPLY, async () => {});
/**
 * Settle's the bill
 */
async function makesettleBillrequest(order_state) {
  if (checkSystemDate) {
    const targetDate = moment(window.currentDateFetchedFromBackend);
    const currentDate = moment();
    if (!currentDate.isSame(targetDate, 'day')) {
      getLatestDate();
      window.notifyUser.showMessage('error', 'System date is not upto date');
      return;
    }
  }

  if (!calculationDone) {
    return;
  }
  if (currenttableButton?.data?.details?.isBillModified == 2) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderWindowNotifications.Pleasesavebillfirst'),
    );
    return;
  }

  if (window.settlebillisinProgress) {
    return;
  }
  let sendCustomerinfotodboy = false;
  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }

  if (
    currenttableButton.data.details.bill_number != undefined &&
    currenttableButton.data.details.bill_number == 0
  ) {
    if (fastsettlePopupisopen) {
      Swal.showValidationMessage(
        $.i18n.t('controller:orderController.saveTheBillFirst'),
      );
      $('input.swal-fast-action-button').prop('disabled', false);
    } else
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.saveTheBillFirst'),
      );
    return;
  }

  // check waiter and customers before settle order

  switch (currenttableButton.data.order_type_flag) {
    case DINEIN_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.dinein &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    case TAKEAWAY_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.takeaway &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    case HOMED_FLAG_ID:
      if (
        editcustomerSettings &&
        editcustomerSettings.delivery &&
        !Object.values(currenttableButton.data.details.customer).length
      ) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.customerDetailsAreRequired'),
        );
        return 'failure';
      }
      break;

    default:
      break;
  }

  if (
    (currenttableButton.data.order_type_flag === 0 ||
      currenttableButton.data.details.order_type_flag === 'Dine In') &&
    askfordineinWaiterFirst &&
    !currenttableButton.data.details.waiter_id
  ) {
    window.notifyUser.showMessage(
      'error',
      'Waiter not seleced. Please select waiter first',
    );
    return;
  }
  if (
    currenttableButton.data.order_type_flag === 1 &&
    askfortahdWaiterFirst &&
    !currenttableButton.data.details.waiter_id
  ) {
    window.notifyUser.showMessage(
      'error',
      'Waiter not seleced. Please select waiter first',
    );
    return;
  }

  if (
    currenttableButton.data.order_type_flag === 2 &&
    askfordeliveryWaiterFirst &&
    !currenttableButton.data.details.waiter_id
  ) {
    window.notifyUser.showMessage(
      'error',
      'Waiter not seleced. Please select waiter first',
    );
    return;
  }
  if (
    ![OrderState.FREE, OrderState.CANCELLED].includes(order_state) &&
    !currenttableButton.data.details.payment_modes.length &&
    !currenttableButton.data.details.addasdueChecked
  ) {
    window.notifyUser.showMessage('error', 'Please select payment mode');
    return;
  }

  if (fastsettlePopupisopen) {
    const waiterTipAmount = $('#swalfastwaiterTipinput').val();
    // if(waiterTipAmount && !currenttableButton.data.details.waiter){
    //    Swal.showValidationMessage($.i18n.t('Waiter not added. Please add waiter'));
    //    $('input.swal-fast-action-button').prop("disabled", false);
    // }

    if (waiterTipAmount) {
      const waiterTipDetails = {
        store_id: window.storeDetails.store_id,
        order_id: currenttableButton.data.details.bill_number,
        amount: waiterTipAmount,
        waiter: currenttableButton.data.details.waiter,
        waiter_id: currenttableButton.data.details.waiter_id,
      };

      if (currenttableButton.data.details.extra_details) {
        Object.assign(currenttableButton.data.details.extra_details, {
          total_tip: waiterTipAmount,
        });
      }
      if (waiterTipDetails && waiterTipDetails.amount) {
      }
    }
  }
  if (
    currenttableButton.data.details.items == undefined ||
    currenttableButton.data.details.items.length == 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderWindowNotifications.NoItems'),
      0,
    );
    return;
  }
  showLoader({
    title: $.i18n.t('controller:orderController.settlingBill'),
    text: $.i18n.t('controller:orderController.pleaseWait'),
  });
  await precalculateDetailsCheck(currenttableButton);

  if (order_state === undefined) {
    order_state = OrderState.FULFILLED;
  }
  let billTotal = Number(
    currenttableButton.data.details.order_total.toFixed(ROUNDOFF_UPTO),
  );
  let isPreorder;
  const table_id = currenttableButton.id.replace('table_', '');
  const { extra_details } = currenttableButton.data.details;

  switch (currenttableButton.data.order_type_flag) {
    case TAKEAWAY_FLAG_ID:
      {
        $('#tatable-actions-divid *').prop('disabled', true);
        $('#tablesContainer *').prop('disabled', true);
        isPreorder = $('#takeawayPreordercheckid').is(':checked');
        if (!billTotal) billTotal = $('#takeawaybillGrandtotal').text();

        if ($('#takeawaytransferordercheckid').is(':checked')) {
          Object.assign(extra_details, { is_transfer_order: 1 });
        }
      }
      break;
    case HOMED_FLAG_ID:
      {
        $('#tatable-actions-divid *').prop('disabled', true);
        $('#tablesContainer *').prop('disabled', true);
        isPreorder = $('#deliveryPreordercheckid').is(':checked');
        if (!billTotal) billTotal = $('#deliverybillGrandtotal').text();
        if (isSendCustomerDetailsToDBoyEnabled) {
          if (currenttableButton.data.details.customer == undefined) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectCustomer'),
            );
            $('#tatable-actions-divid *').prop('disabled', false);
            $('#tablesContainer *').prop('disabled', false);
            return;
          }
          // const selection = $(
          //   '#dboyselectionfordeliveryId option:selected:not([disabled])',
          // );
          // const selection = $(
          //   "input:radio[name='deliveryBoyButton']:checked",
          // ).val();
          const selection = $(`#deliveryBoyNamelabelid`).text();
          if (!selection) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectDeliveryBoy'),
            );
            $('#tatable-actions-divid *').prop('disabled', false);
            $('#tablesContainer *').prop('disabled', false);
            return;
          }
          sendCustomerinfotodboy = true;
        }

        if (deliveryBoyMandatory) {
          // const selection = $(
          //   "input:radio[name='deliveryBoyButton']:checked",
          // ).val();
          const selection = $(`#deliveryBoyNamelabelid`).text();
          if (!selection) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectDeliveryBoy'),
            );
            $('#tatable-actions-divid *').prop('disabled', false);
            $('#tablesContainer *').prop('disabled', false);
            return;
          }
        }
        if ($('#deliverytransferordercheckid').is(':checked')) {
          Object.assign(extra_details, { is_transfer_order: 1 });
        }
      }
      break;
    case DINEIN_FLAG_ID:
    case VIRTUALTABLE_FLAG_ID:
      {
        $('#table-actions-divid *').prop('disabled', true);
        $('#tablesContainer *').prop('disabled', true);
        if (!billTotal) billTotal = $('#billGrandtotal').text();
        if ($('#transferordercheckid').is(':checked')) {
          Object.assign(extra_details, { is_transfer_order: 1 });
        }
      }
      break;
    default:
      break;
  }

  if (
    currenttableButton.data.details &&
    currenttableButton.data.details.is_pre_order
  ) {
    Object.assign(extra_details, { is_pre_order: 1 });

    if (currenttableButton.data.details.preorderInfo) {
      const formattedDate = moment(
        currenttableButton.data.details.preorderInfo.delivery_at,
      ).format('YYYY-MM-DD HH:mm:ss');
      Object.assign(extra_details, {
        delivery_at: currenttableButton.data.details.preorderInfo.delivery_at,
        delivered_at: formattedDate,
      });
    }
  }

  if (!billstatusReason) {
    billstatusReason = '';
  }

  if (!orderStatusReason) {
    orderStatusReason = '';
  }

  // let extra_details = currenttableButton.data.details.extra_details;
  const { items } = currenttableButton.data.details;

  const billupdateData = {
    order_state,
    order_total: billTotal,
    store_id:
      window.storeDetails && window.storeDetails.store_id
        ? window.storeDetails.store_id
        : '',
    user_id: window.storeDetails.username,
    order_level_total_charges:
      currenttableButton.data.details.order_level_total_charges,
    charges_level_total_tax:
      currenttableButton.data.details.charges_level_total_tax,
    order_subtotal: currenttableButton.data.details.order_subtotal,
    // discount:
    //   Number(currenttableButton.data.details.discounttoApply) +
    //   Number(currenttableButton.data.details.coupondiscounttoApply),
    discount: Number(currenttableButton.data.details.discounttoApply),
    order_level_total_taxes: currenttableButton.data.details.taxtoApply,
    instructions: billstatusReason,
    field1: orderStatusReason,
    couponDisounttotal: Number(
      currenttableButton.data.details.coupondiscounttoApply,
    ),
    issectionwisebilling: currenttableButton.data.details.issectionwisebilling,
    // cust_paid_amount: currenttableButton.data.details.cust_paid_amount !== undefined
    //    ? currenttableButton.data.details.cust_paid_amount
    //    : billTotal,
    // cust_paid_amount:
    //   currenttableButton.data.details.cust_paid_amount &&
    //   currenttableButton.data.details.cust_paid_amount,
    extra_details: extra_details || {},
    charges: currenttableButton.data.details.totalCharges,
    item_level_total_charges:
      currenttableButton.data.details.item_level_total_charges,
    sync_status: SYNC_STATUS_FLAG.NOT_SYNCED,
    countMidnightSale,
    orderItems: items,
    app_source: 'atlantic_pos',
  };

  if (
    currenttableButton.data.details.due_payment &&
    currenttableButton?.data?.details?.payment_mode &&
    !currenttableButton?.data?.details?.payment_mode?.toLowerCase() === 'split'
  ) {
    Object.assign(billupdateData, { payment: '' });
    // currenttableButton.data.details.payment_mode = "Due"
  }
  // if(!fastsettlePopupisopen){
  //    billupdateData.cust_paid_amount = billTotal
  // }
  // return

  if (order_state === OrderState.FREE) {
    Object.assign(billupdateData, { payment: '' });
  }

  const billData = {
    billupdateData,
    order_id: currenttableButton.data.details.bill_number,
    table_id,
    table_color: TableUtils.Colors.FREE_TABLE,
    table_action_flag: TableUtils.State.FREE_TABLE,
    order_state,
    order_type_flag: currenttableButton.data.order_type_flag,
  };

  if (currenttableButton?.data?.details?.reservation_id) {
    Object.assign(billData, {
      reservation_id: currenttableButton.data.details.reservation_id,
    });
  }
  if (isPreorder && currenttableButton.data.details.preorderInfo) {
    Object.assign(billData, {
      is_pre_order: isPreorder,
    });
  }

  if (
    !currenttableButton.data.details.payment_mode &&
    !currenttableButton.data.details.due_payment
  ) {
    paymentDetails = {
      order_id: currenttableButton.data.details.bill_number,
      payment_option: defaultPaymentoption,
      store_id: window.storeDetails.store_id,
      amount: billTotal,
      isSplitpayment: false,
    };
    billData.paymentDetails = paymentDetails;
  }

  if (
    currenttableButton.data.details.discountHistory &&
    Array.isArray(currenttableButton.data.details.discountHistory) &&
    currenttableButton.data.details.discountHistory.length > 0
  ) {
    billData.discountHistory = currenttableButton.data.details.discountHistory;
  }

  billstatusReason = undefined;
  orderStatusReason = undefined;
  if (sendCustomerinfotodboy) {
    // const selection = $('#dboyselectionId option:selected:not([disabled])');
    // const selection = $("input:radio[name='deliveryBoyButton']:checked");
    const selection = $(`#deliveryBoyNamelabelid`).text();
    if (selection) {
      // const delivery_boy_phone = $(selection).attr('phone');
      const dboy = window.deliveryBoys.find((d) => d.name === selection);
      sendCustomersinfotodboy({
        customer: currenttableButton.data.details.customer,
        delivery_boy_phone: dboy?.phone,
        bill_amount: billTotal,
        order_id: billData.order_id,
      });
    }
  }
  if (
    !openCashDrawerOnPaymetWindow &&
    currenttableButton.data.details.payment_mode === 'Cash'
  ) {
    openCashDrawerRequest();
  }
  window.settlebillisinProgress = true;
  await new Promise((r) => setTimeout(r, 900));
  initSettleOrder(billData);
  if (showOrderstatusontable) {
    $('#orderstateSelectid').val($('#orderstateSelectid option:first').val());
  }
  $('#neworderpaymentModalid').modal('hide');
}

async function settleQuickprecalculations() {
  let { charges } = quickbilltableButton.data.details;
  const { defaultchargesRemoved } = quickbilltableButton.data.details;
  if ((charges == undefined || charges.length == 0) && !defaultchargesRemoved) {
    charges = window.defaultquickOrdercharges;
    quickbilltableButton.data.details.charges = charges;
    await precalculateDetailsCheck(quickbilltableButton);
  }
  if (defaultCustomizeddiscount != undefined) {
    try {
      await applyCustomizediscount(defaultCustomizeddiscount, true);
    } catch (error) {}
  }
  if (
    window.accessOfCustomerDisplay &&
    quickbilltableButton &&
    quickbilltableButton.data &&
    quickbilltableButton.data.details.items
  ) {
    const state = {
      total: Number(quickbilltableButton?.data?.details?.order_total).toFixed(
        window.ROUNDOFF_UPTO,
      ),
      items: quickbilltableButton?.data?.details?.items,
      billNumber: 0,
      qrCode: null,
    };
    window.sendStatetolocalcustomerdisplay(state);
  }
}

let orderid_for_quickBill;
/**
 * Settles the quick bill request
 */
async function settlequickBill() {
  if (
    window.validateCustomerBeforeSaveOrPrint &&
    !window.validateCustomerBeforeSaveOrPrint()
  ) {
    return;
  }
  if (checkSystemDate) {
    const targetDate = moment(window.currentDateFetchedFromBackend);
    const currentDate = moment();
    if (!currentDate.isSame(targetDate, 'day')) {
      getLatestDate();
      window.notifyUser.showMessage('error', 'System date is not upto date');
      return;
    }
  }

  const selectedCustomOrderType = $('#customQuickBillTypeid').text();
  if (
    askCustomOrderTypeInQuickBill &&
    selectedCustomOrderType === 'New Order'
  ) {
    $('#customQuickBillTypeid').click();
    return;
  }

  if (quickbilltableButton) {
    if (
      !quickbilltableButton.data.details.items ||
      quickbilltableButton.data.details.items.length == 0
    ) {
      window.notifyUser.showMessage(
        'error',
        $.i18n.t('controller:orderController.pleaseAddSomeItems'),
      );
      return;
    }
    if (
      quickbilltableButton.data.details.items != undefined &&
      quickbilltableButton.data.details.items.length > 0
    ) {
      let { charges } = quickbilltableButton.data.details;
      const { defaultchargesRemoved } = quickbilltableButton.data.details;
      if (
        (charges == undefined || charges.length == 0) &&
        !defaultchargesRemoved
      ) {
        charges = window.defaultquickOrdercharges;
        quickbilltableButton.data.details.charges = charges;
        await precalculateDetailsCheck(quickbilltableButton);
      }

      if (
        defaultCustomizeddiscount != undefined &&
        !quickbilltableButton.data.details.discount
      ) {
        try {
          await applyCustomizediscount(defaultCustomizeddiscount, true);
          await sleep(100);
        } catch (error) {}
      }

      let billTotal = quickbilltableButton.data.details.order_total;
      if (!billTotal) billTotal = $('#quickbillGrandtotal').text();

      let customer_name = $('#quickbillkotcustomernameField').val();
      let customer_mobile = $('#quickbillkotcustomermobileField').val();
      customer_name = customer_name ? customer_name.trim() : '';
      customer_mobile = customer_mobile ? customer_mobile.trim() : '';
      const table_id = quickbilltableButton.id.replace('table_', '');
      const persons = $('#quickbillnoofpersonsField').val();
      const { items } = quickbilltableButton.data.details;
      // if reduce stock check item stock
      // this is for buy x get y item
      if (reduceStock) {
        // group by item_refid
        let proceed = true;
        const groupedItems = _(items)
          .groupBy('item_refid')
          .map((group, refid) => {
            // Combine and process grouped items
            const title = _.uniq(group.map((item) => item.title)).join(', ');
            const quantity = _.sumBy(group, 'quantity');
            const amount = _.sumBy(group, 'amount');
            const discounts = _.flatMap(group, (item) =>
              JSON.parse(item.discounted_items || '[]'),
            );
            const { current_stock } = group[0];

            return {
              item_refid: parseInt(refid),
              title,
              quantity,
              amount,
              discounts,
              current_stock,
            };
          })
          .value();

        if (groupedItems && groupedItems.length) {
          groupedItems.forEach((gItem) => {
            if (gItem.quantity > gItem.current_stock) {
              proceed = false;
              window.notifyUser.showMessage(
                'error',
                `Only ${gItem.current_stock} stock available of ${gItem.title} item.`,
              );
            }
          });
        }
        if (!proceed) {
          return;
        }
      }

      const kotNote = $('#quickbillkotnoteField').val();
      // validations
      if (kotNote) {
        if (kotNote.length > 100) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.KOTnoteshouldbelessthanHundredcharacters',
            ),
          );
          return;
        }

        if (window.someSpecialCharRegex.test(kotNote)) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Specialcharactersarenotallowedinkotnote',
            ),
          );
          return;
        }
      }

      if (customer_name) {
        if (customer_name.length > 100) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Customernameshouldbelessthanhundredcharacters',
            ),
          );
          return;
        }

        if (window.specialCharRegex.test(customer_name)) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Specialcharactersarenotallowedincustomername',
            ),
          );
          return;
        }
      }

      if (customer_name && !customer_mobile) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t(
            'controller:orderWindowNotifications.Mobilenumberismandatory',
          ),
        );
        return;
      }

      if (customer_mobile) {
        if (customer_mobile.length > 15) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.MobilenumberlengthshouldbelessthanFifteendigit',
            ),
          );
          return;
        }
      }

      // if (isNaN(customer_mobile)) {
      //   window.notifyUser.showMessage(
      //     'error',
      //     'Please enter valid mobile number',
      //   );
      //   return;
      // }

      if (persons) {
        if (persons < 0) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t('Covers/guest should not be in negative number'),
          );
          return;
        }
        if (persons.length > 3) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.CoversGuestslengthshouldbelessthanthreedigit',
            ),
          );
          return;
        }
        if (isNaN(persons)) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Pleaseentervalidcoversguest',
            ),
          );
          return;
        }
        if (!Number.isInteger(Number(persons))) {
          window.notifyUser.showMessage(
            'error',
            'Covers value should not be in decimal',
          );
          return;
        }
      }

      if (dynamiccustomerAddressforquickbill) {
        if (dynamiccustomerAddressforquickbill.length > 800) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.CustomerAddressshouldbelessthantwohundredcharacters',
            ),
          );
          return;
        }

        // if (window.specialCharRegex.test(dynamiccustomerAddressforquickbill)) {
        //   window.notifyUser.showMessage(
        //     'error',
        //     $.i18n.t(
        //       'controller:orderWindowNotifications.Specialcharactersarenotallowedinaddress',
        //     ),
        //   );
        //   return;
        // }
      }

      if (!persons && askforquickbillcoversFirst) {
        await askforCoversifneeded(QUICK_TAB_ID, true);
        return;
      }

      if (editcustomerSettings && editcustomerSettings.quick) {
        if (!customer_name || !customer_mobile) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t('controller:orderController.customerDetailsAreRequired'),
          );
          return 'failure';
        }
      }
      const { addasdueChecked } = quickbilltableButton.data.details;
      let { due_payment } = quickbilltableButton.data.details;
      let { paymentDetails } = quickbilltableButton.data.details;

      if (defaultPaymentoption === 'None' && !paymentDetails) {
        window.notifyUser.showMessage('error', 'Please select payment mode');
        return;
      }

      settleQuickBillIsInProcress = true;
      showLoader({
        title: $.i18n.t('controller:orderController.settlingBill'),
        text: $.i18n.t('controller:orderController.pleaseWait'),
      });

      if (!due_payment) {
        due_payment = 0;
      }
      // Find if customer exists Quick Bill
      let updateAddress;
      let updateCustomerName = false;
      let customer = getCustomer(false, customer_mobile);

      if (customer && customer.name !== customer_name) {
        updateCustomerName = true;
        Object.assign(customer, {
          name: customer_name,
        });
      }
      if (updateCustomerName) {
        reinitCustomersinfo = true;
      }

      if (customer_mobile && !customer_name) {
        customer_name = customer_mobile;
      }
      const dial_code = $('#quickbillkotdialcodeFieldid option:selected').val();
      if (!customer && customer_name && customer_mobile) {
        customer = {
          name: customer_name,
          phone: customer_mobile,
          email: '',
          store_id: window.storeDetails.store_id,
          address_line1: dynamiccustomerAddressforquickbill,
          address_line2: '',
          city: '',
          createdDate: moment().format('YYYY-MM-DD'),
          dial_code,
        };
        Object.assign(customer, {
          ...newCustomerAddressForQuickBill,
        });
        sendCustomerandaddtoListenerfromremote(customer, true);
      } else if (
        customer &&
        customer.phone &&
        dynamiccustomerAddressforquickbill
      ) {
        let address = customer.address_line1 ? customer.address_line1 : '';
        address += customer.address_line2 ? customer.address_line2 : '';
        updateAddress =
          dynamiccustomerAddressforquickbill !== address
            ? dynamiccustomerAddressforquickbill
            : undefined;
        if (updateAddress) {
          reinitCustomersinfo = true;
        }
      }
      quickbilltableButton.data.details.customer = customer;

      const { extra_details } = quickbilltableButton.data.details;
      if ($('#quickbilltransferordercheckid').is(':checked')) {
        Object.assign(extra_details, { is_transfer_order: 1 });
      }

      if (askCustomeOrderId && quickCustomorderId) {
        Object.assign(extra_details, { customOrderId: quickCustomorderId });
      }

      let order_id = window.generateId();
      if (orderid_for_quickBill) {
        order_id = orderid_for_quickBill;
      }

      if (paymentDetails == undefined) {
        // if (
        //   [
        //     OnlineBillingTypeByName.ZOMATO,
        //     OnlineBillingTypeByName.SWIGGY,
        //   ].includes(defaultcustomerQuickordertype)
        // ) {
        //   paymentDetails = {
        //     order_id,
        //     payment_option: 'Online Paid',
        //     amount: billTotal,
        //     isSplitpayment: false,
        //   };
        // } else {
        //   paymentDetails = {
        //     order_id,
        //     payment_option: defaultPaymentoption,
        //     amount: billTotal,
        //     isSplitpayment: false,
        //   };
        // }

        paymentDetails = {
          order_id,
          payment_option: defaultPaymentoption,
          amount: billTotal,
          isSplitpayment: false,
        };

        // if (
        //   [
        //     QUICKBILL_BILLING_FLAG,
        //     DINEIN_BILLING_FLAG,
        //     TAKEAWAY_BILLING_FLAG,
        //     HOMED_BILLING_FLAG,
        //   ].includes(defaultcustomerQuickordertype)
        // ) {
        //   paymentDetails = {
        //     order_id,
        //     payment_option: defaultPaymentoption,
        //     amount: billTotal,
        //     isSplitpayment: false,
        //   };
        // } else {
        //   paymentDetails = {
        //     order_id,
        //     payment_option: 'Online Paid',
        //     amount: billTotal,
        //     isSplitpayment: false,
        //   };
        // }
      } else if (paymentDetails.isSplitpayment && paymentDetails.payList) {
        paymentDetails.payList.forEach((element) => {
          element.order_id = order_id;
        });
      } else {
        paymentDetails.order_id = order_id;
        paymentDetails.amount = billTotal;
      }
      if (!paymentDetails.order_id) {
        Object.assign(paymentDetails, {
          order_id,
        });
      }

      const payment = paymentDetails.payment_option;

      const { waiter } = quickbilltableButton.data.details;
      const { waiter_id } = quickbilltableButton.data.details;

      quickbilltableButton.data.details.createdBy =
        window.storeDetails.username;

      // if (!customer_name && !customer_mobile) {
      //   customer_name = 'POS User';
      //   customer_mobile = '9090909090';
      // }

      Object.assign(extra_details, { invoiceType: 'B2C' });

      const billDetails = {
        order_total: billTotal,
        table_name: quickbilltableButton.content,
        table_id,
        // cust_name: customer != undefined ? customer.name : customer_name,
        cust_name: customer_name,
        phone: customer != undefined ? customer.phone : customer_mobile,
        email: customer != undefined ? customer.email : '',
        line_1: customer != undefined ? customer.address_line1 : '',
        line_2: customer != undefined ? customer.address_line2 : '',
        persons,
        order_state: OrderState.FULFILLED,
        discount: Number(quickbilltableButton.data.details.discounttoApply),
        // +
        // Number(quickbilltableButton.data.details.coupondiscounttoApply),
        discount_title: quickbilltableButton.data.details.discount_title,
        order_level_total_taxes: quickbilltableButton.data.details.taxtoApply,
        order_id,
        order_subtotal: quickbilltableButton.data.details.order_subtotal,
        order_level_total_charges:
          quickbilltableButton.data.details.order_level_total_charges,
        charges_level_total_tax:
          quickbilltableButton.data.details.charges_level_total_tax,
        store_id: window.storeDetails.store_id,
        user_id: window.storeDetails.username,
        billing_type: defaultcustomerQuickordertype,
        payment,
        createdBy: window.storeDetails.username,
        couponDisounttotal:
          quickbilltableButton.data.details.coupondiscounttoApply,
        couponDisount: quickbilltableButton.data.details.couponDisountamt,
        couponDisounttype: quickbilltableButton.data.details.couponDisounttype,
        coupon: quickbilltableButton.data.details.coupon,
        note: $('#quickbillkotnoteField').val(),
        due_payment,
        hasDuepayment: due_payment > 0 ? 1 : 0,
        order_kotflag: 2, // Marking as placed to Use in KDS,
        cust_paid_amount: quickbilltableButton.data.details.cust_paid_amount,
        waiter,
        waiter_id,
        issectionwisebilling: ISBILLINGBYSECTION_ON,
        extra_details: extra_details || {},
        charges: quickbilltableButton.data.details.totalCharges,
        item_level_total_charges:
          quickbilltableButton.data.details.item_level_total_charges,
        discounted_product_groups: quickbilltableButton.data.details
          .discounted_product_groups
          ? quickbilltableButton.data.details.discounted_product_groups
          : '',
        instructions: quickbilltableButton.data.details.instructions,
        updateAddress,
        updateCustomerName,
        newCustomerAddress: newCustomerAddressForQuickBill,
        waiterTipDetails: quickbilltableButton.data.details.waiterTipDetails,
        app_source: 'atlantic_pos',
        // quick_custom_order_id:quickCustomorderId
      };
      if (
        quickbilltableButton.data.details.due_payment &&
        quickbilltableButton.data.details.due_payment === billTotal
      ) {
        Object.assign(billDetails, { payment: '', cust_paid_amount: 0 });
      }

      if (fastsettlePopupisopen) {
        const waiterTipAmount = Number(
          quickbilltableButton.data.details.fastSettletipAmt,
        );

        if (waiterTipAmount) {
          const waiterTipDetails = {
            store_id: window.storeDetails.store_id,
            order_id,
            amount: waiterTipAmount,
            waiter,
            waiter_id,
          };

          if (extra_details) {
            Object.assign(extra_details, { total_tip: waiterTipAmount });
          }
          Object.assign(billDetails, { waiterTipDetails });
        }
      }

      // in case of buy x get y, y item can repeate and we don't allow duplicae items
      let groupedItems = items;
      // console.log(
      //   `Message="Quick bill order items" items=`,
      //   JSON.stringify(items),
      // );
      const filteredItems = _.chain(items)
        .groupBy((item) => `${item.title}-${item.price}-${item.item_refid}`)
        .map((platform, id) => ({
          ...platform[0],
          kitchen_dept: platform[0].kitchen_dept,
          quantity: _.sumBy(platform, 'quantity'), // Sum of quantities
          amount: _.sumBy(platform, 'amount'), // Sum of amounts
        }))
        .value();
      if (filteredItems && filteredItems.length) {
        groupedItems = filteredItems;
      }

      let printBill = $('#quickbillprintCheck').is(':checked');
      const printKOTstat = $('#quickkotprintCheck').is(':checked');
      if (paymentDetails && paymentDetails.printBill === 0) {
        printBill = false;
      }

      if (paymentDetails && paymentDetails.printBill === 1) {
        printBill = true;
      }
      const billData = {
        paymentDetails,
        billDetails,
        items: groupedItems,
        charges,
        printKOT: printKOTstat,
        printBill,
        addasdueChecked,
        countMidnightSale,
      };

      // if order has discount history
      if (
        quickbilltableButton.data.details.discountHistory &&
        Array.isArray(quickbilltableButton.data.details.discountHistory) &&
        quickbilltableButton.data.details.discountHistory.length > 0
      ) {
        billData.discountHistory =
          quickbilltableButton.data.details.discountHistory;
      }

      if (addasdueChecked && due_payment != 0 && billDetails.phone) {
        billData.dueHistory = {
          order_id,
          due_payment,
          due_amount: due_payment,
          store_id: window.storeDetails.store_id,
          billing_user_id: window.storeDetails.username,
          amount_to_pay: billTotal,
          received_amount: quickbilltableButton.data.details.received_amount,
          payment_info: quickbilltableButton.data.details.payment_info,
          cust_mobile: billDetails.phone,
        };
        Object.assign(billDetails, {
          hasDuepayment: 1,
        });
      }

      if (
        quickbilltableButton.data.details.discountHistory &&
        Array.isArray(quickbilltableButton.data.details.discountHistory) &&
        quickbilltableButton.data.details.discountHistory.length > 0
      ) {
        billData.discountHistory =
          quickbilltableButton.data.details.discountHistory;
      }

      if (
        billDetails.coupon != undefined &&
        billDetails.couponDisount > 0 &&
        billDetails.couponDisounttotal > 0
      ) {
        // Check for Coupon discount
        const couponDisounthistorydata = {
          store_id: window.storeDetails.store_id,
          tmpos_id: window.storeDetails.tmpos_id,
          logedin_user: window.storeDetails.username,
          coupon_code: String(billDetails.coupon).toUpperCase(),
          customer_name: $('#quickbillkotcustomernameField').val(),
          customer_phone: $('#quickbillkotcustomermobileField').val(),
          coupon_code_amt: billDetails.couponDisounttotal,
          order_id,
        };
        billData.couponDisounthistorydata = couponDisounthistorydata;
      }
      if (defaultcustomerQuickordertype !== QUICKBILL_BILLING_FLAG) {
        Object.assign(billDetails, {
          // table_name: BillingTypes[defaultcustomerQuickordertype],
          table_name:
            (window.orderTypes &&
              window.orderTypes[Number(defaultcustomerQuickordertype)]
                ?.order_type) ||
            'Quick Bill',
        });

        if (extra_details) {
          Object.assign(extra_details, {
            customQuickbilltype: true,
          });
          Object.assign(billDetails, {
            extra_details,
          });
        }
      }
      if (
        billData.paymentDetails.payment_option === 'Cash' ||
        billData.paymentDetails.payment_option === 'Split'
      ) {
        let openDrawer = true;
        if (
          billData.paymentDetails.paymentName === 'Split' &&
          billData.paymentDetails.payList &&
          billData.paymentDetails.payList.length
        ) {
          const cashPayment = billData.paymentDetails.payList.find(
            (p) => p.payment_option === 'Cash',
          );
          if (!cashPayment) {
            openDrawer = false;
          }
        }
        if (openDrawer) {
          openCashDrawerRequest();
        }
      }
      initSettleQuickBill(JSON.stringify(billData));
      $('#quickbillsettleButton').prop('disabled', true);
      $('#neworderpaymentModalid').modal('hide');

      // posytude
      if (
        window.settingsConfig[POSYTUDE_PORT - 1] != undefined &&
        window.settingsConfig[POSYTUDE_PORT - 1].value !== '0'
      ) {
        const orderDetail = {};
        orderDetail.amount = billTotal || 0.0;
        betteripcRenderer.callMain(
          'IPC_EVENT:SERIAL_PORT:DISPLAY_AMOUNT',
          orderDetail,
        );
      }

      // //generate qr code
      // let code = '';
      // if (window.storeDetails.upi_id) {
      //   code = `upi://pay?pa=${window.storeDetails.upi_id}&pn=${
      //     window.storeDetails.store_name
      //   }&cu=${window.storeDetails.currency_code}&am=${billTotal.toFixed(
      //     ROUNDOFF_UPTO,
      //   )}`;
      //   // code = code + `&tr=${orderid}`;
      // }
      // //send data of quick bill for customer display
      // sendQuickBillPlacedEvent({
      //   items,
      //   order_total: billTotal,
      //   message: 'Quick bill placed',
      //   Payment_qr: code,
      // });
    }
  }
}

async function showQuickBillDataForCustomerDisplay() {
  if (
    !quickbilltableButton.data.details.items ||
    quickbilltableButton.data.details.items.length == 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseAddSomeItems'),
    );
    return;
  }
  isShowBillToCustomerDPClicked = true;

  orderid_for_quickBill = window.generateId();
  $('#quickbillTable tbody tr td').each(function () {
    $(this).find('button').prop('disabled', true);
    $(this).find('i').prop('disabled', true);
    $(this).find('.item-qty-editable-row').attr('contenteditable', false);
    $(this).find('.item-amount-editable-row').attr('contenteditable', false);
  });
  $('#quickdiscountButton').addClass('disable-click');
  $('#quickchargesButton').addClass('disable-click');
  $('#quickbillrewardsButton').addClass('disable-click');
  $('#quickcoupondiscountButton').addClass('disable-click');
  $('#quickbillclearkotButton').addClass('disable-click');

  // generate bharatpe upi string
  const orderid = orderid_for_quickBill;
  const orderAmount = quickbilltableButton.data.details.order_total
    ? quickbilltableButton.data.details.order_total
    : 0;

  if (window.isbharatpeConfigured && orderAmount && orderid) {
    const bharatPeQRCode = await generateBharatpeQR({
      order_id: orderid,
      amount: orderAmount,
    });
    let code;
    if (bharatPeQRCode) {
      code = bharatPeQRCode;
    }
    sendQuickBillPlacedEvent({
      items: quickbilltableButton?.data?.details?.items,
      order_total: quickbilltableButton.data.details.order_total
        ? quickbilltableButton.data.details.order_total
        : 0,
      message: 'Quick bill placed',
      Payment_qr: code,
    });
    if (window.accessOfCustomerDisplay) {
      const state = {
        total: Number(quickbilltableButton.data.details.order_total).toFixed(
          window.ROUNDOFF_UPTO,
        ),
        items: quickbilltableButton?.data?.details?.items,
        billNumber: 0,
        qrCode: code,
      };

      window.sendStatetolocalcustomerdisplay(state);
    }
  } else if (window.isPhonePeConfigured && orderAmount && orderid) {
    const phonePeQRCode = await generatePhonepeQR({
      order_id: orderid,
      amount: orderAmount,
    });
    let code;
    if (phonePeQRCode) {
      code = phonePeQRCode;
    }
    sendQuickBillPlacedEvent({
      items: quickbilltableButton?.data?.details?.items,
      order_total: quickbilltableButton.data.details.order_total
        ? quickbilltableButton.data.details.order_total
        : 0,
      message: 'Quick bill placed',
      Payment_qr: code,
    });
    if (window.accessOfCustomerDisplay) {
      const state = {
        total: Number(quickbilltableButton.data.details.order_total).toFixed(
          window.ROUNDOFF_UPTO,
        ),
        items: quickbilltableButton?.data?.details?.items,
        billNumber: 0,
        qrCode: code,
      };

      window.sendStatetolocalcustomerdisplay(state);
    }
  } else {
    // generate qr code
    let code = '';
    if (window.storeDetails.upi_id) {
      code = `upi://pay?pa=${window.storeDetails.upi_id}&pn=${
        window.storeDetails.store_name
      }&cu=${window.storeDetails.currency_code}&am=${orderAmount.toFixed(
        ROUNDOFF_UPTO,
      )}`;
      // code = code + `&tr=${orderid}`;
    }
    // send data of quick bill for customer display
    sendQuickBillPlacedEvent({
      items: quickbilltableButton?.data?.details?.items,
      order_total: quickbilltableButton.data.details.order_total
        ? quickbilltableButton.data.details.order_total
        : 0,
      message: 'Quick bill placed',
      Payment_qr: code,
    });
    if (window.accessOfCustomerDisplay) {
      const state = {
        total: Number(quickbilltableButton.data.details.order_total).toFixed(
          window.ROUNDOFF_UPTO,
        ),
        items: quickbilltableButton?.data?.details?.items,
        billNumber: 0,
        qrCode: code,
      };

      window.sendStatetolocalcustomerdisplay(state);
    }
  }
}
window.settleQuickBillOnQrPayment = (order) => {
  if (
    quickbilltableButton &&
    quickbilltableButton.data &&
    order &&
    order.order_id &&
    order.order_id == orderid_for_quickBill
  ) {
    $('#quickbillsettleButton').click();
  }
};

window.updateQuickBillPaymentOnQrPayment = async (
  notificationData,
  tableIdToSettle,
) => {
  const { order } = notificationData;
  if (
    quickbilltableButton &&
    quickbilltableButton.data &&
    order &&
    order.order_id &&
    !order.table_id &&
    order.order_id == orderid_for_quickBill
  ) {
    const paymentDetails = {
      ...quickbilltableButton.data.details.paymentDetails,
    };

    Object.assign(paymentDetails, {
      payment_option: order.mode || 'UPI',
    });

    Object.assign(quickbilltableButton.data.details, { paymentDetails });

    if (
      order?.payment?.cust_name &&
      !quickbilltableButton.data.details.cust_name
    ) {
      Object.assign(quickbilltableButton.data.details, {
        cust_name: order.payment.cust_name,
      });
      $('#quickbillkotcustomernameField').val(order.payment.cust_name);
    }
  } else {
    initUpdateOrderDataAsPerPaymentInfo(notificationData.order);
    const payment_info = { ...notificationData, tableIdToSettle };
    ipcRenderer.send(PAYMENT_RECEIVED, payment_info);
  }
};

