/**
 * Resets the quick bill
 */
function resetQuickbill(clearKOT) {
  if (quickbilltableButton) {
    quickbilltableButton.data.details.items = [];
    quickbilltableButton.data.details.payment_mode = defaultPaymentoption;
    quickbilltableButton.data.details.paymentAdded = false;
    quickbilltableButton.data.details.charges = [];
    quickbilltableButton.data.details.paymentDetails = undefined;
    quickbilltableButton.data.details.bill_number = 0;
    quickbilltableButton.data.details.order_id = undefined;
    quickbilltableButton.data.details.discount = 0;
    quickbilltableButton.data.details.discount_type = undefined;
    quickbilltableButton.data.details.customer = undefined;
    quickbilltableButton.data.details.discounttoApply = 0;
    quickbilltableButton.data.details.couponDisountamt = 0;
    quickbilltableButton.data.details.couponDisounttype = 0;
    quickbilltableButton.data.details.coupon = undefined;
    quickbilltableButton.data.details.issectionwisebilling =
      ISBILLINGBYSECTION_ON;
    quickbilltableButton.data.details.discountHistory = undefined;
    quickbilltableButton.data.details.cust_paid_amount = undefined;
    quickbilltableButton.data.details.addasdueChecked = false;
    quickbilltableButton.data.details.due_payment = 0;
    quickbilltableButton.data.details.payment_modes = undefined;

    quickbilltableButton.data.details.preorderInfo = undefined;
    quickbilltableButton.data.details.is_pre_order = 0;
    quickbilltableButton.data.details.custom_bill_number = undefined;
    quickbilltableButton.data.details.extra_details = {};
    quickbilltableButton.data.details.order_total = 0;
    quickbilltableButton.data.details.totalCharges = 0;
    quickbilltableButton.data.details.rewardHistoryavailable = undefined;
    quickbilltableButton.data.details.item_level_total_charges = 0;
    quickbilltableButton.data.details.instructions = undefined;
    quickbilltableButton.data.details.waiterTipDetails = undefined;
    quickbilltableButton.data.details.fastSettletipAmt = undefined;
    quickbilltableButton.data.details.kot_numbers = undefined;
    quickbilltableButton.data.details.order_number = undefined;
    quickbilltableButton.data.details.order_note = undefined;
    if (quickbilltableButton.data.defaultcustomerQuickordertype)
      quickbilltableButton.data.defaultcustomerQuickordertype = undefined;

    if (quickbilltableButton.data.details.covers)
      delete quickbilltableButton.data.details.covers;
    if (quickbilltableButton.data.details.waiter) {
      delete quickbilltableButton.data.details.waiter;
      delete quickbilltableButton.data.details.waiter_id;
    }
    delete quickbilltableButton.data.details.defaultchargesRemoved;

    defaultcustomerQuickordertype = QUICKBILL_BILLING_FLAG;
    dynamiccustomerAddressforquickbill = '';
    newCustomerAddressForQuickBill = {};
  }

  $('#quickbillTable').find('tr:not(:first)').remove();
  $('#billGrandtotal').html('');
  $('#takeawaybillGrandtotal').html('');
  $('#deliverybillGrandtotal').html('');
  $('#quickbillkotnoteField').val('');
  $('#quickbillnoofpersonsField').val('');
  if (!clearKOT) {
    $('#quickbillkotcustomernameField').val('');
    $('#quickkotcustomeraddressField').val('');
    $('#quickbillkotcustomermobileField').val('');
    $('#quickkotcustomeraddressField').val('');
  }
  $('#quickbillkotdialcodeFieldid').val(window.dial_code);
  $('#customQuickBillTypeid').html('New Order');

  // $('#ebillBillcheckid').prop('checked', false);
  $('#quickbillGrandtotal').html('0');
  if (window.accessOfCustomerDisplay) {
    window.sendStatetolocalcustomerdisplay({});
  }
  $('#quickebillBillcheckid').prop('checked', defaultebillCheck);
  // $('#quickkotprintChecklabel').html('KOT');
}

