async function applyItemDiscount(data) {
  if (data) {
    let forQuickbill = false;
    let currenttablebuttoninstance = currenttableButton;
    let current_order_type;
    const activeTab = $('.mainsectionTabs li a.active').attr('id');
    if (activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
          current_order_type = 2;
          currenttablebuttoninstance = currenttableButton;
          break;
        case TAKEAWAY_TAB_ID:
          currenttablebuttoninstance = currenttableButton;
          current_order_type = 3;
          break;
        case DELIVERY_TAB_ID:
          currenttablebuttoninstance = currenttableButton;
          current_order_type = 4;
          break;
        case QUICK_TAB_ID:
          forQuickbill = true;
          currenttablebuttoninstance = quickbilltableButton;
          current_order_type = 1;
          break;
        default:
          break;
      }
    }
    let discountOrderTypes = [];
    if (data.order_type.length && data.order_type.includes(',')) {
      discountOrderTypes = data?.order_type?.split(',');
    } else {
      discountOrderTypes.push(String(data.order_type));
    }
    let checkOrderType = false;
    if (discountOrderTypes.includes(String(current_order_type))) {
      checkOrderType = true;
    }
    if (discountOrderTypes.includes('0')) {
      checkOrderType = true;
    }

    if (!checkOrderType) {
      return;
    }
    const response = await applyItemLevelDiscount(
      safeParse(data),
      currenttablebuttoninstance,
      forQuickbill,
    );
    if (response) {
      const items = response;
      const activeTab = $('.mainsectionTabs li a.active').attr('id');
      if (activeTab) {
        switch (activeTab) {
          case DINEIN_TAB_ID:
            try {
              $(`#${DINEIN_BILLTABLE}`).find('tr:not(:first)').remove();
            } catch (error) {
              return;
            }
            items.forEach((item) => {
              addBillRow(DINEIN_BILLTABLE, item);
            });
            break;
          case TAKEAWAY_TAB_ID:
            try {
              $(`#${TAKEAWAY_BILLTABLE}`).find('tr:not(:first)').remove();
            } catch (error) {
              return;
            }
            items.forEach((item) => {
              addBillRow(TAKEAWAY_BILLTABLE, item);
            });

            break;
          case DELIVERY_TAB_ID:
            try {
              $(`#${DELIVERY_BILLTABLE}`).find('tr:not(:first)').remove();
            } catch (error) {
              return;
            }
            items.forEach((item) => {
              addBillRow(DELIVERY_BILLTABLE, item);
            });

            break;
          case QUICK_TAB_ID:
            try {
              $(`#${QUICK_BILLTABLE}`).find('tr:not(:first)').remove();
            } catch (error) {
              return;
            }
            items.forEach((item) => {
              addKOTRow(QUICK_BILLTABLE, item);
            });
            break;
          default:
            break;
        }
      }
      $('#discountModalid').modal('hide');
      window.notifyUser.showMessage(
        'success',
        $.i18n.t('controller:orderWindowNotifications.Discountapplied'),
      );
    }
  }
}

async function checknApplydiscount() {
  // const optionsSelected = $('#discountsListCombo').find(':selected');s
  const optionsSelected = $(`#discountsListCombo li.activeElement`);

  if (optionsSelected != undefined && optionsSelected.length > 0) {
    const option = optionsSelected[0];
    if (option != undefined) {
      if (option.hasAttribute('is-customized')) {
        try {
          const data = option.getAttribute('data-discount');
          applyCustomizediscount(JSON.parse(data), false);
          setTimeout(() => {
            $('#discountreasonInputid').val('');
            $('#searchDiscountid').val('');
          }, 200);
        } catch (error) {}
      } else if (option.hasAttribute('is-itemdiscount')) {
        let forQuickbill = false;
        let currenttablebuttoninstance = currenttableButton;
        const activeTab = $('.mainsectionTabs li a.active').attr('id');
        if (activeTab) {
          switch (activeTab) {
            case DINEIN_TAB_ID:
            case TAKEAWAY_TAB_ID:
              currenttablebuttoninstance = currenttableButton;
              break;
            case DELIVERY_TAB_ID:
              currenttablebuttoninstance = currenttableButton;
              break;
            case QUICK_TAB_ID:
              forQuickbill = true;
              currenttablebuttoninstance = quickbilltableButton;
              break;
            default:
              break;
          }
        }
        if (
          currenttablebuttoninstance &&
          currenttablebuttoninstance.data &&
          currenttablebuttoninstance.data.details &&
          currenttablebuttoninstance.data.details.items
        ) {
          const items = currenttablebuttoninstance.data.details.items;

          const alreadyDiscounted = items.some(
            (item) =>
              Number(item.pricebeforeDiscount || 0) >
              Number(item.discounted_price || item.amount || 0),
          );

          if (alreadyDiscounted) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t(
                'controller:orderWindowNotifications.DiscountAlreadyApplied',
              ),
            );
            return;
          }
        }
        const data = option.getAttribute('data-discount');
        const response = await applyItemLevelDiscount(
          JSON.parse(data),
          currenttablebuttoninstance,
          forQuickbill,
        );
        if (response) {
          const items = response;
          const activeTab = $('.mainsectionTabs li a.active').attr('id');
          if (activeTab) {
            switch (activeTab) {
              case DINEIN_TAB_ID:
              case TAKEAWAY_TAB_ID:
              case DELIVERY_TAB_ID:
                $(`#table_${currenttablebuttoninstance.data.id}`).click();
                break;
              //   try {
              //     $(`#${DINEIN_BILLTABLE}`).find('tr:not(:first)').remove();
              //   } catch (error) {
              //     return;
              //   }
              //   items.forEach((item) => {
              //     addBillRow(DINEIN_BILLTABLE, item);
              //   });
              //   break;
              // case TAKEAWAY_TAB_ID:
              //   try {
              //     $(`#${TAKEAWAY_BILLTABLE}`).find('tr:not(:first)').remove();
              //   } catch (error) {
              //     return;
              //   }
              //   items.forEach((item) => {
              //     addBillRow(TAKEAWAY_BILLTABLE, item);
              //   });

              //   break;
              // case DELIVERY_TAB_ID:
              //   try {
              //     $(`#${DELIVERY_BILLTABLE}`).find('tr:not(:first)').remove();
              //   } catch (error) {
              //     return;
              //   }
              //   items.forEach((item) => {
              //     addBillRow(DELIVERY_BILLTABLE, item);
              //   });

              //   break;
              case QUICK_TAB_ID:
                try {
                  $(`#${QUICK_BILLTABLE}`).find('tr:not(:first)').remove();
                } catch (error) {
                  return;
                }
                items.forEach((item) => {
                  addKOTRow(QUICK_BILLTABLE, item);
                });
                break;
              default:
                break;
            }
          }
          $('#discountModalid').modal('hide');
          window.notifyUser.showMessage(
            'success',
            $.i18n.t('controller:orderWindowNotifications.Discountapplied'),
          );
        }
      } else if (option.hasAttribute('rate')) {
        let extra_details = option.getAttribute('extra_details');
        if (extra_details) {
          extra_details = JSON.parse(extra_details);
          if (extra_details.valid_on_day) {
            const currentDate = moment();
            let currentDay = currentDate.day();
            currentDay += 1;
            const valid_days = extra_details.valid_on_day.split(',');
            if (
              valid_days &&
              valid_days.length &&
              !valid_days.includes(String(currentDay)) &&
              valid_days[0] !== '0'
            ) {
              const validdays = _.at(DISCOUNT_DAYS, valid_days);
              const discount_valid_days = validdays.join(', ');
              window.notifyUser.showMessage(
                'error',
                ` ${$.i18n.t(
                  'controller:orderWindowNotifications.Discountapplicableon',
                )} ${discount_valid_days}`,
              );
              return;
            }
          }

          if (extra_details.from_time && extra_details.to_time) {
            const isBetween = istimebetweenTwotime(
              extra_details.from_time,
              extra_details.to_time,
            );
            if (!isBetween) {
              window.notifyUser.showMessage(
                'error',
                `${$.i18n.t(
                  'controller:orderController.discountIsValid.discountIsValidBetween',
                )} ${extra_details.from_time} ${$.i18n.t(
                  'controller:orderController.discountIsValid.to',
                )} ${extra_details.to_time}`,
                0,
              );
              return;
            }
          }
        }

        let reason = $('#discountreasonInputid').val();
        reason = reason.trim();
        if (makediscountreasoncompulsory && !reason) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t('controller:orderWindowNotifications.Pleaseaddreason'),
          );
          return;
        }
        if (reason) {
          if (reason.length > 100) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t(
                'controller:orderWindowNotifications.Reasonlengthshouldbelessthanhundredcharacters',
              ),
            );
            return;
          }

          if (window.specialCharRegex.test(reason)) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t(
                'controller:orderWindowNotifications.Specialcharactersarenotallowedinaddress',
              ),
            );
            return;
          }
        }
        if (reason) {
          billstatusReason = addOrderlevelinstructions(
            billstatusReason,
            reason,
            'Discount',
          );
        }
        const discount_rate = option.getAttribute('rate');
        if (Number(discount_rate) < 0) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Discountshouldbegreaterthanzero',
            ),
          );
          return;
        }
        const discount = {
          id: option.getAttribute('id'),
          is_modifiable: option.getAttribute('is_modifiable'),
          discount_type: option.getAttribute('discount_type'),
          rate: option.getAttribute('rate'),
          product_groups: option.getAttribute('product_groups'),
          title: $(option).html(),
          discount_name: $(option).html(),
          instructions: reason ? `Discount:: ${reason}` : '',
        };
        updateDiscount(discount);
        $('#discountreasonInputid').val('');
        $('#searchDiscountid').val('');
      } else {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t('controller:orderController.pleaseSelectDiscount'),
        );
      }
    }
  } else {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectDiscount'),
    );
  }
}
function checkifNumber(valuetoTest) {
  return /^\d+$/.test(valuetoTest);
}
const findIndexById = (arr, id) => arr.findIndex((obj) => obj.id === id);
function isOrderTotalBetweenDiscountlimit(value, lowerBound, upperBound) {
  return value >= lowerBound && value <= upperBound;
}
/**
 * Check and apply the customized discount to the
 * current window.
 * @param {Discount info} data
 */
async function applyCustomizediscount(customizedDiscountList, checkSilently) {
  const activeTab = $('.mainsectionTabs li a.active').attr('id');

  let order_total_amount;
  if (activeTab) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
      case TAKEAWAY_TAB_ID:
      case DELIVERY_TAB_ID:
        order_total_amount = currenttableButton.data.details.order_total;
        break;

      case QUICK_TAB_ID:
        order_total_amount = quickbilltableButton.data.details.order_total;
        break;
    }
  }

  if (!Array.isArray(customizedDiscountList)) {
    customizedDiscountList = [customizedDiscountList];
  }

  const customizeDiscounts = [...customizedDiscountList];
  if (customizedDiscountList && customizedDiscountList.length) {
    // get day wise discount
    customizedDiscountList.forEach((discount, i) => {
      if (discount.discount_day !== 0) {
        const currentDate = moment();
        let currentDay = currentDate.day();
        currentDay += 1;
        const valid_day = discount.discount_day;
        if (currentDay != valid_day) {
          // customizedDiscount = discount;
          const index = findIndexById(customizeDiscounts, discount.id);
          customizeDiscounts.splice(index, 1);
        }
      }
    });
  }
  let customizedDiscount = customizeDiscounts[0];

  customizeDiscounts.forEach((discount) => {
    if (discount.amount_lower_limit && discount.amount_upper_limit) {
      const isBetweenLimit = isOrderTotalBetweenDiscountlimit(
        order_total_amount,
        discount.amount_lower_limit,
        discount.amount_upper_limit,
      );
      if (isBetweenLimit) {
        customizedDiscount = discount;
      }
    }
  });
  // let customizedDiscount = customizedDiscountList[0];

  let discountAmount = 0;
  let customiseddiscountType = customizedDiscount.type;
  if (customizedDiscount && customizedDiscount.amount) {
    discountAmount = customizedDiscount.amount;
    // Check if disount has specific active period
    if (customizedDiscount.from_date_time && customizedDiscount.to_date_time) {
      try {
        const applicabletoday = moment().isBetween(
          customizedDiscount.from_date_time,
          customizedDiscount.to_date_time,
        );
        const isSameAsStartDate = moment().isSame(
          customizedDiscount.from_date_time,
          'day',
        );
        const isSameAsEndDate = moment().isSame(
          customizedDiscount.to_date_time,
          'day',
        );
        if (!applicabletoday && !isSameAsStartDate && !isSameAsEndDate) {
          if (!checkSilently)
            window.notifyUser.showMessage(
              'error',
              `${$.i18n.t(
                'controller:orderController.discountIsValid.discountIsValidBetween',
              )} ${customizedDiscount.from_date_time} ${$.i18n.t(
                'controller:orderController.discountIsValid.to',
              )} ${customizedDiscount.to_date_time}`,
              0,
            );
          return;
        }

        if (customizedDiscount.discount_day) {
          const currentDate = moment();
          let currentDay = currentDate.day();
          currentDay += 1;
          const valid_day = customizedDiscount.discount_day;
          if (currentDay !== valid_day) {
            window.notifyUser.showMessage(
              'error',
              `Discount applicable on ${
                DISCOUNT_DAYS[customizedDiscount.discount_day]
              }`,
            );
            return;
          }
        }

        if (applicabletoday) {
          // extract time from start date and end date
          const dateObject = new Date(customizedDiscount.from_date_time);

          const startHours = dateObject.getUTCHours();
          const startMinutes = dateObject.getUTCMinutes();

          const startTime = `${startHours}:${startMinutes}`;

          const endDateObject = new Date(customizedDiscount.to_date_time);

          const endHours = endDateObject.getUTCHours();
          const endMinutes = endDateObject.getUTCMinutes();

          const endTime = `${endHours}:${endMinutes}`;

          const isBetween = istimebetweenTwotime(startTime, endTime);
          if (!isBetween) {
            if (!checkSilently) {
              window.notifyUser.showMessage(
                'error',
                `Discount is applicable from ${startHours}:${startMinutes} to ${endHours}:${endMinutes}`,
              );
              return;
            }
            return;
          }
        }
      } catch (error) {
        console.error(error);
      }
    }

    let billTotal = 0;
    let billsubTotal = 0;
    let currenttable;
    // let activeTab = $('.mainsectionTabs li a.active').attr('id');

    const discountorderTypes = String(customizedDiscount.order_type).split(',');
    if (activeTab) {
      // order_type 0=All ,1=Quick Bill, 2=Dine In, 3= TA
      switch (activeTab) {
        case DINEIN_TAB_ID:
          {
            currenttable = currenttableButton;
            if (
              !discountorderTypes.includes(CUSTOMISED_DISCOUNT_ORDERTYPE.ALL) &&
              !discountorderTypes.includes(
                CUSTOMISED_DISCOUNT_ORDERTYPE.DINE_IN,
              )
            ) {
              if (!checkSilently)
                window.notifyUser.showMessage(
                  'error',
                  $.i18n.t(
                    'controller:orderController.notApplicableToThisSection',
                  ),
                );
              return;
            }
            resetCurrentdiscount(currenttable);
            await precalculateDetailsCheck(currenttable);

            billTotal = currenttable.data.details.order_total;
            if (!billTotal) {
              billTotal = $('#billGrandtotal').text();
            }
            billsubTotal = currenttable.data.details.order_subtotal;
          }
          break;
        case TAKEAWAY_TAB_ID:
          // case TAKEAWAY_TAB_ID:
          {
            if (
              !discountorderTypes.includes(CUSTOMISED_DISCOUNT_ORDERTYPE.ALL) &&
              !discountorderTypes.includes(
                CUSTOMISED_DISCOUNT_ORDERTYPE.TAKEAWAY,
              )
            ) {
              if (!checkSilently)
                window.notifyUser.showMessage(
                  'error',
                  $.i18n.t(
                    'controller:orderController.notApplicableToThisSection',
                  ),
                );
              return;
            }

            currenttable = currenttableButton;
            resetCurrentdiscount(currenttable);
            await precalculateDetailsCheck(currenttable);

            billTotal = currenttable.data.details.order_total;
            if (!billTotal) {
              billTotal = $('#takeawaybillGrandtotal').text();
            }
            billsubTotal = currenttable.data.details.order_subtotal;
          }
          break;

        case DELIVERY_TAB_ID:
          {
            // HD Type
            if (
              !discountorderTypes.includes(CUSTOMISED_DISCOUNT_ORDERTYPE.ALL) &&
              !discountorderTypes.includes(
                CUSTOMISED_DISCOUNT_ORDERTYPE.HOME_DELIVERY,
              )
            ) {
              if (!checkSilently)
                window.notifyUser.showMessage(
                  'error',
                  $.i18n.t(
                    'controller:orderController.notApplicableToThisSection',
                  ),
                );
              return;
            }

            currenttable = currenttableButton;
            resetCurrentdiscount(currenttable);
            await precalculateDetailsCheck(currenttable);

            billTotal = currenttable.data.details.order_total;
            if (!billTotal) {
              billTotal = $('#deliverybillGrandtotal').text();
            }
            billsubTotal = currenttable.data.details.order_subtotal;
          }
          break;
        case QUICK_TAB_ID:
          {
            currenttable = quickbilltableButton;
            if (
              !discountorderTypes.includes(CUSTOMISED_DISCOUNT_ORDERTYPE.ALL) &&
              !discountorderTypes.includes(
                CUSTOMISED_DISCOUNT_ORDERTYPE.QUICK_BILL,
              )
            ) {
              if (!checkSilently)
                window.notifyUser.showMessage(
                  'error',
                  $.i18n.t(
                    'controller:orderController.notApplicableToThisSection',
                  ),
                );
              return;
            }
            resetCurrentdiscount(currenttable);
            await precalculateDetailsCheck(currenttable);
            billTotal = currenttable.data.details.order_total;
            if (!billTotal) billTotal = $('#quickbillGrandtotal').text();
            billsubTotal = currenttable.data.details.order_subtotal;
          }
          break;
        default:
          break;
      }
      if (currenttable == undefined) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            $.i18n.t('controller:orderController.pleaseSelectTheTable'),
          );
        return;
      }

      try {
        billTotal = Number(billTotal);
      } catch (error) {
        billTotal = 0;
      }
      if (billTotal == 0) {
        return;
      }
      if (billsubTotal && billTotal !== billsubTotal) {
        billTotal = billsubTotal;
      }
      if (customizedDiscount.discount_day != 0) {
        // 7 For All day'ck
        let daytoCheck = customizedDiscount.discount_day;
        const currentDate = moment();
        let currentDay = currentDate.day();
        currentDay++;
        daytoCheck -= 1;
        if (daytoCheck == currentDay) {
          if (!checkSilently)
            window.notifyUser.showMessage(
              'error',
              `${$.i18n.t(
                'controller:orderController.discountIsOnlyApplicableOn',
              )} ${currentDate.day(daytoCheck).format('dddd')}`,
            );
          return;
        }
      }

      if (
        customizedDiscount.amount_lower_limit == 0 &&
        customizedDiscount.amount_upper_limit == 0 &&
        customizedDiscount.applicable_on_amount > billTotal
      ) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            `${$.i18n.t(
              'controller:orderController.minimumTotal.minimumTotalIs',
            )} ${window.currency} ${
              customizedDiscount.applicable_on_amount
            } ${$.i18n.t(
              'controller:orderController.minimumTotal.toApplyThisDiscount',
            )}`,
          );
        return;
      }
      // Check if their is a lower limit for bill amount
      if (
        customizedDiscount.amount_lower_limit &&
        customizedDiscount.amount_lower_limit > billTotal
      ) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            `${$.i18n.t(
              'controller:orderController.minimumTotal.minimumTotalIs',
            )} ${window.currency} ${
              customizedDiscount.amount_lower_limit
            } ${$.i18n.t(
              'controller:orderController.minimumTotal.toApplyThisDiscount',
            )}`,
          );
        return;
      }
      // Check if their is a max limit for bill amount
      if (
        customizedDiscount.amount_upper_limit &&
        customizedDiscount.amount_upper_limit < billTotal
      ) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            `${$.i18n.t(
              'controller:orderController.maximumTotal.minimumTotalIs',
            )} ${window.currency} ${
              customizedDiscount.amount_upper_limit
            } ${$.i18n.t(
              'controller:orderController.maximumTotal.toApplyThisDiscount',
            )}`,
          );
        return;
      }

      // Verify if discount amount is valid 0 Fixed 1 Percent
      if (customiseddiscountType == 2 && discountAmount >= billTotal) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderController.discountAmountCannotBeGreaterThanBillAmount',
            ),
          );
        return;
      }
      if (customiseddiscountType == 1 && discountAmount > 100) {
        if (!checkSilently)
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderController.discountAmountCannotBeGreaterThanBillAmount',
            ),
          );
        return;
      }
      // Check if disount is after a amount
      if (
        customizedDiscount.discount_after_amount &&
        customizedDiscount.discount_after_amount > 0 &&
        billTotal > customizedDiscount.discount_after_amount
      ) {
        billTotal -= customizedDiscount.discount_after_amount;
      }

      // Check if discount value is in percent
      // If yes then convert it
      if (customiseddiscountType == 1) {
        discountAmount = (billTotal / 100) * customizedDiscount.amount;
        // discountAmount = Number(((billTotal * customizedDiscount.amount) / 100).toFixed(ROUNDOFF_UPTO));
      }
      // Check if the maximum discount limit is given
      // If yes then apply only maximum amount
      if (
        customizedDiscount.max_applicable_discount &&
        discountAmount > customizedDiscount.max_applicable_discount
      ) {
        discountAmount = customizedDiscount.max_applicable_discount;
        customiseddiscountType = '0';
        customizedDiscount.amount = discountAmount;
        if (!checkSilently)
          window.notifyUser.showMessage(
            'success',
            `${$.i18n.t(
              'controller:orderController.maximumApplicableDiscountAmountIs',
            )} ${window.currency} ${
              customizedDiscount.max_applicable_discount
            }`,
            0,
          );
      }
      applyDiscounttotable(currenttable, {
        rate: customizedDiscount.amount,
        discount_type: customiseddiscountType == 1 ? '1' : '0',
        discount_name: customizedDiscount.title || '',
        discount_title: customizedDiscount.title || '',
        product_groups: customizedDiscount.product_groups,
      });

      const reason = $('#discountreasonInputid').val();
      if (reason) {
        if (reason.length > 100) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Reasonlengthshouldbelessthanhundredcharacters',
            ),
          );
          return;
        }

        if (window.allspecialCharRegex.test(reason)) {
          window.notifyUser.showMessage(
            'error',
            $.i18n.t(
              'controller:orderWindowNotifications.Somespecialcharactersarenotallowed',
            ),
          );
          return;
        }
      }
      if (reason) {
        billstatusReason = addOrderlevelinstructions(
          billstatusReason,
          reason,
          'Discount',
        );
      }

      if (ISBILLINGBYSECTION_ON && !customizedDiscount.product_groups) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t(
            'controller:orderController.discountDoesntHaveAnyProductGroups',
          ),
        );
        return;
      }
      if (
        ISBILLINGBYSECTION_ON &&
        customizedDiscount.product_groups &&
        currenttable.data.details.items
      ) {
        let applyDiscount = false;
        const productGroups = customizedDiscount.product_groups.split(',');
        currenttable.data.details.items.forEach((item) => {
          if (productGroups.includes(String(item.product_group_id))) {
            applyDiscount = true;
          }
        });
        if (!applyDiscount) {
          return;
        }
      }
      await precalculateDetailsCheck(currenttable);
      switch (activeTab) {
        case DINEIN_TAB_ID:
        case TAKEAWAY_TAB_ID:
        case DELIVERY_TAB_ID:
          {
            const table_id = currenttable.id.replace('table_', '');
            const paymentData = {
              table_id,
              data: {
                // discount_type: '0',
                // rate: discountAmount,
                product_groups: customizedDiscount.product_groups
                  ? customizedDiscount.product_groups
                  : undefined,
                discount_type: customiseddiscountType === 1 ? '1' : '0',
                rate: customizedDiscount.amount,
                title: customizedDiscount.title || '',
                instructions: reason ? `Discount:: ${reason}` : '',
              },
              order_id: currenttable.data.details.bill_number,
            };

            sendDiscountupdate(currenttable, activeTab, paymentData);
          }
          break;
        case QUICK_TAB_ID:
          {
            applyDiscounttotable(currenttable, {
              rate: customizedDiscount.amount,
              discount_type: customiseddiscountType == 1 ? '1' : '0',
              discount_name: customizedDiscount.title || '',
              title: customizedDiscount.title || '',
              product_groups: customizedDiscount.product_groups,
              instructions: reason ? `Discount:: ${reason}` : '',
            });
            precalculateDetailsCheck(quickbilltableButton);
            $('#discountModalid').modal('hide');
            window.notifyUser.showMessage(
              'success',
              $.i18n.t('controller:orderWindowNotifications.Discountapplied'),
            );
          }
          break;
        default:
          break;
      }
    }
  }
}

function resetCurrentdiscount(tableInstance) {
  if (tableInstance) {
    tableInstance.data.details.discount = 0;
    tableInstance.data.details.discount_type = '0';
    tableInstance.data.details.discounted_product_groups = undefined;
    tableInstance.data.details.discount_title = '';
    tableInstance.data.details.discountHistory = undefined;
  }
}

function applyDiscounttotable(tableInstance, discountData) {
  if (tableInstance && discountData) {
    tableInstance.data.details.discount = discountData.rate;
    tableInstance.data.details.discount_type = discountData.discount_type;
    tableInstance.data.details.discounted_product_groups =
      discountData.product_groups;
    tableInstance.data.details.discount_title =
      discountData.discount_name || '';
    tableInstance.data.details.instructions = discountData.instructions || '';
  }
}

/**
 *  Updates the discount for the table
 */
async function updateDiscount(discountData) {
  if (discountData != undefined) {
    // let discount_rate = discountData.rate;
    const newrawDiscountrate = $('#discountInputid').val();
    if (newrawDiscountrate) {
      if (Number(newrawDiscountrate) < 0) {
        window.notifyUser.showMessage(
          'error',
          $.i18n.t(
            'controller:orderWindowNotifications.Discountshouldbegreaterthanzero',
          ),
        );
        return;
      }
      const newrawDiscount = toNumber(newrawDiscountrate);
      if (isNumber(newrawDiscount)) {
        discountData.rate = newrawDiscount;
        const selectList = $('#discountsListCombo');
        selectList.find('option').not(':first').remove();
      }
    }
    const activeTab = $('.mainsectionTabs li a.active').attr('id');
    if (activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
        case TAKEAWAY_TAB_ID:
        case DELIVERY_TAB_ID:
          {
            if (currenttableButton == undefined) {
              return;
            }
            resetCurrentdiscount(currenttableButton);
            await precalculateDetailsCheck(currenttableButton);

            let billTotal = currenttableButton.data.details.order_total;
            if (!billTotal) {
              switch (activeTab) {
                case DINEIN_TAB_ID:
                  billTotal = $('#billGrandtotal').text();
                  break;

                case TAKEAWAY_TAB_ID:
                  billTotal = $('#takeawaybillGrandtotal').text();
                  break;

                case DELIVERY_TAB_ID:
                  billTotal = $('#deliverybillGrandtotal').text();
                  break;

                default:
                  break;
              }
            }

            const billsubTotal = currenttableButton.data.details.order_subtotal;
            if (billsubTotal !== 0 && billsubTotal !== billTotal) {
              billTotal = billsubTotal;
            }

            if (
              Number(discountData.discount_type) == 2 &&
              Number(discountData.rate) >= Number(billTotal)
            ) {
              window.notifyUser.showMessage(
                'error',
                $.i18n.t(
                  'controller:orderController.discountAmountCannotBeGreaterThanBillAmount',
                ),
              );
              return;
            }
            if (
              Number(discountData.discount_type) == 1 &&
              Number(discountData.rate) > 100
            ) {
              window.notifyUser.showMessage(
                'error',
                'Discount rate cannot be greater than 100',
              );
              return;
            }

            // if (ISBILLINGBYSECTION_ON && !discountData.product_groups) {
            //   window.notifyUser.showMessage(
            //     'error',
            //     $.i18n.t(
            //       'controller:orderController.discountDoesntHaveAnyProductGroups',
            //     ),
            //     300,
            //   );
            //   return;
            // }

            if (ISBILLINGBYSECTION_ON && discountData.product_groups) {
              const itemProductGroups = _.map(
                currenttableButton.data.details.items,
                'product_group_id',
              );
              let discountProductGroups =
                discountData.product_groups.split(',');
              discountProductGroups = discountProductGroups.map((num) =>
                Number(num),
              );

              const found = itemProductGroups.some((r) =>
                discountProductGroups.includes(r),
              );

              if (!found) {
                window.notifyUser.showMessage(
                  'error',
                  $.i18n.t(
                    'controller:orderWindowNotifications.DiscountisnotapplicabletoaddeditemsProductgroup',
                  ),
                  300,
                );
                return;
              }
            }

            const table_id = currenttableButton.id.replace('table_', '');
            const paymentData = {
              table_id,
              data: discountData,
              order_id: currenttableButton.data.details.bill_number,
            };

            applyDiscounttotable(currenttableButton, discountData);
            currenttableButton.data.details.due_payment = 0;

            await precalculateDetailsCheck(currenttableButton);
            const { extra_details } = currenttableButton.data.details;
            if (extra_details && extra_details.rewardDiscount) {
              extra_details.rewardDiscount = undefined;
              currenttableButton.data.details.extra_details = extra_details;
              // Send delete reward history

              initSendRewardHistory({
                order_id: paymentData.order_id,
                status: 'deleted',
              });
              sendRewardhistory({
                reward: '',
                order_id: currenttableButton.data.details.bill_number,
                phone: currenttableButton.data.details?.customer?.phone,
                customer_name: currenttableButton.data.details?.customer?.name,
                isQuickbill: 0,
                action: 'delete',
              });
            }
            sendDiscountupdate(currenttableButton, activeTab, paymentData);
          }
          break;
        case QUICK_TAB_ID:
          quickbilltableButton.data.details.discount = 0;
          quickbilltableButton.data.details.discount_type = '0';
          await precalculateDetailsCheck(quickbilltableButton);

          let billTotal = quickbilltableButton.data.details.order_total;
          if (!billTotal) billTotal = $('#quickbillGrandtotal').text();

          const billsubTotal = quickbilltableButton.data.details.order_subtotal;
          if (billsubTotal !== 0 && billsubTotal !== billTotal) {
            billTotal = billsubTotal;
          }
          if (
            Number(discountData.discount_type) == 2 &&
            Number(discountData.rate) >= Number(billTotal)
          ) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t(
                'controller:orderController.discountAmountCannotBeGreaterThanBillAmount',
              ),
            );
            return;
          }
          if (
            Number(discountData.discount_type) == 1 &&
            Number(discountData.rate) > 100
          ) {
            window.notifyUser.showMessage(
              'error',
              'Discount rate cannot be greater than 100',
            );
            return;
          }
          applyDiscounttotable(quickbilltableButton, discountData);

          const { extra_details } = quickbilltableButton.data.details;
          if (extra_details && extra_details.rewardDiscount) {
            extra_details.rewardDiscount = undefined;
            quickbilltableButton.data.details.extra_details = extra_details;
          }
          await precalculateDetailsCheck(quickbilltableButton);
          if (defaultPaymentoption !== 'None' && defaultPaymentoption !== '0') {
            const paymentDetails = {
              isSplitpayment: false,
              payment_option: defaultPaymentoption,
              amount: quickbilltableButton.data.details.order_total,
            };
            Object.assign(quickbilltableButton.data.details, {
              paymentDetails,
              payment_mode: defaultPaymentoption,
            });
            quickbilltableButton.data.details.paymentDetails = paymentDetails;
          }
          window.notifyUser.showMessage(
            'success',
            $.i18n.t('controller:orderWindowNotifications.Discountapplied'),
          );
          $('#discountModalid').modal('hide');
          break;

        default:
          break;
      }
    }
  }
}
$(document).on('keydown', '#discountInputid', function (e) {
  if (e.key === 'e' || e.key === 'E' || e.key === '+' || e.key === '-') {
    e.preventDefault();
  }
});

// $(document).on('input', '#discountInputid', function () {
//   this.value = this.value
//     .replace(/[^0-9.]/g, '') // allow numbers and dot
//     .replace(/(\..*?)\..*/g, '$1'); // allow only one dot
//   console.log('this value', this.value);
// });
async function sendDiscountupdate(selectedTable, activeTab, requestData) {
  const kotUpdatedata = {};
  // Check if discount is provided
  let hasdiscountedProductgrps = false;
  if (
    requestData.data.discount_type != undefined &&
    requestData.data.rate != undefined
  ) {
    kotUpdatedata.discount_id = requestData.data.id;
    kotUpdatedata.discount_type = requestData.data.discount_type;
    kotUpdatedata.discount_rate = requestData.data.rate;
    kotUpdatedata.field1 = billstatusReason || '';
    // if (requestData.data.product_groups) {
    Object.assign(kotUpdatedata, {
      discounted_product_groups: requestData.data.product_groups,
    });
    hasdiscountedProductgrps = true;
    // }
    kotUpdatedata.discount_rate = requestData.data.rate;
    kotUpdatedata.discount_title = requestData.data.title;
  }
  let couponDisountavailable = false;
  // Check for coupon discount
  if (
    requestData.data.couponDisountamt != undefined &&
    requestData.data.couponDisounttype != undefined
  ) {
    kotUpdatedata.couponDisount = requestData.data.couponDisountamt;
    kotUpdatedata.couponDisounttype = requestData.data.couponDisounttype;
    kotUpdatedata.coupon = requestData.data.coupon;
    couponDisountavailable = true;
    // if (requestData.data.product_groups) {
    Object.assign(kotUpdatedata, {
      discounted_product_groups: requestData.data.product_groups,
    });
    hasdiscountedProductgrps = true;
    // }
  }
  requestData.data = kotUpdatedata;
  requestData.couponDisountavailable = couponDisountavailable;

  if (selectedTable == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }
  let billTotal = selectedTable.data.details.order_total;
  if (!billTotal) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
        billTotal = $('#billGrandtotal').text();
        break;

      case TAKEAWAY_TAB_ID:
        billTotal = $('#takeawaybillGrandtotal').text();
        break;

      case DELIVERY_TAB_ID:
        billTotal = $('#deliverybillGrandtotal').text();
        break;

      default:
        break;
    }
  }
  const billupdateData = {
    order_total: billTotal,
    order_level_total_charges:
      selectedTable.data.details.order_level_total_charges,
    charges_level_total_tax: selectedTable.data.details.charges_level_total_tax,
    // discount:
    //   Number(selectedTable.data.details.discounttoApply) +
    //   Number(selectedTable.data.details.coupondiscounttoApply),
    discount: Number(selectedTable.data.details.discounttoApply),
    order_level_total_taxes: selectedTable.data.details.taxtoApply,
    instructions: billstatusReason || '',
    extra_details: selectedTable.data.details.extra_details,
    // cust_paid_amount:
    //   selectedTable.data.details.cust_paid_amount !== undefined &&
    //   selectedTable.data.details.cust_paid_amount,
    // : billTotal,
    due_payment: 0,
    // cust_paid_amount: billTotal,
  };

  if (hasdiscountedProductgrps) {
    Object.assign(billupdateData, {
      discounted_product_groups: kotUpdatedata.discounted_product_groups,
    });
  }

  if (kotUpdatedata) {
    Object.assign(billupdateData, {
      discount_title: kotUpdatedata.discount_title,
    });
  }
  if (couponDisountavailable) {
    billupdateData.couponDisount = kotUpdatedata.couponDisount;
    billupdateData.couponDisounttype = kotUpdatedata.couponDisounttype;
    billupdateData.coupon = kotUpdatedata.coupon;
    billupdateData.couponDisounttotal = Number(
      selectedTable.data.details.coupondiscounttoApply,
    );
  }
  requestData.billupdateData = billupdateData;
  if (defaultPaymentoption !== 'None' && defaultPaymentoption !== '0') {
    const paymentDetails = {
      order_id: selectedTable.data.details.bill_number,
      payment_option: defaultPaymentoption,
      amount: billTotal,
    };
    requestData.paymentDetails = paymentDetails;
    selectedTable.data.details.payment_mode = paymentDetails.payment_option;
  }
  selectedTable.data.details.paymentAdded = false;
  // selectedTable.data.details.cust_paid_amount = billTotal;
  requestData.tempCharges = selectedTable.data.details.charges;
  requestData.allowdiscountafterPrint = allowdiscountafterPrint;
  showLoader({
    title: 'Updating discount',
    text: $.i18n.t('controller:orderController.pleaseWait'),
  });
  initUpdateDiscount(requestData);
}

/**
 *
 * @param {tab to set as active} tab
 */
function activateTab(tab) {
  // show change order type icon on kot window only not on billing window
  if (
    [DINE_BILL_TABID, TAKEAWAY_BILL_TABID, DELIVERY_BILL_TABID].includes(tab)
  ) {
    $('#changeordertypeid').hide();
    $('#takeawaychangeordertypeid').hide();
    $('#deliverychangeordertypeid').hide();

    // show change order type after save kot
    if (window.changeOrderTypeEnabled) {
      $('#changeordertypeAfterSaveKotid').show();
      $('#takeawaychangeordertypeAfterSaveKotid').show();
      $('#deliverychangeordertypeAfterSaveKotid').show();
    }
  } else if (window.changeOrderTypeEnabled) {
    $('#changeordertypeid').show();
    $('#takeawaychangeordertypeid').show();
    $('#deliverychangeordertypeid').show();

    // hide change order type after save kot
    $('#changeordertypeAfterSaveKotid').hide();
    $('#takeawaychangeordertypeAfterSaveKotid').hide();
    $('#deliverychangeordertypeAfterSaveKotid').hide();
  }
  if (tab) {
    $(`.nav-tabs a[href="#${tab}"]`).tab('show');
  }
}

/**
 * set the current table name
 * @param {Sets the current table name} name
 */
function setCurrentTable(name) {
  $('#currentTablename').html(name);
  $('#dineinbillcurrentTablename').html(name);
}

/**
 * Add new customer
 */
window.sendCustomerandaddtoListenerfromremote = async function (
  customer,
  isSilent,
) {
  if (customer && window.storeDetails && window.storeDetails.store_id) {
    addnewCustomer(customer);
    if (customer.id) {
      window.notifyUser.showMessage('success', 'Customer updated');
      return;
    }
    if (!isSilent)
      window.notifyUser.showMessage(
        'success',
        $.i18n.t('controller:orderController.customerAdded'),
      );
  }
};

/**
 * Adds new customer
 * @param {Customer to add} customer
 */
async function addnewCustomer(customer) {
  customer.createWallet = true;
  if (
    currenttableButton &&
    currenttableButton.data.details &&
    currenttableButton.data.details.customer &&
    currenttableButton.data.details.customer.phone === customer.phone
  ) {
    // if name is updated then update name on table
    if (currenttableButton.data.details.customer.name !== customer.name) {
      customer.updateNameOnTable = true;
      customer.table_id = currenttableButton.data.id;
      $(`#${currenttableButton.id}`)
        .find('#tablecustomernameLabelid')
        .html(customer.name);

      if ($('#modal_customernameid').is(':visible')) {
        $('#modal_customernameid').val(customer.name);
      }
    }
    currenttableButton.data.details.customer.name = customer.name;
  }
  initAddCustomer(customer);
}

ipcRenderer.on(ADD_CUSTOMER_REPLY, async (event, reply) => {
  try {
    reply = JSON.parse(reply);
    if (reply && reply.customer) {
      const index = _.findIndex(customersList, { phone: reply.customer.phone });
      if (index > 0) {
        customersList.splice(index, 1, reply.customer);
      } else {
        customersList.push(reply.customer);
      }
      if (window.customerscriptLoaded) remoterefreshCustomerstable();

      if (window.customermgmtscriptLoaded) refreshCustomermgmttable();
    }
  } catch (error) {
    console.error(error);
  }
});

function showChangetable() {
  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }

  if (
    currenttableButton.data.details.bill_number != undefined &&
    currenttableButton.data.details.bill_number != 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.cannotShiftSavedBill'),
    );
    return true;
  }
  let isKOTTableempty;
  let isBillTableempty;
  const activeTab = $('.mainsectionTabs li a.active').attr('id');
  if (activeTab) {
    switch (activeTab) {
      case DINEIN_TAB_ID:
        {
          isKOTTableempty = $('#kotTable tbody tr').length == 0;
          isBillTableempty = $('#billTable tbody tr').length == 0;
          if (isKOTTableempty && isBillTableempty) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.thereAreNoItemsToShift'),
            );
            return true;
          }
        }
        break;
      case TAKEAWAY_TAB_ID:
        {
          const istaKOTTableempty = $('#takeawaykotTable tbody tr').length == 0;
          const istaBillTableempty = $('#takebillTable tbody tr').length == 0;
          if (istaKOTTableempty && istaBillTableempty) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.thereAreNoItemsToShift'),
            );
            return true;
          }
        }
        break;
      default:
        break;
    }
  }

  const popup = Swal.mixin({});
  const list = $('<datalist></datalist>').attr('id', 'tableSuggestionslist');
  tableName_suggestions.forEach((element) => {
    list.append($('<option>').text(element));
  });

  popup.fire({
    title: $.i18n.t('controller:orderController.enterTableName'),
    text: $.i18n.t(
      'controller:orderController.thisWillShiftTheCurrentKOTAndBillItemToDestiantionTable',
    ),
    // input: 'text',
    html: `<input type="text" placeholder=${$.i18n.t(
      'controller:orderController.enterTableName',
    )} class="changetableInputfield w-75">`,
    confirmButtonText: $.i18n.t('controller:orderController.changeTable.OK'),
    cancelButtonText: $.i18n.t('controller:orderController.changeTable.Cancel'),
    didOpen: async () => {
      await addSuggestionstoelement(
        '#swal2-html-container input.changetableInputfield',
        tableName_suggestions,
        '#swal2-html-container',
      );
    },
    customClass: {
      popup: 'tmbill-swal-pop-up',
      input: 'tmbill-swal-input',
      actions: 'oldkot-swal-action',
    },
    showCancelButton: true,
    // allowOutsideClick: false,
    width: '23em',
    preConfirm: () => {
      const value = $(
        '#swal2-html-container input.changetableInputfield',
      ).val();

      if (!value) {
        return 'Please add valid table name';
      }
      findelementandFire(value.toString(), false).then(async (button_found) => {
        if (
          button_found != undefined &&
          button_found.id != undefined &&
          currenttableButton != undefined
        ) {
          if (
            button_found &&
            button_found.data &&
            button_found.data.details &&
            button_found.data.details.order_state === 'Placed'
          ) {
            window.Swal.showValidationMessage(
              'Order is running on this table.',
            );
            return false;
          }
          const table_id = currenttableButton.id.replace('table_', '');
          const desttable_id = button_found.id.replace('table_', '');
          const destTableOrderFlag = button_found.data.order_type_flag;

          if (
            button_found.data.details.bill_number != undefined &&
            button_found.data.details.bill_number != 0
          ) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t(
                'controller:orderController.pleaseSettleBillOnDestinationTable',
              ),
            );
            return true;
          }

          if (table_id == desttable_id) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.cannotShiftOnSameTable'),
            );
            return;
          }
          const currentItems = tableData.get(currenttableButton.id);
          let selectedItems = currenttableButton.data.details.items;

          if (selectedItems && !selectedItems.length) {
            selectedItems = tableData.get(currenttableButton.id);
          }
          if (
            currenttableButton.data.details.printBillItems &&
            currenttableButton.data.details.printBillItems.length
          ) {
            selectedItems = currenttableButton.data.details.printBillItems;
          }
          const table = $(`#table_${desttable_id}`);
          if (table && table.length) {
            const currenttableButton = table[0];
            if (window.isMultipricingEnabled) {
              selectedItems = checkMultipricing({
                selectedItems,
                department_id: Number(
                  currenttableButton.data['mpos_department.id'],
                ),
              });
            }
          }

          if (!isKOTTableempty) {
            // Append or add KOT Item

            if (tableData.has(button_found.id)) {
              const destItems = tableData.get(button_found.id);
              if (currentItems != undefined && currentItems.length > 0) {
                destItems.push.apply(destItems, currentItems);
              }
              tableData.set(button_found.id, destItems);
            } else {
              const newItems = [];
              newItems.push.apply(newItems, currentItems);
              tableData.set(button_found.id, newItems);
            }
            $(`#${button_found.id}`).css(
              'background-color',
              TableUtils.Colors.KOT_HAS_ITEMS,
            );
            button_found.data.details.color = TableUtils.Colors.KOT_HAS_ITEMS;
            button_found.data.table_action_flag =
              TableUtils.State.KOT_HAS_ITEMS;
          }
          // return
          const changeTabledata = {
            isBillTableempty,
            desttable_id,
            table_id,
            table_color: TableUtils.Colors.KOT_SAVED,
            table_action_flag: TableUtils.State.KOT_SAVED,
            table_color2: TableUtils.Colors.FREE_TABLE,
            table_action_flag2: TableUtils.State.FREE_TABLE,
            table_name: button_found.content,
            from_table_name: currenttableButton.data.table_name,
            selectedItems,
            order_type_flag: currenttableButton.data.order_type_flag,
            destTableOrderFlag: destTableOrderFlag == 0 ? 1 : 2,
            createdBy: window.storeDetails.username,
          };
          initChangeTable(changeTabledata);

          // Check if KOT is saved.
          if (!isBillTableempty) {
            button_found.data.details.color = TableUtils.Colors.KOT_SAVED;
            button_found.data.table_action_flag = TableUtils.State.KOT_SAVED;
            $(`#${button_found.id}`).css(
              'background-color',
              TableUtils.Colors.KOT_SAVED,
            );
          }

          // reset current table
          tableData.set(currenttableButton.id, []);
          $(`#${currenttableButton.id}`).css(
            'background-color',
            TableUtils.Colors.FREE_TABLE,
          );
          currenttableButton.data.details.color = TableUtils.Colors.FREE_TABLE;
          currenttableButton.data.details.items = [];
          currenttableButton.data.details.printBillItems = [];
          currenttableButton.data.details.itemsForItemDiscount = [];

          currenttableButton.data.table_action_flag =
            TableUtils.State.FREE_TABLE;

          $('#kotTable').find('tr:not(:first)').remove();
          $('#billTable').find('tr:not(:first)').remove();
          window.notifyUser.showMessage(
            'success',
            $.i18n.t('controller:orderController.tableShifted'),
          );
          const eventParams = {
            table_id,
            allitemsRemoved: true,
            message: `KOT Update for ${currenttableButton.data.table_name}`,
            transferItem: true,
            destinationtable: desttable_id,
            kotcreatedAt: currenttableButton.data.details.kotcreatedAt,
          };
          // setTimeout(() => {
          sendKotupdateddevent(eventParams);
          // }, 2000);
          setTimeout(() => {
            $(`#table_${table_id}`).click();
          }, 200);
          // // $(`#table_${table_id}`).click();
          setTimeout(() => {
            $(`#table_${desttable_id}`).click();
          }, 650);
        }
      });
    },
  });
}

/**
 * Customer modal open close listener bill
 */
function addcustomermodalListener() {
  $('#customerModal').on('hidden.bs.modal', () => {
    const selectedCustomer = $('#customerModalbodyid').data();
    const activeTab = $('.mainsectionTabs li a.active').attr('id');
    if (selectedCustomer && activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
          {
            $('#kotcustomermobileField').val(selectedCustomer.phone);
            $('#kotcustomernameField').val(selectedCustomer.name);
            $('#kotcustomeraddressField').val('');
          }
          break;
        case TAKEAWAY_TAB_ID:
          {
            $('#takeawaykotcustomermobileField').val(selectedCustomer.phone);
            $('#takeawaykotcustomernameField').val(selectedCustomer.name);
            $('#takotcustomeraddressField').val('');
          }
          break;
        case DELIVERY_TAB_ID:
          {
            $('#deliverykotcustomermobileField').val(selectedCustomer.phone);
            $('#deliverykotcustomernameField').val(selectedCustomer.name);
            $('#deliverykotcustomeraddressField').val('');
          }
          break;
        case QUICK_TAB_ID:
          $('#quickbillkotcustomermobileField').val(selectedCustomer.phone);
          $('#quickbillkotcustomernameField').val(selectedCustomer.name);
          $('#quickkotcustomeraddressField').val('');
          break;
        default:
          break;
      }
      updateCustomer();
    }

    $('#customerModalbodyid').data({});
    $('#customerModalbodyid').removeData();
  });

  $('#customerModal').on('shown.bs.modal', () => {
    $('#customerModalbodyid').data({});
    $('#customerModalbodyid').removeData();
  });
}
