  $('#changeordertypeid').on('click', async () => {
    if (!currenttableButton) {
      window.notifyUser.showMessage('error', 'Please select table');
      return;
    }
    const current_table = currenttableButton.id;
    const items = tableData.get(current_table);
    if (!items || !items.length) {
      window.notifyUser.showMessage('error', 'No items');
      return;
    }

    const selectedType = await showOrderTypesForchangeordertype('1');
    if (selectedType === 'ask order type') {
      return;
    }
    $(`#${currenttableButton.id}`)
      .find('#tablewaiterLabelid')
      .attr('title', '')
      .html('&nbsp');
    if (selectedType && String(selectedType.orderType)) {
      const customer_name = $('#kotcustomernameField').val();
      const customer_phone = $('#kotcustomermobileField').val();
      const country_code = $('#dineinkotdialcodeFieldid').val();
      const customer_address = $('#kotcustomeraddressField').val();
      const kot_note = $('#kotnoteField').val();
      const covers = $('#noofpersonsField').val();

      $('#kotcustomernameField').val('');
      $('#kotcustomermobileField').val('');
      $('#dineinkotdialcodeFieldid').val(window.dial_code);
      $('#kotcustomeraddressField').val('');
      $('#kotnoteField').val('');
      $('#noofpersonsField').val('');
      if (tableData.has(current_table)) {
        // tableData.set(currenttableButton.id, []);
        $('#kotTable').find('tr:not(:first)').remove();
        const tableitems = currenttableButton?.data?.details?.items;
        let table_color = '#007c45';
        if (tableitems && tableitems.length) {
          table_color = '#0095d7';
        }

        setTimeout(() => {
          $(`#${current_table}`).css({ background: table_color });
          currenttableButton = undefined;
        }, 1000);
        let itemsList = [];
        switch (selectedType.orderType) {
          case 2:
            const sourceTableId = currenttableButton && currenttableButton.id;
            if (currenttableButton) {
              $(`#${currenttableButton.id}`).removeClass(
                'selected-table-border',
              );
            }

            currenttableButton = undefined;
            window.globalcurrenttableId = undefined;

            newOrder(true);
            $('#takeawaytabID').tab('show');

            await sleep(100);
            itemsList = transferTableItems({
              items,
              orderType: selectedType.orderType,
              currentTable: undefined,
              itemsList,
            });

            if (itemsList) {
              temptakeawayorderList = itemsList;
              if (sourceTableId && tableData.has(sourceTableId)) {
                tableData.set(sourceTableId, []);
              }
              // $('#takeawaytabID').tab('show');
              $('#takeawaykotcustomernameField').val(customer_name);
              $('#takeawaykotcustomermobileField').val(customer_phone);
              $('#takeawaykotdialcodeFieldid').val(country_code);
              $('#takotcustomeraddressField').val(customer_address);
              $('#takeawaykotnoteField').val(kot_note);
              $('#takeawaynoofpersonsField').val(covers);
              kotCalculation(TAKEAWAY_FLAG_ID);
            }
            break;
          case 3: {
            const sourceTableId = currenttableButton && currenttableButton.id;

            if (currenttableButton) {
              $(`#${currenttableButton.id}`).removeClass(
                'selected-table-border',
              );
            }

            currenttableButton = undefined;
            window.globalcurrenttableId = undefined;

            await newDeliveryOrder(true);
            $('#deliverytabID').tab('show');

            await sleep(50);

            itemsList = transferTableItems({
              items,
              orderType: selectedType.orderType,
              currentTable: undefined,
              itemsList,
              tablesbuttonList,
            });

            if (itemsList) {
              tempdeliveryorderList = itemsList;

              if (sourceTableId && tableData.has(sourceTableId)) {
                tableData.set(sourceTableId, []);
              }

              $('#deliverykotcustomernameField').val(customer_name);
              $('#deliverykotcustomermobileField').val(customer_phone);
              $('#deliverykotdialcodeFieldid').val(country_code);
              $('#deliverykotcustomeraddressField').val(customer_address);
              $('#deliverykotnoteField').val(kot_note);
              $('#deliverynoofpersonsField').val(covers);

              kotCalculation(HOMED_FLAG_ID);
            }

            break;
          }
          default:
            itemsList = transferTableItems({
              items,
              orderType: selectedType.orderType,
              currentTable: currenttableButton,
              itemsList,
              tablesbuttonList,
            });
            if (selectedType.customeOrderId) {
              quickCustomorderId = selectedType.customeOrderId;
            }
            if (itemsList) {
              quickbilltableButton.data.details.items = itemsList;
              tableData.set(currenttableButton.id, []);
              $('#quickbilltabID').tab('show');
              $('#customQuickBillTypeid').html(selectedType.orderTypevalue);
              defaultcustomerQuickordertype = selectedType.orderType;
              quickbilltableButton.data.selectedCustomOrderType =
                selectedType.orderType;
              $('#quickbillkotcustomernameField').val(customer_name);
              $('#quickbillkotcustomermobileField').val(customer_phone);
              $('#quickbillkotdialcodeFieldid').val(country_code);
              $('#quickkotcustomeraddressField').val(customer_address);
              $('#quickbillkotnoteField').val(kot_note);
              $('#quickbillnoofpersonsField').val(covers);
              precalculateDetailsCheck(quickbilltableButton);
              if (orderTypeWiseOrderNumber) {
                const orderNumbers = safeParse(
                  nextKOTOrderAndBillNumberData.order_type_wise_order_number,
                );
                $('#nextordernoforquickBillid').html(
                  `${customOrderNumberName}: ${orderNumbers[selectedType.orderType] ? orderNumbers[selectedType.orderType] : 1}`,
                );
              }
            }
            break;
        }
      }
    }
  });

