  $(document).on('blur', '#kotTable tr .editable', function () {
    const item_id = $(this).attr('item_id');
    const itemData = $(this).parent().parent().data();
    let newQty = $(this).text();
    if (newQty) {
      if (Number(newQty) > 10000) {
        newQty = 1;
        window.notifyUser.showMessage(
          'error',
          'Quantity should be less than 10000',
        );
      }

      if (window.specialCharRegex.test(newQty) || isNaN(newQty)) {
        newQty = 1;
        window.notifyUser.showMessage('error', 'Please enter valid quantity');
      }
    }
    if (currenttableButton != undefined && item_id != undefined) {
      try {
        const quantityDecimals = Number(newQty).countDecimals();
        if ([2, 3].includes(quantityDecimals)) {
          newQty = Number(Number(newQty).toFixed(quantityDecimals));
        } else {
          newQty = Number(Number(newQty).toFixed(ROUNDOFF_UPTO));
        }
      } catch (error) {
        newQty = 1;
      }
      const items = tableData.get(currenttableButton.id);
      const kotDiv = document.querySelector('.kottableDiv');
      if (kotDiv) {
        kotDiv._lastScrollTop = kotDiv.scrollTop;
      }
      $('#kotTable').find('tr:not(:first)').remove();
      let discountedItemsavailable;
      let isAddonsAvaliable = false;
      items.forEach((item) => {
        if (item && item.amount !== undefined) {
          let roundoffto = 2;
          if (item.amount && Number(item.amount).countDecimals() >= 3) {
            roundoffto = 3;
          }
          let comparewith = item.title;
          if (item.is_open_item && item.newopenitemName) {
            comparewith = item.newopenitemName;
          }

          if (item.isitemwithOption) {
            comparewith = item.titlewithOption;
          }

          let itemTitle = itemData.title;
          if (item.isitemwithOption) {
            itemTitle = itemData.titlewithOption;
          }
          if (
            itemTitle === comparewith &&
            item.price === itemData.price &&
            item.short_code === itemData.short_code &&
            item.note === itemData.note
          ) {
            // if (itemData.title === comparewith) {
            if (reduceStock) {
              if (newQty > itemData.current_stock) {
                window.notifyUser.showMessage(
                  'error',
                  `Only ${itemData.current_stock} items available. You can add upto ${itemData.current_stock} items`,
                );
                newQty = itemData.current_stock;
              }
              const getItems = items.filter(
                (i) => i.item_refid === item.item_refid,
              );

              let totalStock = itemData.current_stock;
              let currentSelectedQty = 0;
              if (getItems && getItems.length > 1) {
                // totalStock = items.reduce((sum, item) => {
                //   return sum + (item.current_stock || 0);
                // }, 0);

                currentSelectedQty = getItems.reduce((sum, item) => {
                  return sum + (item.quantity || 0);
                }, 0);

                const totQty =
                  currentSelectedQty + (newQty - itemData.quantity);
                if (totQty > totalStock) {
                  window.notifyUser.showMessage(
                    'error',
                    `Only ${itemData.current_stock} items available. You can add upto ${itemData.current_stock} items`,
                  );
                  newQty = itemData.quantity;
                }
              }
            }
            item.quantity =
              newQty && typeof newQty === 'number' && newQty > 0
                ? newQty
                : item.quantity;

            // item.quantity = Math.floor(item.quantity);
            item.amount = item.price * item.quantity;
            item.amount = Number(Number(item.amount).toFixed(3));
            item.amount = Number(
              roundAmountUptoDecimals(item.amount, roundoffto),
            );

            if (newQty !== itemData.quantity && itemData.discounted_items) {
              discountedItemsavailable = item;
            }
            if (item.addons && item.addons.length) {
              isAddonsAvaliable = true;
            }
          }
          addKOTRow(DINEIN_KOTTABLE, item);
        }
      });
      if (discountedItemsavailable && !isAddonsAvaliable) {
        addDiscounteditems(
          discountedItemsavailable.quantity,
          discountedItemsavailable,
          DINEIN_KOTTABLE,
        );
      }
    }
  });

