                  item.amount = Number(Number(item.amount).toFixed(roundoffto));

                  if (
                    newQty !== itemData.quantity &&
                    itemData.discounted_items
                  ) {
                    discountedItemsavailable = item;
                  }
                  if (item.addons && item.addons.length) {
                    isAddonsAvaliable = true;
                  }
