function addorEditcurrentcustomer(type) {
  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }

  if (
    currenttableButton.data.details.items != undefined &&
    currenttableButton.data.details.items.length == 0
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseAddSomeItems'),
    );
    return;
  }

  let nameField;
  let mobileField;
  let addressField;

  switch (type) {
    case DINEIN_FLAG_ID:
      nameField = '#kotcustomernameField';
      mobileField = '#kotcustomermobileField';
      addressField = '#kotcustomeraddressField';
      break;
    case TAKEAWAY_FLAG_ID:
      nameField = '#takeawaykotcustomernameField';
      mobileField = '#takeawaykotcustomermobileField';
      addressField = '#takotcustomeraddressField';
      break;
    case HOMED_FLAG_ID:
      nameField = '#deliverykotcustomernameField';
      mobileField = '#deliverykotcustomermobileField';
      addressField = '#deliverykotcustomeraddressField';
      break;
    default:
      break;
  }
  addoreditCustomerdetails({
    customers: window.customersList,
    nameField,
    mobileField,
    addressField,
    order_id:
      currenttableButton.data.details.bill_number != undefined &&
      currenttableButton.data.details.bill_number == 0
        ? undefined
        : currenttableButton.data.details.bill_number,
    table_id: currenttableButton ? currenttableButton.data.id : 0,
  }).then(async (response) => {
    if (response.customerAddedorupdated) {
      if (currenttableButton && response.customer) {
        const previousCustomer = currenttableButton.data.details.customer;
        currenttableButton.data.details.customer = response.customer;
        if (response.customer.name) {
          $(`#${currenttableButton.id}`)
            .find('#tablecustomernameLabelid')
            .html(response.customer.name);
        }
        sendTableClickEvent({
          table_id: currenttableButton?.data.id || 0,
          message: 'Table clicked',
          order_total: currenttableButton?.data?.details?.order_total || 0,
          bill_number: currenttableButton?.data?.details?.order_id,
          kot_numbers: currenttableButton?.data?.details?.kot_numbers,
          order_state: currenttableButton?.data?.details?.order_state,
          customer_name: response.customer.name,
        });
        window.refreshOrderSettlementWindow = true;
        if (
          previousCustomer.phone &&
          response.customer.phone &&
          previousCustomer.phone !== response.customer.phone &&
          currenttableButton?.data?.details?.extra_details &&
          currenttableButton?.data?.details?.extra_details?.rewardDiscount
        ) {
          resetCurrentdiscount(currenttableButton);
          await precalculateDetailsCheck(currenttableButton);
          sendRewardhistory({
            reward: '',
            order_id: currenttableButton.data.details.bill_number,
            phone: previousCustomer.phone,
            customer_name: previousCustomer.name,
            isQuickbill: 0,
            action: 'delete',
          });
          const discountData = {
            id: 0,
            is_modifiable: 0,
            discount_type: 0,
            rate: 0,
            product_groups: '',
            title: '',
            discount_name: '',
            instructions: '',
          };

          const table_id = currenttableButton.id.replace('table_', '');
          const paymentData = {
            table_id,
            data: discountData,
            order_id: currenttableButton.data.details.bill_number,
          };
          const activeTab = $('.mainsectionTabs li a.active').attr('id');

          delete currenttableButton?.data?.details?.extra_details
            ?.rewardDiscount;
          currenttableButton.data.details.discount = 0;
          sendDiscountupdate(currenttableButton, activeTab, paymentData);
        }
      }
      updateCustomer();
    }
  });
}

