async function sendPaymentlink() {
  if (!window.storeDetails || !window.storeDetails.upi_id) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseAddUpiIdFromBackoffice'),
    );
    return;
  }
  if (currenttableButton == undefined) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return;
  }
  if (
    !currenttableButton.data.details.customer ||
    !currenttableButton.data.details.customer.phone
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectCustomer'),
    );
    return;
  }

  if (
    currenttableButton.data.details.bill_number != undefined &&
    currenttableButton.data.details.bill_number != 0
  ) {
    const amount = Number(currenttableButton.data.details.order_total).toFixed(
      window.ROUNDOFF_UPTO,
    );
    const { phone } = currenttableButton.data.details.customer;
    const { name } = currenttableButton.data.details.customer;
    sendEbill({
      phone,
      name,
      amount: Number(amount),
      order_id: currenttableButton.data.details.bill_number,
      // delivery_type: BillingTypes[currenttableButton.data.order_type_flag + 1],
      delivery_type:
        window.orderTypes[Number(currenttableButton.data.order_type_flag + 1)]
          .order_type,
      for_payment_link: 1,
    });
  } else {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.saveTheBillFirst'),
    );
  }
}
/**
 * Add the filters to the list aand set
 * the listeners to them
 */
function tableFilters() {
  // Create a list of filters
  const toolTipnew = $('<ul>', {
    class: 'table-filters-list',
    id: 'table-filters-list-id',
  });

  // Add a default all filter with the value
  const alltemp = $('<li>', {
    html: $.i18n.t(`controller:orderController.filterTables.All`),
    value: -1,
    click: toggleCurrentfilter,
  });
  const allcheck = $('<i>', {
    class: 'fas fa-check',
  });
  let timer;
  // Append it to the list
  alltemp.append(allcheck);
  toolTipnew.append(alltemp);

  // Get the Table states and append them to the list
  // with listener attathced to them
  _.keys(TableUtils.State).forEach((value) => {
    const temp = $('<li>', {
      // html: _.startCase(_.capitalize(value)),
      html: $.i18n.t(`controller:orderController.filterTables.${value}`),
      value: TableUtils.State[value],
      click: toggleCurrentfilter,
    });
    const check = $('<i>', {
      class: 'fas fa-check',
      style: 'display:none',
    });
    temp.append(check);
    toolTipnew.append(temp);
  });

  // Pre Order filter
  const preordertemp = $('<li>', {
    html: $.i18n.t(`controller:orderController.filterTables.preOrder`),
    value: 'preorder',
    click: toggleCurrentfilter,
  });
  const preordercheck = $('<i>', {
    class: 'fas fa-check',
    style: 'display:none',
  });
  preordertemp.append(preordercheck);
  toolTipnew.append(preordertemp);

  // Unsettled
  const unSettledtemp = $('<li>', {
    html: $.i18n.t(`controller:orderController.filterTables.UNSETTLED`),
    value: 'Unsettled',
    click: toggleCurrentfilter,
  });

  const unSettledcheck = $('<i>', {
    class: 'fas fa-check',
    style: 'display:none',
  });
  unSettledtemp.append(unSettledcheck);
  toolTipnew.append(unSettledtemp);

  // Delivery boy not assigned
  const DeliveryBoyNotAssigned = $('<li>', {
    html: $.i18n.t(
      `controller:orderController.filterTables.DELIVERY_BOY_NOT_ASSIGNED`,
    ),
    value: 'DeliveryBoyNotAssigned',
    click: toggleCurrentfilter,
  });

  const DeliveryBoyNotAssignedcheck = $('<i>', {
    class: 'fas fa-check',
    style: 'display:none',
  });

  DeliveryBoyNotAssigned.append(DeliveryBoyNotAssignedcheck);
  toolTipnew.append(DeliveryBoyNotAssigned);

  // Close the popup if it leaves the popover
  $(document).on('mouseleave', '#table-filters-list-id', () => {
    $('#filterButton').popover('hide');
  });

  // This will be triggered when the mouse is entered
  // on the list of filter and clears the settimeout
  // when will be triggered after 5 seconds when
  // the popover is open.By cancelling it we don't have
  // to worry about accidental popover closes.
  $(document).on('mouseenter', '#table-filters-list-id', () => {
    clearTimeout(timer);
  });

  // Add a settimeout of 5 seconds to close
  // the popover if user doesnot interact with
  // the filter list
  $('#filterButton').on('click', () => {
    timer = setTimeout(() => {
      $('#filterButton').popover('hide');
    }, 5000);
  });
  const options = {
    content: toolTipnew[0],
    html: true,
  };
  $('#filterButton').addClass('custom-popover').popover(options);
}

function toggleCurrentfilter(element) {
  if (element) {
    $('#table-filters-list-id li i').hide();
    $(element.target).find('i').show();
    filtertableBystatus($(element.target).attr('value'));
  }
  $('#filterButton').popover('hide');
}

/**
 *
 * @param {Filter Status} status
 */
function filtertableBystatus(status) {
  // table_action_flag
  // Check if all is checked which has a value of -1
  if (Number(status) === -1) {
    $('#tablesContainer').children().show();
  } else {
    $('#tablesContainer')
      .children()
      .each(function () {
        let show = this.data.table_action_flag == status;
        if (status === 'preorder' && this.data.is_pre_order) {
          show = true;
        }
        if (status === 'Unsettled' && this.data.table_action_flag !== 0) {
          show = true;
        }
        if (
          status === 'DeliveryBoyNotAssigned' &&
          this.data.order_type_flag === 2
        ) {
          // show = true;
          if (
            this.data &&
            this.data.details &&
            !this.data.details.delivery_boy_name
          ) {
            show = true;
          }
        }
        show ? $(this).show() : $(this).hide();
      });
  }
}

