async function applyItemleveldiscount({
  forKottable,
  item_id,
  option_ref_id,
  title,
  note,
}) {
  if (item_id) {
    let items = [];
    const activeTab = $('.mainsectionTabs li a.active').attr('id');
    if (activeTab) {
      switch (activeTab) {
        case DINEIN_TAB_ID:
          if (currenttableButton == undefined) {
            window.notifyUser.showMessage(
              'error',
              $.i18n.t('controller:orderController.pleaseSelectTheTable'),
            );
            return;
          }
          currentTableinstace = currenttableButton;
          items = tableData.get(currenttableButton.id);
          break;
        case TAKEAWAY_TAB_ID:
          items = temptakeawayorderList;
          break;
        case DELIVERY_TAB_ID:
          items = tempdeliveryorderList;
          break;

        case QUICK_TAB_ID:
          currentTableinstace = quickbilltableButton;
          items = quickbilltableButton.data.details.items;
          break;
        default:
          break;
      }
    }

    // if (item.isitemwithOption) item_id = item.option_ref_id;
    if (items && Array.isArray(items) && items.length > 0) {
      const searchItembyifresult = option_ref_id
        ? _.find(items, { option_ref_id: item_id })
        : _.find(items, { id: Number(item_id), note });
      if (searchItembyifresult) {
        if (searchItembyifresult.modified_discount !== 1) {
          window.notifyUser.showMessage(
            'error',
            `${$.i18n.t(
              'controller:orderController.discountModificationIsNowAllowedFor',
            )} ${searchItembyifresult.title}`,
          );
          return;
        }
        const discountedItem =
          await askforItemleveldiscount(searchItembyifresult);
        if (discountedItem) {
          const index = option_ref_id
            ? _.findIndex(items, { option_ref_id: item_id })
            : _.findIndex(items, { id: Number(item_id), note });
          if (activeTab && index >= 0) {
            items.splice(index, 1, discountedItem);
            switch (activeTab) {
              case DINEIN_TAB_ID:
                tableData.set(currenttableButton.id, items);
                if (forKottable) {
                  $('#kotTable').find('tr:not(:first)').remove();
                  items.forEach((item) => {
                    addKOTRow(DINEIN_KOTTABLE, item);
                  });
                }
                break;
              case TAKEAWAY_TAB_ID:
                temptakeawayorderList = items;
                if (forKottable) {
                  $(`#${TAKEAWAY_KOTTABLE}`).find('tr:not(:first)').remove();
                  items.forEach((item) => {
                    addKOTRow(TAKEAWAY_KOTTABLE, item);
                  });
                }
                break;

              case DELIVERY_TAB_ID:
                tempdeliveryorderList = items;
                if (forKottable) {
                  $(`#${DELIVERY_KOTTABLE}`).find('tr:not(:first)').remove();
                  items.forEach((item) => {
                    addKOTRow(DELIVERY_KOTTABLE, item);
                  });
                }
                break;

              case QUICK_TAB_ID:
                $('#quickbillTable').find('tr:not(:first)').remove();
                items.forEach((item) => {
                  addKOTRow(QUICK_BILLTABLE, item);
                });
                precalculateDetailsCheck(quickbilltableButton);
                break;
              default:
                break;
            }
          }
        }
      }
    }
  }
}

