let kotnotesuggestions = [];
async function additemnotesuggestions(elementId) {
  $(elementId).autocomplete({
    source(req, response) {
      const sourceData = [];
      const re = $.ui.autocomplete.escapeRegex(req.term);
      response(
        $.grep(kotnotesuggestions, (itemnote) => {
          if (String(itemnote).toLowerCase().includes(re.toLowerCase())) {
            sourceData.push({
              label: itemnote,
              // value: itemnote,
            });
          }
        }),
      );
      return response(sourceData);
    },
    appendTo: '#swal2-html-container',
    classes: {
      'ui-autocomplete': 'autocomplete-to-front ',
    },
    select(event, ui) {
      $(elementId).text(ui.item.value);
    },
  });
}

function findDifference(str1, str2) {
  return str2.replace(str1, '').trim();
}
/**
 * Show KOT Note Pop up
 */

function showKOTNotepopup(
  item_id,
  item_refid,
  suggestions,
  itemNoteGroup,
  itemnote,
  title,
) {
  kotnotesuggestions = suggestions;
  let groupedNotes = '';
  const popup = Swal.mixin({
    customClass: {
      popup: 'tmbill-swal-pop-up',
      title: 'tmbill-swal-title-class',
      content: 'tmbill-swal-title-class',
    },
  });

  // let list = $('<datalist></datalist>').attr('id', 'kotnoteSuggestions');
  const itemNotesGroupContainer = $('<div></div>').attr(
    'id',
    'itemNotGroupContainer',
  );

  // Create two child divs
  const groupTitleContainer = $('<div></div>').addClass('groupTitleContainer');
  const itemNotesContainer = $('<div></div>').addClass('itemNotesContainer');

  // Append child divs to main container
  itemNotesGroupContainer.append(groupTitleContainer, itemNotesContainer);
  const list = $('<ul></ul>').attr('id', 'kotnoteSuggestions');
  const labellist = $('<ul></ul>').attr('id', 'noteGroupTitleSuggestions');
  const selectedNotes = {
    customNotes: '',
  };
  let freeNotes = [];
  if (itemNoteGroup && itemNoteGroup.length > 1) {
    const groupLabel = $(`<li class="item-note-group-label">All</li>`).attr(
      'item_note_id',
      'All',
    );
    labellist.append(groupLabel);
  }
  if (itemNoteGroup && itemNoteGroup.length) {
    const grouplabelContainer = $(
      `<div class="item-note-group-container"></div>`,
    );
    itemNoteGroup.forEach((group) => {
      selectedNotes[group.tag_group_name] = '';
      const tags_info = safeParse(group.tags_info);
      if (tags_info && tags_info.itemTags) {
        const suggestions = tags_info.itemTags.split(',');
        const groupContainer = $(
          `<div class="item-note-group-container"></div>`,
        );
        const groupLabel = $(
          `<li class="item-note-group-label">${group.tag_group_name}</li>`,
        ).attr('item_note_id', group.item_note_id);
        labellist.append(groupLabel);
        // const groupDiv = $(`<div></div>`);
        suggestions.forEach((element) => {
          // list.append($('<option>').text(element));
          list.append(
            $('<li>', {
              class: `list-group-item discount-row item_note_class itemNoteGroup_${group.item_note_id}`,
              text: element,
              groupName: group.tag_group_name,
              groupId: group.item_note_id,
              // style: 'display: inline-block',
              style: `background-color:${tags_info.backgroundColor}30 !important; display: inline-block; color:${tags_info.backgroundColor}; border: 1px solid ${tags_info.backgroundColor} `,
            }),
          );
        });
        // groupContainer.append(groupLabel);
        // groupContainer.append(groupDiv);
        // list.append(groupContainer);
      }
    });
  }
  groupTitleContainer.append(labellist);
  itemNotesContainer.append(list);
  if (suggestions.length > 0) {
    suggestions.forEach((element) => {
      // list.append($('<option>').text(element));
      if (element.length) {
        list.append(
          $('<li>', {
            class: `list-group-item discount-row item_note_class`,
            text: element,
            style: 'display: inline-block',
          }).append(
            $('<a>', {
              class:
                'fas  fa-times-circle delete-rowitem-icon item-note-delete',
            }),
          ),
        );
      }
    });
  }
  popup.fire({
    title: $.i18n.t('controller:orderController.enterItemNote'),
    input: 'text',
    showCancelButton: true,
    allowOutsideClick: false,
    confirmButtonText: $.i18n.t('controller:swalDataTranslations.ApplyNote'),
    id: 'itemnotesuggestion',
    width: '48em',
    html: itemNotesGroupContainer,
    inputAttributes: {
      autocomplete: 'on',
      list: 'kotnoteSuggestions',
      id: 'itemnote-input',
    },
    cancelButtonText: $.i18n.t('controller:orderController.changeTable.Cancel'),
    didOpen: async () => {
      // await additemnotesuggestions('input#itemnote-input');
      // $('#itemnote-input').val(itemnote);
    },
    didRender: () => {
      if (itemnote) {
        let groupNotesPart = itemnote;
        let freeNotesPart = '';

        if (itemnote.includes('&')) {
          const parts = itemnote.split('&');
          groupNotesPart = parts[0].trim();
          freeNotesPart = parts[1].trim();
        }

        const groupNotesArray = groupNotesPart
          .split(',')
          .map((n) => n.trim())
          .filter(Boolean);

        const freeNotesArray = freeNotesPart
          ? freeNotesPart
              .split(',')
              .map((n) => n.trim())
              .filter(Boolean)
          : [];

        itemNoteGroup.forEach((group, index) => {
          const noteText = groupNotesArray[index];

          if (noteText) {
            const normalize = (str) => str.replace(/\s+/g, ' ').trim();

            // console.log(
            //   'roup.item_note_id::',
            //   $(`.itemNoteGroup_${group.item_note_id}`),
            // );
            const $match = $(`.itemNoteGroup_${group.item_note_id}`).filter(
              function () {
                return (
                  normalize(
                    $(this).clone().children().remove().end().text(),
                  ) === normalize(noteText)
                );
              },
            );

            // console.log('$match::', $match);

            if ($match.length) {
              $match.addClass('selectedItemNote');
              selectedNotes[group.tag_group_name] = noteText;
            }
          }
        });

        freeNotesArray.forEach((noteText) => {
          if (!freeNotes.includes(noteText)) {
            freeNotes.push(noteText);
            // If already in suggestions, just highlight
            const $match = $('.item_note_class').filter(function () {
              return $(this).text().trim() === noteText;
            });
            if ($match.length) {
              $match.addClass('selectedItemNote');
            } else {
              // Add custom note to UI
              // $('#kotnoteSuggestions').append(
              //   $('<li>', {
              //     class: 'list-group-item discount-row item_note_class selectedItemNote',
              //     text: noteText,
              //     style: 'display: inline-block',
              //   }).append(
              //     $('<a>', {
              //       class: 'fas fa-times-circle delete-rowitem-icon item-note-delete',
              //     })
              //   )
              // );
            }
          }
        });

        // Rebuild groupedNotes for saving
        groupedNotes = groupNotesArray.join(', ');
        if (freeNotes.length) {
          groupedNotes = groupedNotes
            ? `${groupedNotes} & ${freeNotes.join(',')}`
            : freeNotes.join(',');
        }

        // Put the note string into the input
        $('#itemnote-input').val(itemnote);
      }

      // Attach event to the button
      const Notes = document.querySelectorAll('.item_note_class');
      Notes.forEach((note) => {
        $(note).click(() => {
          const text = $(note).text();
          const selectedGroup = $(note).attr('groupName');
          const selectedGroupId = $(note).attr('groupId');
          $(`.itemNoteGroup_${selectedGroupId}`).removeClass(
            'selectedItemNote',
          );
          if (selectedNotes.hasOwnProperty(selectedGroup)) {
            if (selectedNotes[selectedGroup] == text) {
              // $(note).removeClass('selectedItemNote');
              selectedNotes[selectedGroup] = '';
            } else {
              $(note).addClass('selectedItemNote');
              selectedNotes[selectedGroup] = text;
            }
          } else if (!freeNotes.includes(text)) {
            freeNotes.push(text);
            $(note).addClass('selectedItemNote');
          } else {
            $(note).removeClass('selectedItemNote');
            freeNotes = freeNotes.filter((item) => item !== text);
          }
          groupedNotes = Object.entries(selectedNotes)
            .filter(([_, value]) => value) // Remove empty values
            .map(([key, value]) => `${value}`)
            .join(', ');

          if (freeNotes && freeNotes.length) {
            const freeNotesText = freeNotes.join(',');
            if (groupedNotes && groupedNotes.length) {
              groupedNotes = `${groupedNotes} & ${freeNotesText}`;
            } else {
              groupedNotes = freeNotesText;
            }
          }
          $('#itemnote-input').val(groupedNotes);
        });
      });

      $('li .item-note-delete').on('click', function (e) {
        e.preventDefault();

        const text = $(this).closest('li').text().trim();
        $(this).closest('li').remove();

        $('#itemnote-input').val('');
        groupedNotes = '';
        freeNotes = [];
        Object.keys(selectedNotes).forEach((k) => (selectedNotes[k] = ''));

        // update source data
        if (currenttableButton && tableData.has(currenttableButton.id)) {
          const items = tableData.get(currenttableButton.id);
          const item = items.find(
            (i) => String(i.item_refid) === String(item_refid),
          );
          if (item) {
            item.note = '';
          }
        }

        // 🔹 remove note immediately from UI row
        $(`tr[item_refid="${item_refid}"] .kotrowItemNoteid`).remove();

        initDeleteItemNote({
          item_refid,
          note: text,
          store_id: window.storeDetails.store_id,
        });
      });

      $('#noteGroupTitleSuggestions .item-note-group-label').on(
        'click',
        function () {
          $('#noteGroupTitleSuggestions .item-note-group-label').removeClass(
            'activeItemNoteGroup',
          );
          $(this).addClass('activeItemNoteGroup');
          filterItemNote($(this).attr('item_note_id'));
        },
      );
    },
    inputPlaceholder: $.i18n.t('controller:orderController.enterItemNote'),
    inputValidator: (value) => {
      if (!value) {
        return 'Please add valid note';
      }
      if (value) {
        // if (value.length > 100) {
        //   return 'Item note should be less than 100 characters';
        // }

        if (window.specialCharRegex.test(value)) {
          return 'Special characters are not allowed in item note';
        }
      }
      value = String(value).replace('#', '');
      // Max note length
      if (value.length > 100) {
        value = value.substring(0, 100);
      }
      addkotnoteormakeComplementary(item_id, value, undefined, title);

      let newNote = $('#itemnote-input').val();
      if (newNote && newNote.includes(',')) {
        let splitNotes = newNote
          .split(',')
          .map((n) => n.trim())
          .filter(Boolean);

        newNote = splitNotes.join(', ');
      }
      if (groupedNotes && groupedNotes.length) {
        const output = findDifference(groupedNotes, newNote);
        newNote = output;
      }
      initAddItemNote(
        JSON.stringify({
          item_refid,
          note: newNote,
          store_id: window.storeDetails.store_id,
        }),
      );
    },
  });
}

