/**
 * Removes the array object by its key and value pair
 * @param {Given array} arr
 * @param {Object key} attr
 * @param {Object value to match} value
 */
let removeByAttr = function (arr, attr, value, price, item_refid) {
  let i = arr.length;
  if (checkifNumber(value)) {
    while (i--) {
      if (
        arr[i] &&
        arr[i].hasOwnProperty(attr) &&
        arguments.length > 2 &&
        arr[i][attr] === Number(value)
      ) {
        arr.splice(i, 1); // i is a starting point and  1 is number of elements to remove
      }
    }
  } else {
    while (i--) {
      // if item note is added then add it in title
      let attrToCompare = `${arr[i][attr]}`;
      if (attr === 'title') {
        attrToCompare = `${arr[i][attr]} ${arr[i].price}`;
      }
      if (arr[i].note) {
        attrToCompare = `${arr[i][attr]} ${arr[i].price} ${arr[i].note}`;
      }

      if (attr === 'option_ref_id') {
        attrToCompare = `${arr[i][attr]}`;
      }

      if (
        arr[i] &&
        arr[i].hasOwnProperty(attr) &&
        ((arguments.length > 2 && attrToCompare === String(value)) ||
          // arr[i].discountedParent == String(value))
          arr[i].bogoBaseItemRefId == `bogo_ref_id_${item_refid}`)
      ) {
        arr.splice(i, 1); // i is a starting point and  1 is number of elements to remove
      }
    }
  }

  return arr;
};

