function formatBarcode(barcode) {
  // const part1 = barcode.slice(0, 7);
  // const part2 = barcode.slice(7);
  // const nextFour = part2.slice(0, 4);

  // const integerPart = parseInt(nextFour.slice(0, -2), 10) || 0;
  // const decimalPart = nextFour.slice(-2);

  // // Format like 0.26 or 1.26 etc.
  // const formattedPart2 = `${integerPart}.${decimalPart}`;

  // // Final result
  // return `${part1} ${formattedPart2}`;

  const part1 = barcode.slice(0, 7);
  const part2 = barcode.slice(7);

  const integerPart = part2.slice(0, 2); // Keep leading zeros
  const decimalPart = part2.slice(2); // Last 4 digits

  const formattedPart2 = `${integerPart}.${decimalPart}`;
  return `${part1} ${formattedPart2}`;
}

async function openRunningOrder(bill_number) {
  // $(`#table_${table_id}`).click();
  const response = await getRunningOrderDetialsRequest({ bill_number });
  if (response) {
    const table_id = response.table_id;
    // $(`#table_${response.table_id}`).click();
    const table = $(`#table_${table_id}`);
    if (table && table.length) {
      const tableData = table[0].data;
      if (tableData && tableData.table_action_flag !== 0) {
        $(`#table_${table_id}`).click();
        setTimeout(() => {
          const activeTab = $('.mainsectionTabs li a.active').attr('id');

          const isVisible = $('#tablesParentdivclassid').is(':visible');
          if (activeTab && isVisible) {
            switch (activeTab) {
              case DINEIN_TAB_ID:
                if ($('#paymentButton2').is(':visible')) {
                  $('#paymentButton2').click();
                }
                break;
              case TAKEAWAY_TAB_ID:
                if ($('#takeawaypaymentButton2').is(':visible')) {
                  $('#takeawaypaymentButton2').click();
                }
                break;
              case DELIVERY_TAB_ID:
                if ($('#deliverypaymentButton2').is(':visible')) {
                  $('#deliverypaymentButton2').click();
                }
                break;
              default:
                break;
            }
          }
        }, 100);
      }
    }
  }
}

/**
 *  Filter buttons whose name matches the parameter
 * @param {Item name} data
 */

async function search(data, byCode) {
  const activeTab = $('.mainsectionTabs li a.active').attr('id');

  if (data && data.startsWith('TM_')) {
    const order_id = data.replace('TM_', '');
    openRunningOrder(order_id);
    byCode ? $('#searchitembyCode').val('') : $('#searchByname_item').val('');
    return;
  }

  if (
    byCode &&
    activeTab &&
    activeTab == DINEIN_TAB_ID &&
    currenttableButton == undefined
  ) {
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.pleaseSelectTheTable'),
    );
    return 'failure';
  }

  // 13 digit barcode
  const short_code = data;
  let retryCheck = 1; // added this else it will go in infinite loop if item not found
  if (data.length === 13 && !data.startsWith('withoutQty_')) {
    data = formatBarcode(data);
  }
  if (data.startsWith('withoutQty_')) {
    data = data.replace('withoutQty_', '');
    retryCheck += 1;
  }
  if (data.includes(':')) {
    data = data.split(':')[0];
  }

  let filter;
  filter = data.toLowerCase();
  const myNode = document.getElementById('itemviewContainer');
  const descendents = myNode.getElementsByTagName('*');

  let i;
  let currentDescedent;

  // CHeck if quantity is provided
  const result = filter.split(' ');
  let quantity = 1;
  // if (result.length == 2 && checkifNumber(result[1])) {
  if (result.length == 2) {
    quantity = result[1];
    if (quantity === '0') {
      quantity = 1;
    }
    filter = result[0];
  }
  let suffix = 'item_';
  if (byCode) {
    suffix += filter;
  }

  let itemFound = false;
  for (i = 0; i < descendents.length; ++i) {
    currentDescedent = descendents[i];
    if (
      currentDescedent != undefined &&
      currentDescedent.content != undefined
    ) {
      var matches = currentDescedent.content.match(/\b(\w)/g);
    }
    if (matches) {
      var acronym = matches.join('').toLowerCase();
    }
    if (byCode) {
      const attr = $(currentDescedent).attr('isSectionWiseItem');

      if (
        (storeDetails.is_bar_section_billing || itemFileterByOrderType) &&
        activeTab == DINEIN_TAB_ID
      ) {
        if (
          String(currentDescedent.id).toLowerCase() ===
            String(suffix).toLowerCase() &&
          attr == 'true'
        ) {
          if (itemFileterByOrderType) {
            const activeOrderType = $('.mainsectionTabs li a.active').attr(
              'orderType',
            );
            const productGroupList = String(
              currentDescedent.data.excludePlaforms,
            ).split(',');

            if (productGroupList.includes(String(activeOrderType))) {
              window.notifyUser.showMessage(
                'error',
                `${currentDescedent.data.title} is not available for this order type`,
              );
              $('#searchitembyCode').val('');
              return;
            }
          }
          currentDescedent.data.quantity = quantity;
          currentDescedent.data.addedByShortCode = true;
          currentDescedent.data.addedByShortCodeQuantity = quantity;
          $(`#${currentDescedent.id}`).click();
          $('#searchitembyCode').val('');
          itemFound = true;
          break;
        }
      } else if (
        String(currentDescedent.id).toLowerCase() ===
        String(suffix).toLowerCase()
      ) {
        // 🔒 ADD THIS VALIDATION BLOCK
        if (itemFileterByOrderType) {
          const activeOrderType = $('.mainsectionTabs li a.active').attr(
            'orderType',
          );
          const productGroupList = String(
            currentDescedent.data.excludePlaforms,
          ).split(',');

          if (productGroupList.includes(String(activeOrderType))) {
            window.notifyUser.showMessage(
              'error',
              `${currentDescedent.data.title} is not available for this order type`,
            );
            $('#searchitembyCode').val('');
            return;
          }
        }

        currentDescedent.data.quantity = quantity;
        currentDescedent.data.addedByShortCode = true;
        currentDescedent.data.addedByShortCodeQuantity = quantity;
        $(`#${currentDescedent.id}`).click();
        $('#searchitembyCode').val('');
        itemFound = true;
        break;
      }
    } else {
      // isSectionWiseItem attribute added for searching items section wise
      const attr = $(currentDescedent).attr('isSectionWiseItem');
      if (currentDescedent != undefined) {
        if (
          (currentDescedent.content != undefined &&
            !currentDescedent.content
              .toLowerCase()
              .trim()
              .includes(filter.trim()) &&
            !acronym.toLowerCase().trim().includes(filter.trim())) ||
          attr == 'false'
        )
          currentDescedent.style.display = 'none';
        else currentDescedent.style.display = '';
      }
    }
  }

  if (byCode && !itemFound) {
    // if shortcode with qty and not found item then this maybe retail item so check without qty
    if (short_code.length === 13 && retryCheck === 1) {
      const changedShortCode = `withoutQty_${short_code}`;
      search(changedShortCode, true);
      return;
    }
    window.notifyUser.showMessage(
      'error',
      $.i18n.t('controller:orderController.itemCodeDoesNotExists'),
    );
  }
}

async function searchDiscount(data) {
  let filter = data.toLowerCase();
  const myNode = document.getElementById('discountsListCombo');
  const descendents = myNode.getElementsByTagName('*');

  let i, currentDescedent;
  let matches, acronym;
  let anyVisible = false;

  for (i = 0; i < descendents.length; ++i) {
    currentDescedent = descendents[i];
    matches = null;
    acronym = '';

    if (
      currentDescedent != undefined &&
      $(currentDescedent).attr('content') != undefined
    ) {
      matches = $(currentDescedent)
        .attr('content')
        .match(/\b(\w)/g);
      if (matches) {
        acronym = matches.join('').toLowerCase();
      }
    }

    if (
      currentDescedent != undefined &&
      $(currentDescedent).attr('content') != undefined
    ) {
      if (
        !$(currentDescedent)
          .attr('content')
          .toLowerCase()
          .trim()
          .includes(filter.trim()) &&
        !acronym.toLowerCase().trim().includes(filter.trim())
      ) {
        currentDescedent.style.display = 'none';
      } else {
        currentDescedent.style.display = '';
        anyVisible = true;
      }
    }
  }

  // remove old message if any, then show message when nothing matched
  $('#discountsListCombo .no-discount-found').remove();
  if (!anyVisible) {
    $('#discountsListCombo').append(
      `<li class="no-discount-found" style="margin-top: 30px;">No Discount Found</li>`,
    );
  }
}

