// scrollissue
function enableTreeTouchScroll() {
  const tree = document.getElementById('tree');
  if (!tree || tree.dataset.touchEnabled) return;

  tree.dataset.touchEnabled = 'true';

  let startY = 0;
  let scrollTop = 0;
  let isDown = false;

  tree.addEventListener(
    'touchstart',
    function (e) {
      isDown = true;
      startY = e.touches[0].pageY;
      scrollTop = tree.scrollTop;
    },
    { passive: true },
  );

  tree.addEventListener(
    'touchmove',
    function (e) {
      if (!isDown) return;

      e.stopPropagation();

      const y = e.touches[0].pageY;
      const walk = y - startY;
      tree.scrollTop = scrollTop - walk;
    },
    { passive: false },
  );

  tree.addEventListener('touchend', function () {
    isDown = false;
  });
}
setInterval(enableTreeTouchScroll, 1000);

