function updateTableheightsettings(event, ui) {
  if (ui && ui.size && ui.size.height) {
    tableContainerheight = ui.size.height;
    setItemcontainerHeight({ tableContainerheight, settableHeight: false });

    const data = {
      id: TABLE_CONTAINER_HEIGHT,
      value: tableContainerheight.toFixed(ROUNDOFF_UPTO),
    };
    updateSettings(data);
  }
}
