window.reloadOrdersettings = async function () {
  initSettings();
  if (window.ISTABLEBILL_DETAILS_CHANGED != undefined) {
    if (window.ISTABLEBILL_DETAILS_CHANGED) {
      const doesKotexists = iskotRunningfortables();
      if (doesKotexists) {
        const result = await Swal.fire({
          title: $.i18n.t('controller:orderController.Settings'),
          text: $.i18n.t(
            'controller:orderController.seemsLikeBillDetailsOnTableSettingIsChanged',
          ),
          width: '23em',
          confirmButtonText: $.i18n.t(
            'controller:swalDataTranslations.Continue',
          ),
          allowOutsideClick: false,
          allowEscapeKey: false,
          showCancelButton: true,
          customClass: {
            popup: 'tmbill-swal-pop-up',
          },
        });
        if (result.value) {
          addTables();
        }
      } else {
        addTables();
      }
    }

    window.ISTABLEBILL_DETAILS_CHANGED = false;
  }

  if (window.ISITEMS_DETAILSOPTION_CHANGED != undefined) {
    if (window.ISITEMS_DETAILSOPTION_CHANGED) {
      addItems();
    }
    window.ISITEMS_DETAILSOPTION_CHANGED = false;
  }

  if (window.SHORTCUTSCHANGED) {
    askForreload(
      $.i18n.t('controller:orderController.seemsLikeShortcutsAreChanged'),
    );
    window.SHORTCUTSCHANGED = false;
  }

  if (window.isappreloadneed) {
    setTimeout(() => {
      askForreload();
    }, 1000);
    window.isappreloadneed = false;
  }
};

