function restoreScroll(tableSelector) {
  const table = document.querySelector(tableSelector);
  if (!table) return;

  const container = table.closest('.kottableDiv');
  if (!container) return;

  if (container._lastScrollTop === undefined) return;

  requestAnimationFrame(function () {
    container.scrollTop = container._lastScrollTop;
  });
}
$(document).on('rowAddOrRemove', '#kotTable', function () {
  restoreScroll('#kotTable');
});

$(document).on('rowAddOrRemove', '#quickbillTable', function () {
  restoreScroll('#quickbillTable');
});

$(document).on('rowAddOrRemove', '#takeawaykotTable', function () {
  restoreScroll('#takeawaykotTable');
});

$(document).on('rowAddOrRemove', '#deliverykotTable', function () {
  restoreScroll('#deliverykotTable');
});
